INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "正面是东西朝向我们的那一边。", "primary_collocate": null, "pronunciation": "zhèng miàn", "ipa": "tʂəŋ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这座房子的正面有一扇大门。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把卡片正面朝上放在桌子上。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片要从正面拍，才看得清楚。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸的正面写着我的名字。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在汽车的正面，向我挥手。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬币的正面是一朵花。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的正面有一只小猫。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你从正面看，这个杯子很漂亮。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校正面有一棵很高的大树。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把画的正面对着墙放好。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西朝向我们的主要一面，与背面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f149c945-cf41-413d-b166-ecfc5601d7e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：zhèng miàn，指物体朝向我们的那一边。"}, {"text": "证件", "is_correct": false, "explanation": "证件（zhèngjiàn）与正面只有第二音节声母不同（j 与 m），意思是证件。"}, {"text": "政变", "is_correct": false, "explanation": "政变（zhèngbiàn）与正面只有第二音节声母不同（b 与 m），意思是政变。"}, {"text": "正念", "is_correct": false, "explanation": "正念（zhèngniàn）与正面只有第二音节声母不同（n 与 m），意思是专注于当下的心念。"}], "explanations": {"正面": "正确：zhèng miàn，指物体朝向我们的那一边。", "证件": "证件（zhèngjiàn）与正面只有第二音节声母不同（j 与 m），意思是证件。", "政变": "政变（zhèngbiàn）与正面只有第二音节声母不同（b 与 m），意思是政变。", "正念": "正念（zhèngniàn）与正面只有第二音节声母不同（n 与 m），意思是专注于当下的心念。"}, "sentence_index": null, "correct_answer": "正面"}, "level_3": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：“房子的正面有一扇大门”指房子朝向外面的一边，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不指位置，“颜色有一扇大门”不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指发出的声响，房子的声音不能“有一扇大门”，与句意不符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”一般只用于人或动物，不说房子的身高。"}], "explanations": {"正面": "正确：“房子的正面有一扇大门”指房子朝向外面的一边，与句意相符。", "颜色": "语义：“颜色”指色彩，不指位置，“颜色有一扇大门”不通。", "声音": "语义：“声音”指发出的声响，房子的声音不能“有一扇大门”，与句意不符。", "身高": "搭配：“身高”一般只用于人或动物，不说房子的身高。"}, "sentence_index": 0, "correct_answer": "正面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题有三个正面需要解决。", "explanation": "这里应该用〈方面〉。“正面”指物体朝前的一面或事情积极的一面，问题的各个方面要用“方面”。"}, {"text": "他的正面很好听。", "explanation": "这里应该用〈嗓子〉。“正面”指物体朝向我们的一面或事情积极的一面，不能指人的声音，说声音好听要用“嗓子”。"}, {"text": "我们要开一场正面的比赛。", "explanation": "这里应该用〈正式〉。“正面”不能修饰比赛，表示按规定、规范的要说“正式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：zhèng miàn，指物体朝向我们的那一边。"}, {"text": "正片", "is_correct": false, "explanation": "正片（zhèngpiàn）与正面只有第二音节声母不同（p 与 m），意思是正片。"}, {"text": "账面", "is_correct": false, "explanation": "账面（zhàngmiàn）与正面只有第一音节韵母不同（ang 与 eng），意思是账目上的记载。"}, {"text": "正电", "is_correct": false, "explanation": "正电（zhèngdiàn）与正面只有第二音节声母不同（d 与 m），意思是正电荷。"}], "explanations": {"正面": "正确：zhèng miàn，指物体朝向我们的那一边。", "正片": "正片（zhèngpiàn）与正面只有第二音节声母不同（p 与 m），意思是正片。", "账面": "账面（zhàngmiàn）与正面只有第一音节韵母不同（ang 与 eng），意思是账目上的记载。", "正电": "正电（zhèngdiàn）与正面只有第二音节声母不同（d 与 m），意思是正电荷。"}, "sentence_index": null, "correct_answer": "正面"}, "level_3": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：“衣服的正面有一只小猫”指衣服朝前的一面印有图案，与句意相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，衣服的味道不能“有一只小猫”，与句意不符。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指物体的长短，“长度有一只小猫”不通，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”一般用于人或动物，不说衣服的体重。"}], "explanations": {"正面": "正确：“衣服的正面有一只小猫”指衣服朝前的一面印有图案，与句意相符。", "味道": "语义：“味道”指气味或滋味，衣服的味道不能“有一只小猫”，与句意不符。", "长度": "语义：“长度”指物体的长短，“长度有一只小猫”不通，与句意不符。", "体重": "搭配：“体重”一般用于人或动物，不说衣服的体重。"}, "sentence_index": 6, "correct_answer": "正面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把正面戴在头上。", "explanation": "这里应该用〈帽子〉。“正面”是物体朝前的一面，不是能戴的东西。"}, {"text": "这个盒子的正面有三公斤。", "explanation": "这里应该用〈重量〉。“正面”指物体的一面，不能表示轻重。"}, {"text": "我每天从正面走到学校。", "explanation": "这里应该用〈家〉。“正面”是物体的一面，不是可以出发的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书得正面印着一只大鸟。", "corrected_sentence": "这本书的正面印着一只大鸟。", "error_description": "助词错误：表示领属要用「的」，不能用「得」，应说“这本书的正面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "椅子的正面们朝向门口，很显眼。", "corrected_sentence": "椅子的正面朝向门口，很显眼。", "error_description": "词缀错误：“们”只用于指人，不能加在“正面”后，应去掉，说“椅子的正面朝向门口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
