INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92685, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "公顷是用来量地有多大的一个单位。", "primary_collocate": null, "pronunciation": "gōng qǐng", "ipa": "kʊŋ˥ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个农场有五十公顷地。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家种了两公顷小麦。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的面积是十公顷。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一公顷等于一万平方米。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片森林有三百公顷。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民今年买了四公顷田。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学占地八十公顷。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖边有一公顷的草地。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村有一千公顷水稻田。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块地大约有六公顷。", "target_word": "公顷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "量土地大小的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92685, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公顷", "is_correct": true, "explanation": "正确答案：公顷，量土地面积的单位，一公顷等于一万平方米。"}, {"text": "公卿", "is_correct": false, "explanation": "gōngqīng（第一声）与 gōngqǐng（第三声）只有第二音节声调不同，“公卿”指位高权重的官员。"}, {"text": "共情", "is_correct": false, "explanation": "gòngqíng 与 gōngqǐng 两个音节的声调都不同，意思是共同体会他人的感受。"}, {"text": "共庆", "is_correct": false, "explanation": "gòngqìng 与 gōngqǐng 两个音节声调都不同，“共庆”意思是一起庆祝。"}], "explanations": {"公顷": "正确答案：公顷，量土地面积的单位，一公顷等于一万平方米。", "公卿": "gōngqīng（第一声）与 gōngqǐng（第三声）只有第二音节声调不同，“公卿”指位高权重的官员。", "共情": "gòngqíng 与 gōngqǐng 两个音节的声调都不同，意思是共同体会他人的感受。", "共庆": "gòngqìng 与 gōngqǐng 两个音节声调都不同，“共庆”意思是一起庆祝。"}, "sentence_index": null, "correct_answer": "公顷"}, "level_3": {"options": [{"text": "公顷", "is_correct": true, "explanation": "正确：公顷是土地面积单位，可以用来量“地”。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：“公斤”是重量单位，不能用来量农场的地。"}, {"text": "立方米", "is_correct": false, "explanation": "语义：“立方米”量体积，不能用来量土地的大小。"}, {"text": "升", "is_correct": false, "explanation": "搭配：“升”量液体的容积，不能与“地”搭配。"}], "explanations": {"公顷": "正确：公顷是土地面积单位，可以用来量“地”。", "公斤": "语义：“公斤”是重量单位，不能用来量农场的地。", "立方米": "语义：“立方米”量体积，不能用来量土地的大小。", "升": "搭配：“升”量液体的容积，不能与“地”搭配。"}, "sentence_index": 0, "correct_answer": "公顷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条高速公路长五十公顷。", "explanation": "这里应该用〈公里〉。公顷量面积，路的长度要用公里。"}, {"text": "我买了两公顷书。", "explanation": "这里应该用〈本〉。公顷是土地面积单位，书要用“本”来数。"}, {"text": "这间教室有五十公顷。", "explanation": "这里应该用〈平方米〉。公顷太大，教室的面积要用平方米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92685, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公顷", "is_correct": true, "explanation": "正确答案：公顷，量土地面积的单位，一公顷等于一万平方米。"}, {"text": "共青", "is_correct": false, "explanation": "gòngqīng 与 gōngqǐng 两个音节声调都不同，“共青”多用于“共青团”。"}, {"text": "恭敬", "is_correct": false, "explanation": "gōngjìng 与 gōngqǐng 第二音节声母 j/q 不同、声调也不同，“恭敬”指对人尊敬有礼。"}, {"text": "工勤", "is_correct": false, "explanation": "gōngqín（第二声）与 gōngqǐng（第三声）仅韵母 in 与 ing 不同且声调不同，“工勤”指工人和勤务人员。"}], "explanations": {"公顷": "正确答案：公顷，量土地面积的单位，一公顷等于一万平方米。", "共青": "gòngqīng 与 gōngqǐng 两个音节声调都不同，“共青”多用于“共青团”。", "恭敬": "gōngjìng 与 gōngqǐng 第二音节声母 j/q 不同、声调也不同，“恭敬”指对人尊敬有礼。", "工勤": "gōngqín（第二声）与 gōngqǐng（第三声）仅韵母 in 与 ing 不同且声调不同，“工勤”指工人和勤务人员。"}, "sentence_index": null, "correct_answer": "公顷"}, "level_3": {"options": [{"text": "公顷", "is_correct": true, "explanation": "正确：“占地”后接面积单位，公顷可以用来量大学的占地。"}, {"text": "吨", "is_correct": false, "explanation": "语义：“吨”是重量单位，不能说占地八十吨。"}, {"text": "瓶", "is_correct": false, "explanation": "搭配：“瓶”量装在瓶子里的东西，不能用来量占地。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”量车辆，不能用来量大学的占地。"}], "explanations": {"公顷": "正确：“占地”后接面积单位，公顷可以用来量大学的占地。", "吨": "语义：“吨”是重量单位，不能说占地八十吨。", "瓶": "搭配：“瓶”量装在瓶子里的东西，不能用来量占地。", "辆": "语义：“辆”量车辆，不能用来量大学的占地。"}, "sentence_index": 6, "correct_answer": "公顷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这桶油有五公顷。", "explanation": "这里应该用〈升〉。公顷量面积，液体的容量要用升。"}, {"text": "我买了一公顷鸡蛋。", "explanation": "这里应该用〈个〉。公顷是面积单位，鸡蛋要用“个”或“颗”来数。"}, {"text": "这根绳子长三公顷。", "explanation": "这里应该用〈米〉。公顷量面积，绳子的长度要用米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家的农场种了三个公顷玉米。", "corrected_sentence": "我家的农场种了三公顷玉米。", "error_description": "错误在“公顷”前多加了“个”。数词与“公顷”之间直接相连，不加“个”，应说“三公顷玉米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片果园大约有八只公顷。", "corrected_sentence": "这片果园大约有八公顷。", "error_description": "错误在“公顷”前用了量词“只”。“只”多用来量动物等，不能用来量面积，应说“八公顷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
