generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公顷", "is_correct": true, "explanation": "正确答案：公顷，面积单位，一公顷等于一万平方米。"}, {"text": "公卿", "is_correct": false, "explanation": "gōngqīng（第一声）与 gōngqǐng（第三声）只有第二音节声调不同，“公卿”指古代的高级官员。"}, {"text": "共庆", "is_correct": false, "explanation": "gòngqìng 与 gōngqǐng 两个音节声调都不同，“共庆”意思是一起庆祝。"}, {"text": "工勤", "is_correct": false, "explanation": "gōngqín（第二声）与 gōngqǐng（第三声）仅韵母 in 与 ing 不同且声调不同，“工勤”指工人和勤务人员。"}], "explanations": {"公顷": "正确答案：公顷，面积单位，一公顷等于一万平方米。", "公卿": "gōngqīng（第一声）与 gōngqǐng（第三声）只有第二音节声调不同，“公卿”指古代的高级官员。", "共庆": "gòngqìng 与 gōngqǐng 两个音节声调都不同，“共庆”意思是一起庆祝。", "工勤": "gōngqín（第二声）与 gōngqǐng（第三声）仅韵母 in 与 ing 不同且声调不同，“工勤”指工人和勤务人员。"}, "sentence_index": null, "correct_answer": "公顷"}, "level_3": {"options": [{"text": "公顷", "is_correct": true, "explanation": "正确：公顷是面积单位，可以用来量绿地的大小。"}, {"text": "斤", "is_correct": false, "explanation": "语义：“斤”是重量单位，不能用来量绿地。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用来量动物，不能与绿地的面积搭配。"}, {"text": "毫升", "is_correct": false, "explanation": "语义：“毫升”量液体的容积，不能用来量绿地。"}], "explanations": {"公顷": "正确：公顷是面积单位，可以用来量绿地的大小。", "斤": "语义：“斤”是重量单位，不能用来量绿地。", "只": "搭配：“只”多用来量动物，不能与绿地的面积搭配。", "毫升": "语义：“毫升”量液体的容积，不能用来量绿地。"}, "sentence_index": 0, "correct_answer": "公顷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸长三十公顷。", "explanation": "这里应该用〈厘米〉。公顷量面积，纸的长度要用厘米。"}, {"text": "我买了两公顷桌子。", "explanation": "这里应该用〈张〉。公顷是面积单位，桌子要用“张”来数。"}, {"text": "这段路长五千公顷。", "explanation": "这里应该用〈千米〉。公顷量面积，路的长度要用千米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
