INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个牧场有十二张公顷草地。", "corrected_sentence": "这个牧场有十二公顷草地。", "error_description": "错误在“公顷”前用了量词“张”。“张”用于纸张、桌子等平面的东西，不能用来量面积，应说“十二公顷草地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
