INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92688, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "破坏；使坏掉。", "primary_collocate": null, "pronunciation": "huǐ", "ipa": "xweɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "一次错误毁了他的好名声。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事毁了我们的计划。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏天气毁了整个周末。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一句话就能毁了朋友的感情。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让小事毁了你的心情。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雨毁了今天的比赛。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的坏习惯毁了他的身体。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个谎言毁了我们的信任。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要为了钱毁了自己的将来。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败毁不了他的梦想。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毁了", "label": "体标（了）"}, {"form": "毁掉", "label": "复合"}, {"form": "毁坏", "label": "复合"}], "register": "中性", "sense_fingerprint": "破坏名声、计划、心情等，使变坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f149c945-cf41-413d-b166-ecfc5601d7e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "毁", "is_correct": true, "explanation": "正确：huǐ，指破坏、使变坏。"}, {"text": "会", "is_correct": false, "explanation": "会（huì）与毁只有声调不同（第四声与第三声），意思是会合或会议。"}, {"text": "回", "is_correct": false, "explanation": "回（huí）与毁只有声调不同（第二声与第三声），意思是回来或回去。"}, {"text": "火", "is_correct": false, "explanation": "火（huǒ）与毁只有韵母不同（o 与 ei），声调相同，意思是火。"}, {"text": "灰", "is_correct": false, "explanation": "灰（huī）与毁只有声调不同（第一声与第三声），意思是灰尘或灰色。"}], "explanations": {"毁": "正确：huǐ，指破坏、使变坏。", "会": "会（huì）与毁只有声调不同（第四声与第三声），意思是会合或会议。", "回": "回（huí）与毁只有声调不同（第二声与第三声），意思是回来或回去。", "火": "火（huǒ）与毁只有韵母不同（o 与 ei），声调相同，意思是火。", "灰": "灰（huī）与毁只有声调不同（第一声与第三声），意思是灰尘或灰色。"}, "sentence_index": null, "correct_answer": "毁"}, "level_3": {"options": [{"text": "毁", "is_correct": true, "explanation": "正确：“一次错误毁了他的好名声”指错误破坏了名声，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，错误不能“唱”名声，与句意不符。"}, {"text": "叠", "is_correct": false, "explanation": "语义：“叠”指把东西折起来，“叠了好名声”不通，与句意不符。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”指用针线连接，一般不与“名声”搭配。"}], "explanations": {"毁": "正确：“一次错误毁了他的好名声”指错误破坏了名声，与句意相符。", "唱": "语义：“唱”是发出歌声，错误不能“唱”名声，与句意不符。", "叠": "语义：“叠”指把东西折起来，“叠了好名声”不通，与句意不符。", "缝": "搭配：“缝”指用针线连接，一般不与“名声”搭配。"}, "sentence_index": 0, "correct_answer": "毁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把旧桥毁好了。", "explanation": "这里应该用〈修〉。“毁”是破坏、使坏掉，不能表示修理，修桥要说“修好”。"}, {"text": "他帮我毁回了钥匙。", "explanation": "这里应该用〈找回〉。“毁”是破坏、使坏掉，不能表示找回丢失的东西，找回钥匙要说“找回”。"}, {"text": "她把窗户毁干净了。", "explanation": "这里应该用〈擦〉。“毁”是破坏、使坏掉，不能表示擦拭，擦干净要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92688, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "毁", "is_correct": true, "explanation": "正确：huǐ，指破坏、使变坏。"}, {"text": "水", "is_correct": false, "explanation": "水（shuǐ）与毁只有声母不同（sh 与 h），声调相同，意思是水。"}, {"text": "鬼", "is_correct": false, "explanation": "鬼（guǐ）与毁只有声母不同（g 与 h），声调相同，意思是鬼。"}, {"text": "辉", "is_correct": false, "explanation": "辉（huī）与毁只有声调不同（第一声与第三声），意思是光辉。"}, {"text": "惠", "is_correct": false, "explanation": "惠（huì）与毁只有声调不同（第四声与第三声），意思是恩惠。"}], "explanations": {"毁": "正确：huǐ，指破坏、使变坏。", "水": "水（shuǐ）与毁只有声母不同（sh 与 h），声调相同，意思是水。", "鬼": "鬼（guǐ）与毁只有声母不同（g 与 h），声调相同，意思是鬼。", "辉": "辉（huī）与毁只有声调不同（第一声与第三声），意思是光辉。", "惠": "惠（huì）与毁只有声调不同（第四声与第三声），意思是恩惠。"}, "sentence_index": null, "correct_answer": "毁"}, "level_3": {"options": [{"text": "毁", "is_correct": true, "explanation": "正确：“他的坏习惯毁了他的身体”指坏习惯损害健康，与句意相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指用布等摩擦，坏习惯不能“擦”身体，与句意不符。"}, {"text": "装", "is_correct": false, "explanation": "语义：“装”指放进或假扮，与“坏习惯”损害身体的语境不符，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」指用水去除污垢，「坏习惯」不能「洗」身体，与句意不符。"}], "explanations": {"毁": "正确：“他的坏习惯毁了他的身体”指坏习惯损害健康，与句意相符。", "擦": "语义：“擦”指用布等摩擦，坏习惯不能“擦”身体，与句意不符。", "装": "语义：“装”指放进或假扮，与“坏习惯”损害身体的语境不符，句意不通。", "洗": "语义：「洗」指用水去除污垢，「坏习惯」不能「洗」身体，与句意不符。"}, "sentence_index": 6, "correct_answer": "毁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把花毁给了妈妈。", "explanation": "这里应该用〈送〉。“毁”是弄坏、使坏掉，不能表示给予，把东西送人要说“送给”。"}, {"text": "我把书毁进了书包。", "explanation": "这里应该用〈放〉。“毁”是弄坏、使坏掉，不能表示放置，把书放进去要说“放进”。"}, {"text": "他把碗毁干净了。", "explanation": "这里应该用〈洗〉。“毁”是弄坏、使坏掉，不能表示清洗，洗碗要说“洗干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一次误会毁了了我们的友谊。", "corrected_sentence": "一次误会毁了我们的友谊。", "error_description": "体标错误：“毁”后已经有“了”，又多加了一个“了”，应只用一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次争吵了毁我们的感情。", "corrected_sentence": "这次争吵毁了我们的感情。", "error_description": "体标位置错误：“了”应放在动词“毁”之后，不能放在“毁”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7cd1bd-8c76-42a8-bd2c-cea8c80fa130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
