INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92689, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出租是把东西借给别人用，别人要给钱。", "primary_collocate": null, "pronunciation": "chū zū", "ipa": "ʈʂʰu˥ tsu˥", "syllable_count": 2, "sentences": [{"text": "这栋楼的二层出租，欢迎来看。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打算出租一间空房。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有人出租帐篷。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友出租着一套大房子。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出租过一个小店面。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些伞可以出租，一天五元。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿意把房子出租给陌生人。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边有很多房子出租。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店出租各种运动用品。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想出租我的车库。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出租了", "label": "体标"}, {"form": "出租着", "label": "体标"}, {"form": "出租过", "label": "体标"}, {"form": "出租屋", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西借给别人用并收钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出门", "is_correct": false, "explanation": "语义：“出门”指人离开家，“二层”不能出门。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”的主语只能是人，不能用于楼层。"}, {"text": "出租", "is_correct": true, "explanation": "“出租”指收取租金把房子借给别人用，与“欢迎来看”的语境相符，是正确答案。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指生命诞生，不能用于楼层。"}], "explanations": {"出门": "语义：“出门”指人离开家，“二层”不能出门。", "出差": "搭配：“出差”的主语只能是人，不能用于楼层。", "出租": "“出租”指收取租金把房子借给别人用，与“欢迎来看”的语境相符，是正确答案。", "出生": "语义：“出生”指生命诞生，不能用于楼层。"}, "sentence_index": 0, "correct_answer": "出租"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民出租新鲜蔬菜。", "explanation": "这里应该用〈出售〉。“出租”的东西要还回来，蔬菜吃掉了就不能出租，只能说“出售”。"}, {"text": "他出租了一个玩笑。", "explanation": "这里应该用〈讲〉。“出租”只能用于可借出的物品，不能用于玩笑。"}, {"text": "面包店每天出租新鲜面包。", "explanation": "这里应该用〈出售〉。“出租”的东西用完要还回来，面包吃掉就没有了，只能说“出售”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除，不能用来说把房子交给别人使用。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”不能带“给”引出的接受者，不能用于“把……给”结构。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽培植物，“把房子种给陌生人”说不通。"}, {"text": "出租", "is_correct": true, "explanation": "“出租”指收取租金把房子借给别人用，与“把房子……给陌生人”搭配，是正确答案。"}], "explanations": {"拆": "语义：“拆”指拆除，不能用来说把房子交给别人使用。", "参观": "配价：“参观”不能带“给”引出的接受者，不能用于“把……给”结构。", "种": "语义：“种”指栽培植物，“把房子种给陌生人”说不通。", "出租": "“出租”指收取租金把房子借给别人用，与“把房子……给陌生人”搭配，是正确答案。"}, "sentence_index": 6, "correct_answer": "出租"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出租了一个假期。", "explanation": "这里应该用〈度过〉。“出租”只能用于可借给别人用的物品，假期不能出租。"}, {"text": "他出租了一个决定。", "explanation": "这里应该用〈做〉。“出租”的对象是物品，“决定”不能出租。"}, {"text": "我想出租这场雨。", "explanation": "这里应该用〈躲避〉。“出租”指收取租金把物品借给别人用，雨不能借给别人，应说“躲避这场雨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区的车位出租了给附近的司机。", "corrected_sentence": "我们小区的车位出租给了附近的司机。", "error_description": "“了”位置错误：“出租给了”的“了”应放在“给”之后，“出租了给”不成立，正确说法是“出租给了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些工具可以出租给了工人。", "corrected_sentence": "这些工具可以出租给工人。", "error_description": "“可以”表示可能，不能与表示完成的“了”同用：“可以出租给了工人”应删去“了”，正确说法是“可以出租给工人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92690, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92690, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92690, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收取租金，把房屋、车辆、物品等借给别人使用。", "primary_collocate": null, "pronunciation": "chū zū", "ipa": "ʈʂʰu˥ tsu˥", "syllable_count": 2, "sentences": [{"text": "他把房子出租给了一位学生。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间房子出租，每月两千元。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生想出租自己的车。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有自行车出租。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出租了一间小房间。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下的商店正在出租。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的院子不出租。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠出租房子赚钱。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套公寓只出租给学生。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板出租了三辆汽车。", "target_word": "出租", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出租了", "label": "体标"}, {"form": "出租着", "label": "体标"}, {"form": "出租过", "label": "体标"}, {"form": "出租屋", "label": "复合"}], "register": "中性", "sense_fingerprint": "收租金把房屋车辆物品借给别人用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种", "is_correct": false, "explanation": "语义：“种”指栽培植物，不能用来说把房子交给别人使用。"}, {"text": "出租", "is_correct": true, "explanation": "“出租”指收取租金把房子借给别人用，与“给了一位学生”搭配，是正确答案。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“房子”不搭，“把房子吃给了一位学生”说不通。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”不能带“给”引出的接受者，不能用于“把……给”结构。"}], "explanations": {"种": "语义：“种”指栽培植物，不能用来说把房子交给别人使用。", "出租": "“出租”指收取租金把房子借给别人用，与“给了一位学生”搭配，是正确答案。", "吃": "语义：“吃”与“房子”不搭，“把房子吃给了一位学生”说不通。", "参观": "配价：“参观”不能带“给”引出的接受者，不能用于“把……给”结构。"}, "sentence_index": 0, "correct_answer": "出租"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店在出租新鲜水果。", "explanation": "这里应该用〈出售〉。“出租”要求物品能够归还，水果吃掉就没了，只能说“出售”。"}, {"text": "他把钱出租给了朋友。", "explanation": "这里应该用〈借〉。“出租”的对象是房屋、车辆、物品等，钱不能出租，应说“把钱借给了朋友”。"}, {"text": "这家超市出租免费的饮料。", "explanation": "这里应该用〈赠送〉。“出租”要收取租金，不能用于免费的东西，免费给人应说“赠送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出门", "is_correct": false, "explanation": "语义：“出门”指人外出，院子不能出门。"}, {"text": "出租", "is_correct": true, "explanation": "“出租”指收取租金把院子借给别人用，这里说“院子不出租”，是正确答案。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”的主语必须是人，不能用于“院子”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指生命诞生，不能用于院子。"}], "explanations": {"出门": "语义：“出门”指人外出，院子不能出门。", "出租": "“出租”指收取租金把院子借给别人用，这里说“院子不出租”，是正确答案。", "出差": "搭配：“出差”的主语必须是人，不能用于“院子”。", "出生": "语义：“出生”指生命诞生，不能用于院子。"}, "sentence_index": 6, "correct_answer": "出租"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天出租我去学校。", "explanation": "这里应该用〈送〉。“出租”的对象是物品，不能用于人。"}, {"text": "学校今天出租了一场考试。", "explanation": "这里应该用〈举行〉。“出租”只用于可以借出的物品，不能用于活动。"}, {"text": "他出租了一个好主意。", "explanation": "这里应该用〈想出〉。“出租”只用于可以借给别人使用的房屋、车辆、物品，主意不能出租。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把车库出租了邻居。", "corrected_sentence": "他把车库出租给了邻居。", "error_description": "漏掉“给”：“出租”后面要用“出租给”引出承租人，不能直接说“出租了邻居”，正确说法是“出租给了邻居”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的店铺出租了给一家咖啡馆。", "corrected_sentence": "她的店铺出租给了一家咖啡馆。", "error_description": "“了”位置错误：“出租给了”的“了”应放在“给”之后，“出租了给”不成立，正确说法是“出租给了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92691, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
