INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92691, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "演讲是站在很多人前面，大声讲出自己的想法。", "primary_collocate": null, "pronunciation": "yǎn jiǎng", "ipa": "jɛn˨˩˦ tɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他站在台上，大声地演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人看着他，他一点儿也不怕，大声演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请小明到前面给大家演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次在三百个人面前演讲，很紧张。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着话筒，站起来开始演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们一个一个上台演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她演讲的时候，声音很大，大家都听得清楚。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场上有人在对着人群演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不敢在这么多人面前演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他演讲了十分钟，大家都笑了。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演讲了", "label": "体标"}, {"form": "演讲过", "label": "体标"}, {"form": "演讲者", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：站在众人面前大声讲出自己的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演讲", "is_correct": true, "explanation": "正确答案。演讲指站在众人前大声讲出自己的想法，与“站在台上，大声地”相合。"}, {"text": "默念", "is_correct": false, "explanation": "语义：“默念”指不出声地念，与“大声地”矛盾。"}, {"text": "低语", "is_correct": false, "explanation": "语义：“低语”指小声说话，与“大声地”矛盾。"}, {"text": "静坐", "is_correct": false, "explanation": "搭配：“静坐”指安静地坐着，不能用“大声地”修饰。"}], "explanations": {"演讲": "正确答案。演讲指站在众人前大声讲出自己的想法，与“站在台上，大声地”相合。", "默念": "语义：“默念”指不出声地念，与“大声地”矛盾。", "低语": "语义：“低语”指小声说话，与“大声地”矛盾。", "静坐": "搭配：“静坐”指安静地坐着，不能用“大声地”修饰。"}, "sentence_index": 0, "correct_answer": "演讲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个剧团周末在广场上演讲，很多人来看。", "explanation": "这里应该用〈演出〉。演讲是一个人对众人讲出自己的想法，不用于剧团的戏剧或节目表演。"}, {"text": "孩子在台上演讲了一首诗。", "explanation": "这里应该用〈朗诵〉。演讲是讲出自己的想法，不用于念现成的诗。"}, {"text": "她在音乐会上演讲了一首歌。", "explanation": "这里应该用〈演唱〉。演讲用于发表见解，不用于唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演讲", "is_correct": true, "explanation": "正确答案。演讲指站在众人前讲话，与“声音很大，大家都听得清楚”相合。"}, {"text": "默读", "is_correct": false, "explanation": "语义：“默读”不出声，与“声音很大”矛盾。"}, {"text": "耳语", "is_correct": false, "explanation": "语义：“耳语”指贴着耳朵小声说，与“声音很大”矛盾。"}, {"text": "低吟", "is_correct": false, "explanation": "语域：“低吟”偏文学用语，口语叙述中很少用；且低吟声音轻，与“声音很大”矛盾。"}], "explanations": {"演讲": "正确答案。演讲指站在众人前讲话，与“声音很大，大家都听得清楚”相合。", "默读": "语义：“默读”不出声，与“声音很大”矛盾。", "耳语": "语义：“耳语”指贴着耳朵小声说，与“声音很大”矛盾。", "低吟": "语域：“低吟”偏文学用语，口语叙述中很少用；且低吟声音轻，与“声音很大”矛盾。"}, "sentence_index": 6, "correct_answer": "演讲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在晚会上演讲了一支舞，大家都笑了。", "explanation": "这里应该用〈跳〉。演讲是站在众人前发表见解，不用于跳舞。"}, {"text": "妈妈每晚给孩子演讲故事。", "explanation": "这里应该用〈讲〉。“讲故事”是固定说法；演讲是站在众人前发表想法，不用于给孩子讲故事。"}, {"text": "他在舞台上演讲了小品。", "explanation": "这里应该用〈表演〉。演讲指发表见解，不能用来指表演小品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
