INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92692, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在公众面前就某个问题发表见解。", "primary_collocate": null, "pronunciation": "yǎn jiǎng", "ipa": "jɛn˨˩˦ tɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "校长在大会上就环保问题演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受邀到大学里演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长明天要在广场上就交通问题演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位专家常常到各地演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他就教育问题向大家演讲了半个小时。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她曾经在联合国演讲过。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者们都来听总统演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想就这个问题在公司里演讲一次。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天晚上有一位作家来我们学校演讲。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在会上演讲，谈了公司明年的想法。", "target_word": "演讲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演讲了", "label": "体标"}, {"form": "演讲过", "label": "体标"}, {"form": "演讲者", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：在公众面前就某个问题发表见解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演讲", "is_correct": true, "explanation": "正确答案。演讲指在公众面前就某个问题发表见解，与“在大会上就环保问题”相合。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：校长在大会上就环保问题哭泣，与“发表见解”明显不合。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与“就环保问题”明显不合，不是发表见解的行为。"}, {"text": "表演", "is_correct": false, "explanation": "搭配：“表演”多指舞台演出，不能与“就环保问题”搭配。"}], "explanations": {"演讲": "正确答案。演讲指在公众面前就某个问题发表见解，与“在大会上就环保问题”相合。", "哭泣": "语义：校长在大会上就环保问题哭泣，与“发表见解”明显不合。", "跳舞": "语义：“跳舞”与“就环保问题”明显不合，不是发表见解的行为。", "表演": "搭配：“表演”多指舞台演出，不能与“就环保问题”搭配。"}, "sentence_index": 0, "correct_answer": "演讲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个剧团常常到各地演讲。", "explanation": "这里应该用〈演出〉。剧团是表演节目，不是在公众面前就问题发表见解，所以不用演讲。"}, {"text": "歌手常常到各地演讲新歌。", "explanation": "这里应该用〈演唱〉。演讲是在公众面前就问题发表见解，不用于唱歌。"}, {"text": "他负责演讲晚会。", "explanation": "这里应该用〈主持〉。演讲是发表见解，不是主持晚会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演讲", "is_correct": true, "explanation": "正确答案。“听”后接的是演讲，符合“记者们都来听总统”的语境。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：记者不会来听总统睡觉，与“来听”矛盾。"}, {"text": "打球", "is_correct": false, "explanation": "搭配：“听”后不接“打球”这类动作，应接讲话或演讲。"}, {"text": "烧菜", "is_correct": false, "explanation": "语义：烧菜没有内容可听，与“来听”矛盾。"}], "explanations": {"演讲": "正确答案。“听”后接的是演讲，符合“记者们都来听总统”的语境。", "睡觉": "语义：记者不会来听总统睡觉，与“来听”矛盾。", "打球": "搭配：“听”后不接“打球”这类动作，应接讲话或演讲。", "烧菜": "语义：烧菜没有内容可听，与“来听”矛盾。"}, "sentence_index": 6, "correct_answer": "演讲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在学校演讲了一场比赛，大家都很兴奋。", "explanation": "这里应该用〈举办〉。演讲是一人站在众人前发表见解，不能说“演讲”一场比赛。"}, {"text": "大家在会上演讲了一顿午饭。", "explanation": "这里应该用〈吃〉。演讲是站在众人前发表见解，不能用于吃饭。"}, {"text": "他在超市演讲了一份购物清单。", "explanation": "这里应该用〈朗读〉，指照着文字读出来。演讲是在众人前就问题发表见解，不用于读购物清单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
