INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92693, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "刑罚是对做了坏事的人的惩罚，比如把他关起来。", "primary_collocate": null, "pronunciation": "xíng fá", "ipa": "ɕiŋ˧˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "做了坏事的人，要受到刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑罚的目的，是让人不再做坏事。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的刑罚很重。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐牢是一种刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为偷东西，受了刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代有很多可怕的刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轻微的错误，不应受到过重的刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "furigana": "qīng wēi de cuò wù bù yīng shòu dào guò zhòng de xíng fá", "sentence_source": "generated"}, {"text": "对小偷来说，关起来是常见的刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他害怕刑罚，所以主动说出了真话。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的错误，要有不同的刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "刑罰", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对做坏事的人的惩罚，如关押", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刑罚", "is_correct": true, "explanation": "正确。刑罚是法律对做坏事的人的处罚，与“做了坏事”的语境相符。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：奖励是对好行为的回报，与“做了坏事”的语境相反。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“受到”后不接“工资”，工资应说“领”或“拿”。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：荣誉授予做了好事的人，与“做了坏事”的语境冲突。"}], "explanations": {"刑罚": "正确。刑罚是法律对做坏事的人的处罚，与“做了坏事”的语境相符。", "奖励": "语义：奖励是对好行为的回报，与“做了坏事”的语境相反。", "工资": "搭配：“受到”后不接“工资”，工资应说“领”或“拿”。", "荣誉": "语义：荣誉授予做了好事的人，与“做了坏事”的语境冲突。"}, "sentence_index": 0, "correct_answer": "刑罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他主动帮助同学，却受到了刑罚。", "explanation": "语义：刑罚是对做了坏事的人的惩罚，帮助同学是好事，与语境相反。"}, {"text": "他考了满分，老师却给了他一次刑罚。", "explanation": "语义：刑罚是对做了坏事的人的惩罚，考满分是好事，不应受刑罚。"}, {"text": "法官刑罚了那个小偷，让他坐了三年牢。", "explanation": "刑罚是名词，不能当动词用。这里应说〈判处〉刑罚，或直接说〈判刑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刑罚", "is_correct": true, "explanation": "正确。刑罚是处罚，与“轻微的错误”和“不应过重”的语境相符。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“过重”修饰礼物不自然，礼物不用重量来形容，“过重的礼物”说不通。"}, {"text": "勋章", "is_correct": false, "explanation": "语义：勋章是授予有功者的，与“轻微的错误”不相配。"}, {"text": "薪水", "is_correct": false, "explanation": "搭配：“受到”不接“过重的薪水”，薪水是劳动报酬，不能被“受到”。"}], "explanations": {"刑罚": "正确。刑罚是处罚，与“轻微的错误”和“不应过重”的语境相符。", "礼物": "搭配：“过重”修饰礼物不自然，礼物不用重量来形容，“过重的礼物”说不通。", "勋章": "语义：勋章是授予有功者的，与“轻微的错误”不相配。", "薪水": "搭配：“受到”不接“过重的薪水”，薪水是劳动报酬，不能被“受到”。"}, "sentence_index": 6, "correct_answer": "刑罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天准时完成工作，领导却给他一次刑罚。", "explanation": "语义：刑罚是对做了坏事的人的惩罚，按时完成工作不应受刑罚。"}, {"text": "那个运动员赢了刑罚，所以很高兴。", "explanation": "这里误把刑罚当成了〈奖项〉。刑罚是法院对犯罪者施加的处罚，不能像奖牌那样被“赢”。"}, {"text": "他把捡到的钱包还给了失主，却受到了刑罚。", "explanation": "语义：刑罚是对做了坏事的人的惩罚，归还钱包是好事，与语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小偷受到了一本刑罚。", "corrected_sentence": "这个小偷受到了一种刑罚。", "error_description": "量词错误：刑罚应用量词〈种〉，应说“一种刑罚”。“本”用于书册，不能修饰刑罚。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他因为打人，被受到了刑罚。", "corrected_sentence": "他因为打人，受到了刑罚。", "error_description": "多加了“被”。“受到”本身已表示被动，再加“被”形成重复，应去掉“被”，说“受到了刑罚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92694, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92694, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92694, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法院依法对犯罪的人所施加的处罚。", "primary_collocate": null, "pronunciation": "xíng fá", "ipa": "ɕiŋ˧˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "法院依照法律，对罪犯判处刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种犯罪的刑罚是三年以上有期徒刑。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年人犯罪，可以减轻刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经受完了刑罚，回到了家里。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，杀人要受到严厉的刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "死刑是最重的一种刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官根据情况，决定对他适用什么刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑罚必须由法院依法决定。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子的刑罚还没有确定。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些国家已经取消了死刑这种刑罚。", "target_word": "刑罚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "刑罰", "label": "繁体"}], "register": "书面", "sense_fingerprint": "法院依法对犯罪者施加的处罚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刑罚", "is_correct": true, "explanation": "正确。法院判处的对象是刑罚，与“依照法律对罪犯判处”相符。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：判处的是刑罚，荣誉不是可以被判处的东西。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“判处”不接礼物，礼物不是法律上的处罚。"}, {"text": "薪水", "is_correct": false, "explanation": "搭配：“判处薪水”不成立，薪水不能被判处。"}], "explanations": {"刑罚": "正确。法院判处的对象是刑罚，与“依照法律对罪犯判处”相符。", "荣誉": "语义：判处的是刑罚，荣誉不是可以被判处的东西。", "礼物": "搭配：“判处”不接礼物，礼物不是法律上的处罚。", "薪水": "搭配：“判处薪水”不成立，薪水不能被判处。"}, "sentence_index": 0, "correct_answer": "刑罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小王迟到了，公司决定扣他的工资作为刑罚。", "explanation": "这里应该用〈处罚〉。刑罚是法院依法判决的，公司扣工资属于一般的处罚，不叫刑罚。"}, {"text": "他因为乱扔垃圾，被城管处以刑罚。", "explanation": "这里应该用〈罚款〉。乱扔垃圾属于行政违法，城管施加的是罚款，不是刑罚。"}, {"text": "他被刑罚了三年。", "explanation": "刑罚是名词，不能用作动词。这里应说〈判刑〉，即“他被判刑三年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刑罚", "is_correct": true, "explanation": "正确。法官决定适用的是法律规定的刑罚，与“根据情况”的判决语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“适用”接的是法律、规定或处罚，不接颜色。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“适用什么玩具”说不通，玩具与法律判决无关。"}, {"text": "食物", "is_correct": false, "explanation": "语义：适用指法律或规则的运用，食物与法官判案无关。"}], "explanations": {"刑罚": "正确。法官决定适用的是法律规定的刑罚，与“根据情况”的判决语境相符。", "颜色": "搭配：“适用”接的是法律、规定或处罚，不接颜色。", "玩具": "搭配：“适用什么玩具”说不通，玩具与法律判决无关。", "食物": "语义：适用指法律或规则的运用，食物与法官判案无关。"}, "sentence_index": 6, "correct_answer": "刑罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师因为学生吵闹，对他们施加了刑罚。", "explanation": "这里应用〈管教〉或〈批评〉。刑罚指法院依法对犯罪者判处的处罚，老师管教学生不算刑罚。"}, {"text": "他领到了刑罚的奖金。", "explanation": "刑罚是法院对罪犯施加的处罚，与奖励相反，不能修饰奖金；表示奖励时不能用“刑罚”。"}, {"text": "他因为在网上骂人，被网站处以刑罚，封号一周。", "explanation": "这里应该用〈处罚〉。网站封号属于平台规则下的处罚，不是法院依法判处的刑罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有期徒刑是一条常见的刑罚。", "corrected_sentence": "有期徒刑是一种常见的刑罚。", "error_description": "量词错误：刑罚是一类处罚，量词应用〈种〉；“条”用于细长的物体，不能修饰刑罚。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院对他判处了一条刑罚。", "corrected_sentence": "法院对他判处了一种刑罚。", "error_description": "量词错误：刑罚是一类处罚，量词应用〈种〉，应说“一种刑罚”；“条”用于细长的物体，不能修饰刑罚。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
