INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92695, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "画面是眼睛看到的图画一样的样子。", "primary_collocate": null, "pronunciation": "huà miàn", "ipa": "xwa˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "窗外的雪景像一幅美丽的画面。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着那个画面，我想起了小时候。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边日落的画面让我很难忘。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上玩，画面很温暖。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我脑子里常出现那天的画面。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夕阳下，老人和狗散步，画面很美。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子里的画面像一首安静的诗。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把看到的画面都写进了日记。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，街上的画面特别安静。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家人吃饭的画面让她很感动。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一幅画面", "label": "量词"}, {"form": "一个画面", "label": "量词"}, {"form": "畫面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "眼前看到或脑中想起的像图画一样的景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92695, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下面", "is_correct": false, "explanation": "下面 xiàmiàn 与 画面 huàmiàn 第二音节相同，第一音节声调相同而声母和介音不同（xi 与 hu），意思是下边。"}, {"text": "画面", "is_correct": true, "explanation": "正确答案。画面 huàmiàn，指眼前或脑中看到的图画一样的景象。"}, {"text": "画线", "is_correct": false, "explanation": "画线 huàxiàn 与 画面 的第二音节只有声母不同（x 与 m），意思是画出线条。"}, {"text": "会面", "is_correct": false, "explanation": "会面 huìmiàn 与 画面 的第一音节只有韵母不同（i 与 a），意思是见面、会见。"}], "explanations": {"下面": "下面 xiàmiàn 与 画面 huàmiàn 第二音节相同，第一音节声调相同而声母和介音不同（xi 与 hu），意思是下边。", "画面": "正确答案。画面 huàmiàn，指眼前或脑中看到的图画一样的景象。", "画线": "画线 huàxiàn 与 画面 的第二音节只有声母不同（x 与 m），意思是画出线条。", "会面": "会面 huìmiàn 与 画面 的第一音节只有韵母不同（i 与 a），意思是见面、会见。"}, "sentence_index": null, "correct_answer": "画面"}, "level_3": {"options": [{"text": "文字", "is_correct": false, "explanation": "语义：文字是符号，不是可看见的图画，与「像一幅美丽的」所描写的雪景不合。"}, {"text": "画面", "is_correct": true, "explanation": "正确。画面指眼前或脑中看到的图画一样的景象，可以用「一幅」计量，与雪景相合。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「幅」用于图画一类的东西，不能说「一幅美丽的脚步」。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉的，与「雪景」这种看得见的景象相冲突。"}], "explanations": {"文字": "语义：文字是符号，不是可看见的图画，与「像一幅美丽的」所描写的雪景不合。", "画面": "正确。画面指眼前或脑中看到的图画一样的景象，可以用「一幅」计量，与雪景相合。", "脚步": "搭配：「幅」用于图画一类的东西，不能说「一幅美丽的脚步」。", "声音": "语义：声音是听觉的，与「雪景」这种看得见的景象相冲突。"}, "sentence_index": 0, "correct_answer": "画面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这幅画面挂在墙上。", "explanation": "这里应该用〈画〉。画面指眼前或脑中看到的景象，不能挂在墙上；挂的是实物图画。"}, {"text": "他脑子里闪过一只画面。", "explanation": "这里应该用〈个〉或〈幅〉。画面不用“只”计量，“只”多用于动物或成对的物。"}, {"text": "剧组在海边搭了一个画面。", "explanation": "这里应该用〈场景〉。场景可以搭建布置，画面是看到的样子，不能搭建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92695, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挂面", "is_correct": false, "explanation": "挂面 guàmiàn 与 画面 的第一音节只有声母不同（g 与 h），意思是晾干的细面条。"}, {"text": "画面", "is_correct": true, "explanation": "正确答案。画面 huàmiàn，指眼前或脑中看到的图画一样的景象。"}, {"text": "和面", "is_correct": false, "explanation": "和面 huómiàn 与 画面 的第一音节韵母不同（o 与 a），声调也不同（二声与四声）。意思是加水揉面粉。"}, {"text": "画片", "is_correct": false, "explanation": "画片 huàpiàn 与 画面 的第二音节只有声母不同（p 与 m），意思是印有图画的小卡片。"}], "explanations": {"挂面": "挂面 guàmiàn 与 画面 的第一音节只有声母不同（g 与 h），意思是晾干的细面条。", "画面": "正确答案。画面 huàmiàn，指眼前或脑中看到的图画一样的景象。", "和面": "和面 huómiàn 与 画面 的第一音节韵母不同（o 与 a），声调也不同（二声与四声）。意思是加水揉面粉。", "画片": "画片 huàpiàn 与 画面 的第二音节只有声母不同（p 与 m），意思是印有图画的小卡片。"}, "sentence_index": null, "correct_answer": "画面"}, "level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "语义：人口是人的数量，不能像一首安静的诗，与「村子里的」所描写的景象冲突。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格是数额，不能像一首安静的诗，与「村子里的」所描写的景象不合。"}, {"text": "画面", "is_correct": true, "explanation": "正确。画面指眼前看到的景象，村子的景象可以像一首安静的诗。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是一种活动，不是可看见的景象，不能像一首诗。"}], "explanations": {"人口": "语义：人口是人的数量，不能像一首安静的诗，与「村子里的」所描写的景象冲突。", "价格": "搭配：价格是数额，不能像一首安静的诗，与「村子里的」所描写的景象不合。", "画面": "正确。画面指眼前看到的景象，村子的景象可以像一首安静的诗。", "考试": "语义：考试是一种活动，不是可看见的景象，不能像一首诗。"}, "sentence_index": 6, "correct_answer": "画面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事的画面很复杂，大家都不知道该怎么办。", "explanation": "这里应该用〈情况〉。情况可以指事态复杂，画面是看到的景象，不能用来形容抽象的事情状况。"}, {"text": "这段画面很好听。", "explanation": "这里应该用〈音乐〉。“好听”用于声音和音乐，画面是看到的景象，不能用“好听”来形容。"}, {"text": "这个画面性格很复杂。", "explanation": "这里应该用〈人物〉。性格是人或角色才有的，画面是眼前或脑中的景象，不能说它有性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只温暖的画面一直留在我脑子里。", "corrected_sentence": "那个温暖的画面一直留在我脑子里。", "error_description": "错误在“画面”的量词。“只”用于动物或成对的物，“画面”应用“个”或“幅”。正确的说法是：那个温暖的画面一直留在我脑子里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人和狗散步地画面让我很难忘。", "corrected_sentence": "老人和狗散步的画面让我很难忘。", "error_description": "错误在修饰“画面”的成分。“老人和狗散步”修饰名词“画面”，中间应用“的”，不能用“地”（“地”用在动词前）。正确的说法是：老人和狗散步的画面让我很难忘。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
