INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图画、电影或电视屏幕上显现的景象。", "primary_collocate": null, "pronunciation": "huà miàn", "ipa": "xwa˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "电视的画面突然黑了。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的画面很清楚。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机坏了，屏幕上的画面不动。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网速太慢，视频画面一直停着。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的画面和声音配合得很好。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视画面上出现了一行字。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片的画面不够亮。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电视的画面比旧的好看多了。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画面一换，演员就出现在海边。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电视画面调大一点。", "target_word": "画面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一幅画面", "label": "量词"}, {"form": "一个画面", "label": "量词"}, {"form": "畫面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电影、电视、屏幕或图画上显示出来的景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8435ceb-555a-41a7-9e7c-23c1661a3389') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92696, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下面", "is_correct": false, "explanation": "下面 xiàmiàn 与 画面 huàmiàn 第二音节相同，第一音节声调相同而声母和介音不同（xi 与 hu），意思是下边。"}, {"text": "画面", "is_correct": true, "explanation": "正确答案。画面 huàmiàn，指屏幕或图画上显示出来的景象。"}, {"text": "画线", "is_correct": false, "explanation": "画线 huàxiàn 与 画面 的第二音节只有声母不同（x 与 m），意思是画出线条。"}, {"text": "画片", "is_correct": false, "explanation": "画片 huàpiàn 与 画面 的第二音节只有声母不同（p 与 m），意思是印有图画的小卡片。"}], "explanations": {"下面": "下面 xiàmiàn 与 画面 huàmiàn 第二音节相同，第一音节声调相同而声母和介音不同（xi 与 hu），意思是下边。", "画面": "正确答案。画面 huàmiàn，指屏幕或图画上显示出来的景象。", "画线": "画线 huàxiàn 与 画面 的第二音节只有声母不同（x 与 m），意思是画出线条。", "画片": "画片 huàpiàn 与 画面 的第二音节只有声母不同（p 与 m），意思是印有图画的小卡片。"}, "sentence_index": null, "correct_answer": "画面"}, "level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道是用嘴尝的，不能“黑了”，与电视屏幕变黑的描述不合。"}, {"text": "画面", "is_correct": true, "explanation": "正确。画面指电视屏幕上显示的影像，影像可以突然黑掉。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格可以涨跌，不能说“黑了”，与“突然黑了”搭配不当。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉的，不能“黑了”，与电视屏幕变黑的描述冲突。"}], "explanations": {"味道": "语义：味道是用嘴尝的，不能“黑了”，与电视屏幕变黑的描述不合。", "画面": "正确。画面指电视屏幕上显示的影像，影像可以突然黑掉。", "价格": "搭配：价格可以涨跌，不能说“黑了”，与“突然黑了”搭配不当。", "声音": "语义：声音是听觉的，不能“黑了”，与电视屏幕变黑的描述冲突。"}, "sentence_index": 0, "correct_answer": "画面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手指擦了擦画面，想看清楚。", "explanation": "这里应该用〈屏幕〉。屏幕是可以擦的实物，画面是屏幕上显示的影像，不能擦。"}, {"text": "这个画面是去年签的。", "explanation": "这里应该用〈合同〉。合同可以签订，画面是屏幕上显现的景象，不能签。"}, {"text": "这台电视的一只画面突然黑了。", "explanation": "这里应该用〈个〉或〈幅〉。画面不用“只”计量，“只”多用于动物或成对的物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92696, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挂面", "is_correct": false, "explanation": "挂面 guàmiàn 与 画面 的第一音节只有声母不同（g 与 h），意思是晾干的细面条。"}, {"text": "画面", "is_correct": true, "explanation": "正确答案。画面 huàmiàn，指屏幕或图画上显示出来的景象。"}, {"text": "和面", "is_correct": false, "explanation": "和面 huómiàn 与 画面 的第一音节韵母不同（o 与 a），声调也不同（二声与四声）。意思是加水揉面粉。"}, {"text": "会面", "is_correct": false, "explanation": "会面 huìmiàn 与 画面 的第一音节只有韵母不同（i 与 a），意思是见面、会见。"}], "explanations": {"挂面": "挂面 guàmiàn 与 画面 的第一音节只有声母不同（g 与 h），意思是晾干的细面条。", "画面": "正确答案。画面 huàmiàn，指屏幕或图画上显示出来的景象。", "和面": "和面 huómiàn 与 画面 的第一音节韵母不同（o 与 a），声调也不同（二声与四声）。意思是加水揉面粉。", "会面": "会面 huìmiàn 与 画面 的第一音节只有韵母不同（i 与 a），意思是见面、会见。"}, "sentence_index": null, "correct_answer": "画面"}, "level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人或事物存在的时间，不能用“亮”来形容，与“照片的”不合。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格用来形容人的个性，不能用“亮”来形容照片。"}, {"text": "画面", "is_correct": true, "explanation": "正确。画面可以“亮”或“不亮”，“这张照片的画面不够亮”符合语境。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“亮”不能用来形容体重，“体重不够亮”搭配不当。"}], "explanations": {"年龄": "语义：年龄是人或事物存在的时间，不能用“亮”来形容，与“照片的”不合。", "性格": "语义：性格用来形容人的个性，不能用“亮”来形容照片。", "画面": "正确。画面可以“亮”或“不亮”，“这张照片的画面不够亮”符合语境。", "体重": "搭配：“亮”不能用来形容体重，“体重不够亮”搭配不当。"}, "sentence_index": 6, "correct_answer": "画面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她从相册里挑了一张画面给我看。", "explanation": "这里应该用〈照片〉。照片可以拿出来给人看；画面是屏幕上显现的景象，不是实物，不能从相册里挑出来。"}, {"text": "摄影师把画面对准了海边。", "explanation": "这里应该用〈镜头〉。镜头可以对准某处，画面是拍到的景象，不能对准。"}, {"text": "这段画面很好听。", "explanation": "这里应该用〈音乐〉。“好听”用于声音和音乐，画面是屏幕上显现的景象，不能用“好听”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕上的画面变很清楚。", "corrected_sentence": "屏幕上的画面变得很清楚。", "error_description": "错误在“变”的补语。“变”后面要用“变得”引出补语，不能直接说“变很清楚”。正确的说法是：屏幕上的画面变得很清楚。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电影里精美地画面让人难忘。", "corrected_sentence": "电影里精美的画面让人难忘。", "error_description": "错误在修饰“画面”的词。“精美”修饰名词，中间应用“的”，不能用“地”。正确的说法是：电影里精美的画面让人难忘。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36687aa2-dba4-4cb7-b01b-12ba6f663fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
