INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92697, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "列出是把想到的东西一样一样写在纸上。", "primary_collocate": null, "pronunciation": "liè chū", "ipa": "ljɛ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "我在纸上列出了想买的东西。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿出笔，列出今天要做的事。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，妈妈列出了一张清单。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先列出想去的地方吧。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在本子上列出了三个愿望。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他列出过很多旅行计划。", "target_word": "列出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，我先列出想说的话。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在纸上列出了喜欢的玩具。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟列出了他的生日礼物清单。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想一条一条列出想法。", "target_word": "列出", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "列出了", "label": "体标"}, {"form": "列出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把想到的东西一样一样写在纸上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92697, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "列出", "is_correct": true, "explanation": "正确：把想到的东西一样一样写在纸上。"}, {"text": "列车", "is_correct": false, "explanation": "chē（第一声）与 chū（第一声）韵母不同，意思是列车、火车。"}, {"text": "借出", "is_correct": false, "explanation": "jiè（第四声）与 liè 声母不同（j 与 l），意思是借给别人。"}, {"text": "泄出", "is_correct": false, "explanation": "xiè 与 liè 声母不同（x 与 l），意思是液体或气体流出。"}], "explanations": {"列出": "正确：把想到的东西一样一样写在纸上。", "列车": "chē（第一声）与 chū（第一声）韵母不同，意思是列车、火车。", "借出": "jiè（第四声）与 liè 声母不同（j 与 l），意思是借给别人。", "泄出": "xiè 与 liè 声母不同（x 与 l），意思是液体或气体流出。"}, "sentence_index": null, "correct_answer": "列出"}, "level_3": {"options": [{"text": "列出", "is_correct": true, "explanation": "正确：“列出”表示把想买的东西一样一样写下，符合句意。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”不能表示把东西写在纸上，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于在纸上写东西的意思，不说在纸上唱东西。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“想买的东西”作宾语。"}], "explanations": {"列出": "正确：“列出”表示把想买的东西一样一样写下，符合句意。", "踢": "语义：“踢”不能表示把东西写在纸上，句子说不通。", "唱": "搭配：“唱”不能用于在纸上写东西的意思，不说在纸上唱东西。", "睡": "配价：“睡”是不及物动词，不能带“想买的东西”作宾语。"}, "sentence_index": 0, "correct_answer": "列出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他列出了一篇日记。", "explanation": "这里应该用〈写〉。列出是把想到的东西逐项写下，一篇日记是整篇文章，要说写了一篇日记。"}, {"text": "妈妈列出了一首歌。", "explanation": "这里应该用〈唱出〉。列出用于逐项写下项目，一首歌要用唱出。"}, {"text": "她列出了一个笑容。", "explanation": "这里应该用〈露出〉。笑容是表情，要用露出；列出是把东西逐项写下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "列出", "is_correct": true, "explanation": "正确：“列出”表示把想说的话一样一样写下，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能吃话。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般搭配衣物、蔬菜，不说洗想说的话。"}, {"text": "躺", "is_correct": false, "explanation": "配价：“躺”是不及物动词，不能带“想说的话”作宾语。"}], "explanations": {"列出": "正确：“列出”表示把想说的话一样一样写下，符合句意。", "吃": "语义：“吃”的对象是食物，不能吃话。", "洗": "搭配：“洗”一般搭配衣物、蔬菜，不说洗想说的话。", "躺": "配价：“躺”是不及物动词，不能带“想说的话”作宾语。"}, "sentence_index": 6, "correct_answer": "列出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他列出了一座桥。", "explanation": "这里应该用〈建〉。列出只用于把项目逐项写下，修桥要用建。"}, {"text": "他列出了一阵叹息。", "explanation": "这里应该用〈发出〉。发出用于声音、光、信号等，列出只用于逐项写下项目。"}, {"text": "运动员列出了一个好成绩。", "explanation": "这里应该用〈打出〉。打出多用于比赛中的成绩、分数，列出是把项目逐项写下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先把要带的东西列出去。", "corrected_sentence": "我先把要带的东西列出来。", "error_description": "趋向补语错误：“列出去”错，应为“列出来”。把要带的东西写到纸上，是让东西“出现”在眼前，要用“来”，不用表示离开说话人的“去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我列出了过三个想去的地方。", "corrected_sentence": "我列出过三个想去的地方。", "error_description": "体标错误：“列出了过”错，应为“列出过”。“列出过”表示曾经做过，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
