INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按次序逐项写出或排列出来。", "primary_collocate": null, "pronunciation": "liè chū", "ipa": "ljɛ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "老师让我们列出五个问题。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他按时间顺序列出了所有活动。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在表里列出你的姓名和电话。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报告里列出了十个主要原因。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生列出了几种常见的症状。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我列出过一张购物清单。", "target_word": "列出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求大家列出下周的计划。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书的最后列出了参考资料。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把要买的东西全部列出了。", "target_word": "列出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格表上列出了所有课程。", "target_word": "列出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "列出了", "label": "体标"}, {"form": "列出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "按次序逐项写出或排列出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92698, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "列出", "is_correct": true, "explanation": "正确：按次序逐项写出或排列出来。"}, {"text": "列车", "is_correct": false, "explanation": "chē（第一声）与 chū（第一声）韵母不同，意思是列车、火车。"}, {"text": "借出", "is_correct": false, "explanation": "jiè（第四声）与 liè 声母不同（j 与 l），意思是借给别人。"}, {"text": "泄出", "is_correct": false, "explanation": "xiè 与 liè 声母不同（x 与 l），意思是液体或气体流出。"}], "explanations": {"列出": "正确：按次序逐项写出或排列出来。", "列车": "chē（第一声）与 chū（第一声）韵母不同，意思是列车、火车。", "借出": "jiè（第四声）与 liè 声母不同（j 与 l），意思是借给别人。", "泄出": "xiè 与 liè 声母不同（x 与 l），意思是液体或气体流出。"}, "sentence_index": null, "correct_answer": "列出"}, "level_3": {"options": [{"text": "列出", "is_correct": true, "explanation": "正确：“列出”表示按次序逐项写出，可以带“五个问题”作宾语，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，不能说喝问题。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不说唱问题。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“五个问题”作宾语。"}], "explanations": {"列出": "正确：“列出”表示按次序逐项写出，可以带“五个问题”作宾语，符合句意。", "喝": "语义：“喝”的对象是饮品，不能说喝问题。", "唱": "搭配：“唱”的对象是歌曲，不说唱问题。", "跑": "配价：“跑”是不及物动词，不能带“五个问题”作宾语。"}, "sentence_index": 0, "correct_answer": "列出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他列出了一封长长的信。", "explanation": "这里应该用〈写〉。列出是把若干项目逐项写下，一封信是整篇文字，要说写了一封信。"}, {"text": "她列出了一句心里话。", "explanation": "这里应该用〈说出〉。列出用于逐项写下项目，不用于把心里的话讲出口。"}, {"text": "老师列出了一幅画。", "explanation": "这里应该用〈画出〉。列出用于逐项写下项目，一幅画是整体作品，要用画出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "列出", "is_correct": true, "explanation": "正确：“列出”表示按次序逐项写出，可以用于“下周的计划”，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能吃计划。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般搭配衣物、蔬菜，不说洗计划。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“下周的计划”作宾语。"}], "explanations": {"列出": "正确：“列出”表示按次序逐项写出，可以用于“下周的计划”，符合句意。", "吃": "语义：“吃”的对象是食物，不能吃计划。", "洗": "搭配：“洗”一般搭配衣物、蔬菜，不说洗计划。", "睡": "配价：“睡”是不及物动词，不能带“下周的计划”作宾语。"}, "sentence_index": 6, "correct_answer": "列出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他列出了一座房子。", "explanation": "这里应该用〈盖〉。列出只用于逐项写下项目，盖房子要用盖。"}, {"text": "他列出了一阵笑声。", "explanation": "这里应该用〈发出〉。发出用于声音、光、信号，列出只用于逐项写下项目。"}, {"text": "比赛中她列出了一个好成绩。", "explanation": "这里应该用〈打出〉。打出多用于比赛中的成绩、分数，列出是把项目逐项写下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她列出了了三条建议。", "corrected_sentence": "她列出了三条建议。", "error_description": "体标错误：“列出了了”多了一个“了”，应为“列出了”。“了”只用一次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我列出了过一张旅行清单。", "corrected_sentence": "我列出过一张旅行清单。", "error_description": "体标错误：“列出了过”错，应为“列出过”。“过”表示曾经做过，不能再和“了”一起用在“列出”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
