INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中午吃的一顿饭。", "primary_collocate": null, "pronunciation": "wǔ cān", "ipa": "u˨˩ tsʰan˥", "syllable_count": 2, "sentences": [{"text": "这顿午餐花了五十块钱。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请我吃了一顿丰盛的午餐。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的午餐是在饭馆吃的。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午餐的时候，他一直在看手机。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的午餐是米饭和鸡肉。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在教室里吃午餐。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顿午餐很便宜，只要十块钱。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和我们一起吃了午餐。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没吃午餐，所以现在很饿。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午餐前，请先洗手。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顿", "label": "量词"}, {"form": "工作午餐", "label": "复合"}, {"form": "午餐时间", "label": "复合"}], "register": "中性", "sense_fingerprint": "中午吃的一顿饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11634477-b3a7-490b-8534-8c42b7d88671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "午餐", "is_correct": true, "explanation": "正确：“午餐”是中午吃的一顿饭，与“这顿”和“花了五十块钱”相符。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：量词“顿”只用于饭食，不能用于手机，“这顿手机”搭配不当。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影不是吃的东西，不能说“这顿电影”。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送给别人的东西，不是一顿饭，与句意不符。"}], "explanations": {"午餐": "正确：“午餐”是中午吃的一顿饭，与“这顿”和“花了五十块钱”相符。", "手机": "搭配：量词“顿”只用于饭食，不能用于手机，“这顿手机”搭配不当。", "电影": "语义：电影不是吃的东西，不能说“这顿电影”。", "礼物": "语义：礼物是送给别人的东西，不是一顿饭，与句意不符。"}, "sentence_index": 0, "correct_answer": "午餐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上七点吃午餐，然后出门。", "explanation": "这里应该用〈早餐〉。午餐指中午吃的饭，早上吃的饭要说早餐。"}, {"text": "我昨晚吃了一顿午餐，很饱。", "explanation": "这里应该用〈晚餐〉。午餐指中午吃的饭，晚上吃的饭要说晚餐。"}, {"text": "她每天半夜才吃午餐，然后睡觉。", "explanation": "这里应该用〈夜宵〉。午餐指中午吃的饭，半夜吃的东西要说夜宵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午餐", "is_correct": true, "explanation": "正确：“午餐”是中午吃的一顿饭，只要十块钱说明这顿饭很便宜，与句意相符。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：量词“顿”用于饭食，不用于房间，“这顿房间”搭配不当。"}, {"text": "药", "is_correct": false, "explanation": "语义：药是用来治病的，不是一顿饭，与“很便宜”的句意不符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，不能吃，与句意不符。"}], "explanations": {"午餐": "正确：“午餐”是中午吃的一顿饭，只要十块钱说明这顿饭很便宜，与句意相符。", "房间": "搭配：量词“顿”用于饭食，不用于房间，“这顿房间”搭配不当。", "药": "语义：药是用来治病的，不是一顿饭，与“很便宜”的句意不符。", "课本": "语义：课本是学习用的书，不能吃，与句意不符。"}, "sentence_index": 6, "correct_answer": "午餐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在书包里放了一根午餐，准备带去学校。", "explanation": "这里应该用〈份〉。「根」用于细长的东西；带的一餐饭用「份」。"}, {"text": "她点了一块午餐，在店里吃。", "explanation": "这里应该用〈份〉。「块」用于块状的东西；点的一餐饭用「份」。"}, {"text": "我带了一杯午餐去学校。", "explanation": "这里应该用〈份〉。「杯」用于饮料；带的一餐饭用「份」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
