INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天带了一条午餐去学校。", "corrected_sentence": "我今天带了一盒午餐去学校。", "error_description": "错误形式：“一条午餐”。正确形式：“一盒午餐”。“条”用于细长的东西，装在盒里的午餐要用“盒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
