INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92705, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看不过是看到不对的事，心里很生气。", "primary_collocate": null, "pronunciation": "kàn bu guò", "ipa": "kʰan˥˩ pu kuɔ˥˩", "syllable_count": 3, "sentences": [{"text": "他欺负小孩，我实在看不过去。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板这样对待员工，我看不过去了。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人乱扔垃圾，他看不过，就说了几句。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看不过同学被骂，站出来帮忙。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不过他一直撒谎。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看不过哥哥那样懒，生气地说了他。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居总是吵架，我真看不过去。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路边打狗，我看不过，大声喊了起来。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们这样欺负新同事，我可看不过。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看不过有人插队，就让那个人去排队。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看不过去", "label": "复合"}], "register": "口语", "sense_fingerprint": "看到不对的事心里生气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92705, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看不过", "is_correct": true, "explanation": "正确：「看不过去」表示看到不对的事心里不满、忍受不了，与“欺负小孩”的语境相符。"}, {"text": "舍不得", "is_correct": false, "explanation": "语义：「舍不得去」表示不愿离开、不想去，与前文“欺负小孩”需要出面制止的语境相矛盾。"}, {"text": "懒得", "is_correct": false, "explanation": "语义：「懒得去」表示嫌麻烦、不想管，与“我实在看不过”的愤慨语气正好相反。"}, {"text": "忍心", "is_correct": false, "explanation": "语义：「忍心去」表示狠得下心、不在乎，与“我实在看不过”的愤慨语境相反。"}], "explanations": {"看不过": "正确：「看不过去」表示看到不对的事心里不满、忍受不了，与“欺负小孩”的语境相符。", "舍不得": "语义：「舍不得去」表示不愿离开、不想去，与前文“欺负小孩”需要出面制止的语境相矛盾。", "懒得": "语义：「懒得去」表示嫌麻烦、不想管，与“我实在看不过”的愤慨语气正好相反。", "忍心": "语义：「忍心去」表示狠得下心、不在乎，与“我实在看不过”的愤慨语境相反。"}, "sentence_index": 0, "correct_answer": "看不过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看不过没有学历的人。", "explanation": "这里应该用〈看不起〉。看不过用于看到不对、不公的事而愤慨，单纯瞧不起别人要用〈看不起〉。"}, {"text": "我看不过这首歌的旋律。", "explanation": "这里应该用〈欣赏〉。看不过用于不合理之事的不满，对歌曲的赞赏要用〈欣赏〉。"}, {"text": "我看不过下雨天。", "explanation": "这里应该用〈讨厌〉。下雨天不是不对的事，不能用看不过，只能说讨厌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92705, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看不过", "is_correct": true, "explanation": "正确：「看不过去」表示看着不对的事忍受不了，与“邻居总是吵架”的语境相符。"}, {"text": "懒得", "is_correct": false, "explanation": "语义：「懒得去」表示嫌麻烦、不想管，与“我真看不过”所表达的强烈不满相反。"}, {"text": "乐意", "is_correct": false, "explanation": "语义：「乐意去」表示愿意前往，与邻居吵架令人不满的语境不符。"}, {"text": "舍得", "is_correct": false, "explanation": "语义：“舍得去”表示愿意付出、不吝惜，与邻居吵架令人不满的语境不符。"}], "explanations": {"看不过": "正确：「看不过去」表示看着不对的事忍受不了，与“邻居总是吵架”的语境相符。", "懒得": "语义：「懒得去」表示嫌麻烦、不想管，与“我真看不过”所表达的强烈不满相反。", "乐意": "语义：「乐意去」表示愿意前往，与邻居吵架令人不满的语境不符。", "舍得": "语义：“舍得去”表示愿意付出、不吝惜，与邻居吵架令人不满的语境不符。"}, "sentence_index": 6, "correct_answer": "看不过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看不过他的勇气。", "explanation": "这里应该用〈佩服〉。他有勇气值得敬佩，看不过用于对不合理之事的不满，不能用于佩服。"}, {"text": "我看不过蛇。", "explanation": "这里应该用〈害怕〉。蛇不是不对的事，对它的恐惧要用〈害怕〉。"}, {"text": "我看不过这束花的香气。", "explanation": "这里应该用〈喜欢〉。看不过用于不合理之事的不满，对花香的喜爱要用〈喜欢〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么没礼貌的人，我实在看不过了去。", "corrected_sentence": "这么没礼貌的人，我实在看不过去。", "error_description": "错误：「了」插在动词补语「看不过去」中间，成了「看不过了去」，不成词。正确应为「看不过去」，表示看到不对的事忍受不了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种浪费钱的做法，我真看不过来。", "corrected_sentence": "这种浪费钱的做法，我真看不过去。", "error_description": "错误：「看不过来」表示数量多、看不完或顾不过来，与此句表达的不满语气不符。正确应为「看不过去」，表示看到不对的事忍受不了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
