INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看到不合理的事而感到不满，不能容忍。", "primary_collocate": null, "pronunciation": "kàn bu guò", "ipa": "kʰan˥˩ pu kuɔ˥˩", "syllable_count": 3, "sentences": [{"text": "老师不公平，同学们都看不过去。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资这么低，大家看不过，就去找经理。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看不过别人乱收费，向有关部门反映了。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种不合理的规定，谁都看不过去。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看不过公司的做法，辞职了。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱涨得太离谱，我真看不过。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人占着座位不让，大家都看不过去。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不过他们这样浪费粮食。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法太不公平，连朋友都看不过去。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种事，谁看了都看不过去。", "target_word": "看不过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看不过去", "label": "复合"}], "register": "口语", "sense_fingerprint": "对不合理的事不满而无法容忍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看不过", "is_correct": true, "explanation": "正确：「看不过去」表示对不合理的事不满、无法容忍，与“老师不公平”的语境相符。"}, {"text": "舍不得", "is_correct": false, "explanation": "语义：「舍不得去」表示不愿离开，与“老师不公平”引起的不满不符。"}, {"text": "舍得", "is_correct": false, "explanation": "搭配：「舍得」需接付出的代价或物品，不能直接接“去”作补语。"}, {"text": "来不及", "is_correct": false, "explanation": "语义：「来不及去」强调时间不够，与“同学们都”对不公之事的态度不符。"}], "explanations": {"看不过": "正确：「看不过去」表示对不合理的事不满、无法容忍，与“老师不公平”的语境相符。", "舍不得": "语义：「舍不得去」表示不愿离开，与“老师不公平”引起的不满不符。", "舍得": "搭配：「舍得」需接付出的代价或物品，不能直接接“去”作补语。", "来不及": "语义：「来不及去」强调时间不够，与“同学们都”对不公之事的态度不符。"}, "sentence_index": 0, "correct_answer": "看不过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看不过身边没有钱的人。", "explanation": "这里应该用〈看不起〉。看不过用于对不合理之事的不满，单纯瞧不起别人要用〈看不起〉。"}, {"text": "他帮我修好了车，我看不过他的热心。", "explanation": "这里应该用〈感激〉。看不过用于不合理之事的不满，对别人的帮助表示谢意要用〈感激〉。"}, {"text": "我看不过香菜的味道。", "explanation": "这里应该用〈讨厌〉。香菜没有不合理之处，对它的反感只能说讨厌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看不过", "is_correct": true, "explanation": "正确：「看不过去」表示对不合理的事忍受不了，与“有人占着座位不让”的语境相符。"}, {"text": "舍不得", "is_correct": false, "explanation": "语义：「舍不得去」表示不愿离开或不愿付出，与大家对有人占座不让的不满不符。"}, {"text": "忍心", "is_correct": false, "explanation": "语义：「忍心去」表示狠得下心、不在乎，与大家因占座而不满的语境相反。"}, {"text": "来得及", "is_correct": false, "explanation": "搭配：「来得及」表示时间足够，与“大家都”对不合理之事的不满语气不搭。"}], "explanations": {"看不过": "正确：「看不过去」表示对不合理的事忍受不了，与“有人占着座位不让”的语境相符。", "舍不得": "语义：「舍不得去」表示不愿离开或不愿付出，与大家对有人占座不让的不满不符。", "忍心": "语义：「忍心去」表示狠得下心、不在乎，与大家因占座而不满的语境相反。", "来得及": "搭配：「来得及」表示时间足够，与“大家都”对不合理之事的不满语气不搭。"}, "sentence_index": 6, "correct_answer": "看不过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看不过他的毅力。", "explanation": "这里应该用〈佩服〉。他的毅力值得敬佩，看不过用于不合理之事的不满，不能用于佩服。"}, {"text": "我看不过深夜的雷声。", "explanation": "这里应该用〈害怕〉。雷声不是不合理的事，对它的恐惧要用〈害怕〉。"}, {"text": "我看不过这幅画的美丽色彩。", "explanation": "这里应该用〈欣赏〉。看不过用于不合理之事的不满，对画作的赞美要用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种不合理的涨价，大家都看不过来。", "corrected_sentence": "这种不合理的涨价，大家都看不过去。", "error_description": "错误：「看不过来」表示数量多、顾不过来，与对不合理之事的不满无关。正确应为「看不过去」，表示对不合理的事忍受不了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种太过分的行为，我们都看不过了去。", "corrected_sentence": "这种太过分的行为，我们都看不过去。", "error_description": "错误：「了」插在补语「看不过去」中间，成了「看不过了去」，不成词。正确应为「看不过去」，表示对这种行为忍受不了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可执行是说一件事能真的做出来，照着做就行。", "primary_collocate": null, "pronunciation": "kě zhí xíng", "ipa": "kʰɤ˨˩ ʈʂɨ˧˥ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "这个办法很简单，大家都觉得可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的计划太大了，不可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们一个可执行的学习计划。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个目标不太可执行，我们改一改吧。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的建议很具体，也可执行，大家都同意。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一个可执行的方案。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的要求可执行吗？", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好计划一定要可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法很好，但是不可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出的办法是可执行的，我们马上试了。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可執行", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办法、计划、要求等具体清楚，能真正照着做出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37389423-afce-42fb-8c84-9ff544ce5cc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可执行", "is_correct": true, "explanation": "“可执行”指办法能真正照着做，与“很简单”的语境相符，填入后句意通顺。"}, {"text": "复杂", "is_correct": false, "explanation": "语义：“复杂”与前句“很简单”相反，前后矛盾，句子不通。"}, {"text": "不可能", "is_correct": false, "explanation": "语义：“不可能”与前句“很简单”相矛盾，句意不通。"}, {"text": "遥远", "is_correct": false, "explanation": "搭配：“遥远”多用于距离或时间，不用来形容办法。"}], "explanations": {"可执行": "“可执行”指办法能真正照着做，与“很简单”的语境相符，填入后句意通顺。", "复杂": "语义：“复杂”与前句“很简单”相反，前后矛盾，句子不通。", "不可能": "语义：“不可能”与前句“很简单”相矛盾，句意不通。", "遥远": "搭配：“遥远”多用于距离或时间，不用来形容办法。"}, "sentence_index": 0, "correct_answer": "可执行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人做事很可执行，大家都信任他。", "explanation": "这里应该用〈可靠〉。“可执行”只说办法、计划能否照着做，不用来形容人的品质。"}, {"text": "这种药很可执行，吃了以后很快见效。", "explanation": "这里应该用〈有效〉。“可执行”用于办法、计划，不用来说药物的作用。"}, {"text": "这部电影很可执行，我看了两遍。", "explanation": "这里应该用〈精彩〉。“可执行”说办法、计划能否照着做，不用来评价电影好不好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可执行", "is_correct": true, "explanation": "“可执行”说要求能否照着做，与“吗”问句相符，是句子的谓语。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容人或动物讨人喜欢，与“要求”不搭，句子不通。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多形容水、眼神等，不用来形容要求。"}, {"text": "温暖", "is_correct": false, "explanation": "搭配：“温暖”多形容温度或感情，不用来形容要求。"}], "explanations": {"可执行": "“可执行”说要求能否照着做，与“吗”问句相符，是句子的谓语。", "可爱": "语义：“可爱”形容人或动物讨人喜欢，与“要求”不搭，句子不通。", "清澈": "搭配：“清澈”多形容水、眼神等，不用来形容要求。", "温暖": "搭配：“温暖”多形容温度或感情，不用来形容要求。"}, "sentence_index": 6, "correct_answer": "可执行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把刀很可执行，厨房里天天用。", "explanation": "这里应该用〈实用〉。“可执行”只用于办法、计划、要求，不用来形容刀具等物品。"}, {"text": "这个消息很可执行，大家都相信了。", "explanation": "这里应该用〈可信〉。“可执行”说办法能否照做，不用来形容消息是否可信。"}, {"text": "这只小狗很可执行，大家都喜欢它。", "explanation": "这里应该用〈可爱〉。“可执行”不用来形容动物的样子或性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案设计地可执行，大家都同意了。", "corrected_sentence": "这个方案设计得可执行，大家都同意了。", "error_description": "补语标记应用“得”，不能用“地”。“地”用在动词前作状语，“设计”之后接补语“可执行”要用“得”。错误形式：设计地可执行；正确形式：设计得可执行。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法是可执行的的，我们明天就开始。", "corrected_sentence": "这个办法是可执行的，我们明天就开始。", "error_description": "“的”重复使用，“可执行的”只需一个“的”。错误形式：可执行的的；正确形式：可执行的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab211b87-ba01-4b87-ab29-4a9296f4379a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
