INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92711, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "abstract", "definition": "同比是拿今年的这个月，和去年同一个月比一比。", "primary_collocate": null, "pronunciation": "tóng bǐ", "ipa": "tʰʊŋ˧˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个月卖的水果同比多了很多。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年五月的雨水同比少了一些。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们店这个月的客人同比增加了。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的电费同比涨了二十块。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年六月的平均气温同比升高了两度。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本月的新书销量同比下降了。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家十月的开销同比多了一半。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的游客同比多了三千人。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年四月我们的收入同比提高了。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里这个月的房价同比涨了一点。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同比增长", "label": "复合"}, {"form": "同比下降", "label": "复合"}], "register": "中性", "sense_fingerprint": "拿今年某个月和去年同一个月相比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92711, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同比", "is_correct": true, "explanation": "正确答案：同比（tóng bǐ），拿今年某个月和去年同一个月相比。"}, {"text": "铜币", "is_correct": false, "explanation": "bì（第四声）与 bǐ（第三声）只有声调不同，意思是铜制的钱币。"}, {"text": "同辈", "is_correct": false, "explanation": "bèi（第四声）与 bǐ（第三声）的韵母与声调都不同，意思是同一辈分。"}, {"text": "铜杯", "is_correct": false, "explanation": "bēi（第一声）与 bǐ（第三声）的韵母与声调都不同，意思是铜制的杯子。"}], "explanations": {"同比": "正确答案：同比（tóng bǐ），拿今年某个月和去年同一个月相比。", "铜币": "bì（第四声）与 bǐ（第三声）只有声调不同，意思是铜制的钱币。", "同辈": "bèi（第四声）与 bǐ（第三声）的韵母与声调都不同，意思是同一辈分。", "铜杯": "bēi（第一声）与 bǐ（第三声）的韵母与声调都不同，意思是铜制的杯子。"}, "sentence_index": null, "correct_answer": "同比"}, "level_3": {"options": [{"text": "同比", "is_correct": true, "explanation": "正确：同比表示与去年同一时期相比，说明水果卖得多了。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是地方或物品，不能用来说明水果的数量变化。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”与水果卖出的数量无关，不能说明数量的变化。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”是买的动作，与“卖的水果”的数量变化不搭。"}], "explanations": {"同比": "正确：同比表示与去年同一时期相比，说明水果卖得多了。", "打扫": "搭配：“打扫”的对象是地方或物品，不能用来说明水果的数量变化。", "讨论": "语义：“讨论”与水果卖出的数量无关，不能说明数量的变化。", "购买": "搭配：“购买”是买的动作，与“卖的水果”的数量变化不搭。"}, "sentence_index": 0, "correct_answer": "同比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的电费同比上个月涨了二十块。", "explanation": "这里应该用〈环比〉。同比是与去年同一时期相比，与上个月相比要用环比。"}, {"text": "妈妈把两份菜谱同比了一下。", "explanation": "这里应该用〈对比〉。同比专指与去年同期相比，不能泛指两样东西的比较。"}, {"text": "这个班的男女同比是二比一。", "explanation": "这里应该用〈比例〉。“同比”只表示与去年同期相比，不能表示“比例”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同比", "is_correct": true, "explanation": "正确：同比表示与去年同期相比，可以说明开销的增长情况。"}, {"text": "节约", "is_correct": false, "explanation": "语义：“节约”表示省下来，与“多了一半”的意思矛盾。"}, {"text": "研究", "is_correct": false, "explanation": "搭配：“研究”的对象是问题或事物，不能用来说明开销的数量变化。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：“出售”的对象是商品，不能以“开销”作主语。"}], "explanations": {"同比": "正确：同比表示与去年同期相比，可以说明开销的增长情况。", "节约": "语义：“节约”表示省下来，与“多了一半”的意思矛盾。", "研究": "搭配：“研究”的对象是问题或事物，不能用来说明开销的数量变化。", "出售": "搭配：“出售”的对象是商品，不能以“开销”作主语。"}, "sentence_index": 6, "correct_answer": "同比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年同比的房价是两万块。", "explanation": "这里应该用〈同期〉。同比是比较方式，不能作“房价”的定语。"}, {"text": "孩子们同比放学，一起回家了。", "explanation": "“同比”只表示与去年同期相比，不能表示“同时”的意思。"}, {"text": "她同比努力地练琴。", "explanation": "“同比”只表示与去年同期相比，不能表示“同样”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年五月的水费同比的增加了五块。", "corrected_sentence": "今年五月的水费同比增加了五块。", "error_description": "错误在“同比”后多加了结构助词“的”。“同比”作状语直接修饰动词，不能加“的”，应说“同比增加了五块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的游客同比比去年少了两千人。", "corrected_sentence": "这个月的游客同比少了两千人。", "error_description": "错误在“同比”后多加了“比去年”。“同比”本身已经表示与去年同期相比，不能再加“比去年”，应说“同比少了两千人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
