INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92712, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "abstract", "definition": "与上一年同一时期相比。", "primary_collocate": null, "pronunciation": "tóng bǐ", "ipa": "tʰʊŋ˧˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司今年的销售额同比增长了百分之十。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个季度的利润同比下降了五个百分点。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年三月，全国的汽车销量同比上涨了。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本月出口总额同比增加了八亿元。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该市今年的游客人数同比减少了两成。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年十月的物价同比上升了百分之三。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据显示，二月的用电量同比增长明显。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂上个月的产量同比提高了不少。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的粮食产量同比略有增加。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告说，第二季度的订单同比减少了。", "target_word": "同比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同比增长", "label": "复合"}, {"form": "同比下降", "label": "复合"}], "register": "书面", "sense_fingerprint": "与上一年同一时期相比（统计、经济用语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同比", "is_correct": true, "explanation": "正确答案：同比（tóng bǐ），与上一年同一时期相比。"}, {"text": "同辈", "is_correct": false, "explanation": "bèi（第四声）与 bǐ（第三声）的韵母与声调都不同，意思是同一辈分。"}, {"text": "铜币", "is_correct": false, "explanation": "bì（第四声）与 bǐ（第三声）的声调不同，意思是铜制的钱币。"}, {"text": "同批", "is_correct": false, "explanation": "pī（第一声）与 bǐ（第三声）的声母与声调都不同，意思是同一批次。"}], "explanations": {"同比": "正确答案：同比（tóng bǐ），与上一年同一时期相比。", "同辈": "bèi（第四声）与 bǐ（第三声）的韵母与声调都不同，意思是同一辈分。", "铜币": "bì（第四声）与 bǐ（第三声）的声调不同，意思是铜制的钱币。", "同批": "pī（第一声）与 bǐ（第三声）的声母与声调都不同，意思是同一批次。"}, "sentence_index": null, "correct_answer": "同比"}, "level_3": {"options": [{"text": "同比", "is_correct": true, "explanation": "正确：同比表示与去年同期相比，说明销售额增长的比较基准。"}, {"text": "下降", "is_correct": false, "explanation": "语义：“下降”与“增长”意思相反，两者不能连用说明同一变化。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能以“销售额”作主语。"}, {"text": "调查", "is_correct": false, "explanation": "配价：“调查”要有调查的人和对象，不能只以“销售额”为主语。"}], "explanations": {"同比": "正确：同比表示与去年同期相比，说明销售额增长的比较基准。", "下降": "语义：“下降”与“增长”意思相反，两者不能连用说明同一变化。", "购买": "搭配：“购买”的对象是商品，不能以“销售额”作主语。", "调查": "配价：“调查”要有调查的人和对象，不能只以“销售额”为主语。"}, "sentence_index": 0, "correct_answer": "同比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本月出口总额同比上个月增加了八亿元。", "explanation": "这里应该用〈环比〉。同比是与去年同一时期相比，与上个月相比要用环比。"}, {"text": "我们把两家店的销量同比了一下。", "explanation": "这里应该用〈对比〉。同比专指与去年同期相比，不能泛指两件事的比较。"}, {"text": "这个年级的男女同比是三比二。", "explanation": "这里应该用〈比例〉。“同比”只表示与去年同期相比，不能表示“比例”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同比", "is_correct": true, "explanation": "正确：同比表示与去年同期相比，可以说明用电量的增长情况。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少”与“增长”方向相反，不能同时说明用电量的变化。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的对象是产品，不能以“用电量”为主语。"}, {"text": "节约", "is_correct": false, "explanation": "语义：“节约”表示省下来，与“增长”的意思矛盾。"}], "explanations": {"同比": "正确：同比表示与去年同期相比，可以说明用电量的增长情况。", "减少": "语义：“减少”与“增长”方向相反，不能同时说明用电量的变化。", "生产": "搭配：“生产”的对象是产品，不能以“用电量”为主语。", "节约": "语义：“节约”表示省下来，与“增长”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "同比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年同比的订单有三千份。", "explanation": "这里应该用〈同期〉。同比是比较方式，不能作“订单”的定语。"}, {"text": "我们同比出发，路上很顺利。", "explanation": "“同比”只表示与去年同期相比，不能表示“同时”的意思。"}, {"text": "他同比认真地工作。", "explanation": "“同比”只表示与去年同期相比，不能表示“同样”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的煤气费同比的涨了十块。", "corrected_sentence": "这个月的煤气费同比涨了十块。", "error_description": "错误在“同比”后多加了结构助词“的”。“同比”作状语直接修饰动词，不能加“的”，应说“同比涨了十块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂今年的产量同比比去年多了两成。", "corrected_sentence": "这家工厂今年的产量同比多了两成。", "error_description": "错误在“同比”后多加了“比去年”。“同比”本身已经表示与去年同期相比，不能再加“比去年”，应说“同比多了两成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92713, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软", "is_correct": true, "explanation": "正确。“软”与“硬”构成反义，指摸起来不硬、容易变形。"}, {"text": "甜", "is_correct": false, "explanation": "甜与“硬”不构成反义或近义关系，意思是有甜味。"}, {"text": "湿", "is_correct": false, "explanation": "湿与“硬”不构成反义关系，意思是含有水分。"}, {"text": "亮", "is_correct": false, "explanation": "亮与“硬”不构成反义关系，意思是有光、明亮。"}], "correct_answer": "软", "explanations": {"软": "正确。“软”与“硬”构成反义，指摸起来不硬、容易变形。", "甜": "甜与“硬”不构成反义或近义关系，意思是有甜味。", "湿": "湿与“硬”不构成反义关系，意思是含有水分。", "亮": "亮与“硬”不构成反义关系，意思是有光、明亮。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92713, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软", "is_correct": true, "explanation": "正确。“软”与“硬”构成反义，指摸起来不硬、容易变形。"}, {"text": "慢", "is_correct": false, "explanation": "慢与“硬”不构成反义或近义关系，意思是速度低。"}, {"text": "远", "is_correct": false, "explanation": "远与“硬”不构成反义关系，意思是距离大。"}, {"text": "苦", "is_correct": false, "explanation": "苦与“硬”不构成反义关系，意思是味道苦涩。"}], "correct_answer": "软", "explanations": {"软": "正确。“软”与“硬”构成反义，指摸起来不硬、容易变形。", "慢": "慢与“硬”不构成反义或近义关系，意思是速度低。", "远": "远与“硬”不构成反义关系，意思是距离大。", "苦": "苦与“硬”不构成反义关系，意思是味道苦涩。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92713, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用手摸起来不软，不容易变形。", "primary_collocate": null, "pronunciation": "yìng", "ipa": "iŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这块面包太硬了。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张床很硬，我睡不好。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢太硬的枕头。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果摸起来很硬。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的泥土变得很硬。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块糖太硬，咬不动。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很硬的椅子坐久了不舒服。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块饼干很硬，咬起来很费力。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服摸着很硬。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放干了的面包又硬又难吃。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "硬邦邦", "label": "复合"}, {"form": "坚硬", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手摸起来不软的触感，如硬面包、硬床", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92713, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "硬", "is_correct": true, "explanation": "正确。硬指物体用手摸起来不软，不容易变形。"}, {"text": "印", "is_correct": false, "explanation": "印（yìn）与“硬”（yìng）只差韵尾：ng 换成 n，意思是印刷、印章。"}, {"text": "影", "is_correct": false, "explanation": "影（yǐng）与“硬”（yìng）声调不同（第三声与第四声），意思是影子。"}, {"text": "赢", "is_correct": false, "explanation": "赢（yíng）与“硬”（yìng）声调不同（第二声与第四声），意思是获胜。"}, {"text": "鹰", "is_correct": false, "explanation": "鹰（yīng）与“硬”（yìng）声调不同（第一声与第四声），意思是猛禽。"}], "explanations": {"硬": "正确。硬指物体用手摸起来不软，不容易变形。", "印": "印（yìn）与“硬”（yìng）只差韵尾：ng 换成 n，意思是印刷、印章。", "影": "影（yǐng）与“硬”（yìng）声调不同（第三声与第四声），意思是影子。", "赢": "赢（yíng）与“硬”（yìng）声调不同（第二声与第四声），意思是获胜。", "鹰": "鹰（yīng）与“硬”（yìng）声调不同（第一声与第四声），意思是猛禽。"}, "sentence_index": null, "correct_answer": "硬"}, "level_3": {"options": [{"text": "硬", "is_correct": true, "explanation": "正确。“太硬了”描述面包摸起来或咬起来的触感，符合语境。"}, {"text": "吵", "is_correct": false, "explanation": "语义：面包不会发出声音，“吵”不能形容面包。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的心情，不说“面包太高兴了”。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：面包没有智力，“聪明”不能形容它。"}], "explanations": {"硬": "正确。“太硬了”描述面包摸起来或咬起来的触感，符合语境。", "吵": "语义：面包不会发出声音，“吵”不能形容面包。", "高兴": "搭配：“高兴”形容人的心情，不说“面包太高兴了”。", "聪明": "语义：面包没有智力，“聪明”不能形容它。"}, "sentence_index": 0, "correct_answer": "硬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗粥很硬，喝起来很费劲。", "explanation": "这里应该用〈稠〉。粥的浓稠程度用“稠”；“硬”指摸起来不软、不易变形，不能用来形容粥。"}, {"text": "今天的天气很硬，外面一点也不暖和。", "explanation": "这里应该用〈冷〉。天气的寒暖用“冷”；“硬”指摸起来不软，不能用来形容天气。"}, {"text": "这杯茶很硬，喝起来很顺口。", "explanation": "这里应该用〈浓〉。茶的浓淡用“浓”；“硬”指摸起来不软，不能用来形容茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬", "is_correct": true, "explanation": "正确。“很硬的椅子”指椅面不软，坐久了不舒服，符合语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：椅子没有甜味，“甜”不能形容椅子。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容人的性情，不用于椅子。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：椅子没有情绪，“快乐”不能形容它。"}], "explanations": {"硬": "正确。“很硬的椅子”指椅面不软，坐久了不舒服，符合语境。", "甜": "语义：椅子没有甜味，“甜”不能形容椅子。", "温柔": "搭配：“温柔”形容人的性情，不用于椅子。", "快乐": "语义：椅子没有情绪，“快乐”不能形容它。"}, "sentence_index": 6, "correct_answer": "硬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水很硬，看不见河底。", "explanation": "这里应该用〈浑〉。水的清浊用“浑”；“硬”指摸起来不软，不能表示水看不清。"}, {"text": "这间屋子很硬，住着很舒服。", "explanation": "这里应该用〈暖和〉。屋子的冷暖用“暖和”；“硬”不能用来形容屋子。"}, {"text": "这碗汤很硬，喝起来很鲜。", "explanation": "这里应该用〈浓〉。汤的浓淡用“浓”；“硬”指摸起来不软，不能用来形容汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块面包硬很，咬不动。", "corrected_sentence": "这块面包很硬，咬不动。", "error_description": "语序错误：程度副词“很”应放在形容词“硬”前，说“很硬”，不能说“硬很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张床硬的很，我睡不好。", "corrected_sentence": "这张床硬得很，我睡不好。", "error_description": "补语标记错误：形容词作程度补语时应用“得”（硬得很），不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92714, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软", "is_correct": true, "explanation": "正确。“软”与“硬”相对，指物体不坚固、容易变形。"}, {"text": "甜", "is_correct": false, "explanation": "甜与“硬”不构成反义或近义关系，意思是有甜味。"}, {"text": "湿", "is_correct": false, "explanation": "湿与“硬”不构成反义关系，意思是含有水分。"}, {"text": "亮", "is_correct": false, "explanation": "亮与“硬”不构成反义关系，意思是有光、明亮。"}], "correct_answer": "软", "explanations": {"软": "正确。“软”与“硬”相对，指物体不坚固、容易变形。", "甜": "甜与“硬”不构成反义或近义关系，意思是有甜味。", "湿": "湿与“硬”不构成反义关系，意思是含有水分。", "亮": "亮与“硬”不构成反义关系，意思是有光、明亮。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92714, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "软", "is_correct": true, "explanation": "正确。“软”与“硬”相对，指物体不坚固、容易变形。"}, {"text": "慢", "is_correct": false, "explanation": "慢与“硬”不构成反义或近义关系，意思是速度低。"}, {"text": "远", "is_correct": false, "explanation": "远与“硬”不构成反义关系，意思是距离大。"}, {"text": "苦", "is_correct": false, "explanation": "苦与“硬”不构成反义关系，意思是味道苦涩。"}], "correct_answer": "软", "explanations": {"软": "正确。“软”与“硬”相对，指物体不坚固、容易变形。", "慢": "慢与“硬”不构成反义或近义关系，意思是速度低。", "远": "远与“硬”不构成反义关系，意思是距离大。", "苦": "苦与“硬”不构成反义关系，意思是味道苦涩。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92714, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "物体坚固，不易变形；与“软”相对。", "primary_collocate": null, "pronunciation": "yìng", "ipa": "iŋ˥˩", "syllable_count": 1, "sentences": [{"text": "钻石是世界上最硬的东西。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁比木头硬。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料很硬，不容易坏。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头很硬，不容易变形。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锤子的头很硬。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢铁又硬又结实。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬的东西不容易弯。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子很硬，踩不坏。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃虽然硬，但是容易碎。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木头很硬，用来做桌子。", "target_word": "硬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坚硬", "label": "复合"}, {"form": "硬邦邦", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体坚固、不易变形，与软相对，如石头硬、钢铁硬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '465f594a-3aae-426d-a776-e288a89e9985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92714, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "硬", "is_correct": true, "explanation": "正确。硬指物体坚固、不易变形，与“软”相对。"}, {"text": "印", "is_correct": false, "explanation": "印（yìn）与“硬”（yìng）只差韵尾：ng 换成 n，意思是印刷、印章。"}, {"text": "影", "is_correct": false, "explanation": "影（yǐng）与“硬”（yìng）声调不同（第三声与第四声），意思是影子。"}, {"text": "赢", "is_correct": false, "explanation": "赢（yíng）与“硬”（yìng）声调不同（第二声与第四声），意思是获胜。"}, {"text": "鹰", "is_correct": false, "explanation": "鹰（yīng）与“硬”（yìng）声调不同（第一声与第四声），意思是猛禽。"}], "explanations": {"硬": "正确。硬指物体坚固、不易变形，与“软”相对。", "印": "印（yìn）与“硬”（yìng）只差韵尾：ng 换成 n，意思是印刷、印章。", "影": "影（yǐng）与“硬”（yìng）声调不同（第三声与第四声），意思是影子。", "赢": "赢（yíng）与“硬”（yìng）声调不同（第二声与第四声），意思是获胜。", "鹰": "鹰（yīng）与“硬”（yìng）声调不同（第一声与第四声），意思是猛禽。"}, "sentence_index": null, "correct_answer": "硬"}, "level_3": {"options": [{"text": "硬", "is_correct": true, "explanation": "正确。“最硬的东西”指硬度最高，符合钻石的特点。"}, {"text": "甜", "is_correct": false, "explanation": "语义：钻石没有甜味，不能说“最甜的东西”。"}, {"text": "香", "is_correct": false, "explanation": "语义：钻石没有香气，“最香的东西”与钻石的特点不符。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人或动物的智力，不用于钻石。"}], "explanations": {"硬": "正确。“最硬的东西”指硬度最高，符合钻石的特点。", "甜": "语义：钻石没有甜味，不能说“最甜的东西”。", "香": "语义：钻石没有香气，“最香的东西”与钻石的特点不符。", "聪明": "搭配：“聪明”形容人或动物的智力，不用于钻石。"}, "sentence_index": 0, "correct_answer": "硬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这团棉花很硬，抱在怀里很舒服。", "explanation": "这里应该用〈松软〉。棉花的软硬用“松软”；“硬”指物体坚固、不易变形，不能用来形容棉花。"}, {"text": "今天的天气很硬，风吹得人发抖。", "explanation": "这里应该用〈冷〉。天气的寒暖用“冷”；“硬”指物体坚固，不能用来形容天气。"}, {"text": "这壶茶很硬，倒出来很顺口。", "explanation": "这里应该用〈浓〉。茶的浓淡用“浓”；“硬”指物体坚固，不能用来形容茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬", "is_correct": true, "explanation": "正确。“硬的东西不容易弯”符合常识。"}, {"text": "软", "is_correct": false, "explanation": "语义：“软的东西”容易弯，与后半句“不容易弯”矛盾。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的心情，不用于物体。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容人的性情，不能形容东西。"}], "explanations": {"硬": "正确。“硬的东西不容易弯”符合常识。", "软": "语义：“软的东西”容易弯，与后半句“不容易弯”矛盾。", "高兴": "搭配：“高兴”形容人的心情，不用于物体。", "温柔": "搭配：“温柔”形容人的性情，不能形容东西。"}, "sentence_index": 6, "correct_answer": "硬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音很硬，听起来像在唱歌。", "explanation": "这里应该用〈好听〉。声音悦耳用“好听”；“硬”指物体坚固、不易变形，不能这样形容声音。"}, {"text": "这碗粥很硬，喝起来一点儿也不凉。", "explanation": "这里应该用〈热〉。粥的冷热用“热”；“硬”指物体坚固，不能用来形容粥的温度。"}, {"text": "这碗鸡汤很硬，喝起来很鲜。", "explanation": "这里应该用〈鲜〉。汤的味道用“鲜”；“硬”指物体坚固，不能用来形容汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块钢板硬的很，不容易弯。", "corrected_sentence": "这块钢板硬得很，不容易弯。", "error_description": "补语标记错误：形容词作程度补语时应用“得”（硬得很），不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根铁棍硬很，弯不了。", "corrected_sentence": "这根铁棍很硬，弯不了。", "error_description": "语序错误：程度副词“很”应放在形容词“硬”前，说“很硬”，不能说“硬很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9754eae-c3fc-4d5c-be41-c45b217946dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
