INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92715, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "君主是一个国家里最大的人，比如国王。", "primary_collocate": null, "pronunciation": "jūn zhǔ", "ipa": "tɕyn˥˥ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "君主是国家里最大的人。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国的君主很有钱。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的君主有一座金色的城堡。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "君主说话的时候，大家都很安静。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢听君主和公主的故事。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家有一位善良的君主。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "君主出门时，很多侍卫跟着他。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位君主每天都要见大臣。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“谁是这个国家的君主？”", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电影里演了一位君主。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位君主", "label": "量词"}, {"form": "君主制", "label": "复合"}, {"form": "君主国", "label": "复合"}], "register": "书面", "sense_fingerprint": "一个国家里最大的人，比如国王", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92715, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "君主", "is_correct": true, "explanation": "正确。君主指一个国家里最大的统治者，如国王。"}, {"text": "军属", "is_correct": false, "explanation": "第二音节声母不同：shǔ 为 sh，“主”为 zh。“军属”意思是军人的家属。"}, {"text": "均属", "is_correct": false, "explanation": "第二音节声母不同：shǔ 为 sh，“主”为 zh。“均属”意思是都属于某一类。"}, {"text": "军储", "is_correct": false, "explanation": "第二音节声母不同：chǔ 为 ch，“主”为 zh。“军储”意思是军用物资的储备。"}, {"text": "菌株", "is_correct": false, "explanation": "第二音节声调不同：zhū（第一声）与“主”zhǔ（第三声）。“菌株”意思是微生物的纯培养物。"}], "explanations": {"君主": "正确。君主指一个国家里最大的统治者，如国王。", "军属": "第二音节声母不同：shǔ 为 sh，“主”为 zh。“军属”意思是军人的家属。", "均属": "第二音节声母不同：shǔ 为 sh，“主”为 zh。“均属”意思是都属于某一类。", "军储": "第二音节声母不同：chǔ 为 ch，“主”为 zh。“军储”意思是军用物资的储备。", "菌株": "第二音节声调不同：zhū（第一声）与“主”zhǔ（第三声）。“菌株”意思是微生物的纯培养物。"}, "sentence_index": null, "correct_answer": "君主"}, "level_3": {"options": [{"text": "君主", "is_correct": true, "explanation": "正确。“君主”指国家里最大的人，与句子的定义相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”是种地的人，不是国家里最大的人。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”是念书的人，不是国家里地位最高的人。"}, {"text": "老板", "is_correct": false, "explanation": "搭配：“老板”指企业的负责人，与“国家里”的范围不搭配。"}], "explanations": {"君主": "正确。“君主”指国家里最大的人，与句子的定义相符。", "农民": "语义：“农民”是种地的人，不是国家里最大的人。", "学生": "语义：“学生”是念书的人，不是国家里地位最高的人。", "老板": "搭配：“老板”指企业的负责人，与“国家里”的范围不搭配。"}, "sentence_index": 0, "correct_answer": "君主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这家餐厅的君主，每天负责做饭。", "explanation": "这里应该用〈厨师〉。君主指国家的最高统治者，不能用来称呼餐厅的厨师。"}, {"text": "这个村子的君主说话的时候，大家都很安静。", "explanation": "这里应该用〈首领〉。君主指国家的最高统治者，不能用来称呼村子的负责人。"}, {"text": "我们学校的君主说话的时候，大家都很安静。", "explanation": "这里应该用〈校长〉。君主指国家的最高统治者，不能用来称呼学校的负责人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "君主", "is_correct": true, "explanation": "正确。“君主”是国家的最高统治者，出门时有很多侍卫跟随，与语境相符。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐身边通常没有侍卫跟随，与“很多侍卫跟着他”的语境相悖。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷出门时不会有很多侍卫跟着他，与语境相悖。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠是小动物，出门时不会有很多侍卫跟着，与语境相悖。"}], "explanations": {"君主": "正确。“君主”是国家的最高统治者，出门时有很多侍卫跟随，与语境相符。", "乞丐": "语义：乞丐身边通常没有侍卫跟随，与“很多侍卫跟着他”的语境相悖。", "小偷": "语义：小偷出门时不会有很多侍卫跟着他，与语境相悖。", "老鼠": "语义：老鼠是小动物，出门时不会有很多侍卫跟着，与语境相悖。"}, "sentence_index": 6, "correct_answer": "君主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的君主每天都很忙。", "explanation": "这里应该用〈老板〉。君主指国家的最高统治者，不能用来称呼公司的负责人。"}, {"text": "他是我们球队的君主，大家都听他指挥。", "explanation": "这里应该用〈队长〉。君主指国家的最高统治者，不能用来称呼球队的队长。"}, {"text": "那家工厂的君主每天都在车间里巡视。", "explanation": "这里应该用〈厂长〉。君主指国家的最高统治者，不能用来称呼工厂的负责人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只君主都来参加了会议。", "corrected_sentence": "两位君主都来参加了会议。", "error_description": "量词错误：“君主”指人，应用量词“位”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位聪明地君主很受百姓爱戴。", "corrected_sentence": "那位聪明的君主很受百姓爱戴。", "error_description": "结构助词错误：修饰名词“君主”要用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
