INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92716, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古代或君主制国家的最高统治者，如皇帝、国王。", "primary_collocate": null, "pronunciation": "jūn zhǔ", "ipa": "tɕyn˥˥ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "古代的君主住在很大的宫殿里。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位君主统治了国家四十年。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "君主一句话，大臣们就要照做。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国现在还有君主。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的君主会关心老百姓。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的君主是一位年轻的国王。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大臣们都很怕那位严厉的君主。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里写了很多有名的君主。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位君主死后，儿子成了新的君主。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当一位爱民的君主。", "target_word": "君主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位君主", "label": "量词"}, {"form": "君主制", "label": "复合"}, {"form": "君主国", "label": "复合"}], "register": "书面", "sense_fingerprint": "古代或君主制国家的最高统治者，如皇帝、国王", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "君主", "is_correct": true, "explanation": "正确。君主指古代或君主制国家的最高统治者，如皇帝、国王。"}, {"text": "军属", "is_correct": false, "explanation": "第二音节声母不同：shǔ 为 sh，“主”为 zh。“军属”意思是军人的家属。"}, {"text": "均属", "is_correct": false, "explanation": "第二音节声母不同：shǔ 为 sh，“主”为 zh。“均属”意思是都属于某一类。"}, {"text": "军储", "is_correct": false, "explanation": "第二音节声母不同：chǔ 为 ch，“主”为 zh。“军储”意思是军用物资的储备。"}, {"text": "菌株", "is_correct": false, "explanation": "第二音节声调不同：zhū（第一声）与“主”zhǔ（第三声）。“菌株”意思是微生物的纯培养物。"}], "explanations": {"君主": "正确。君主指古代或君主制国家的最高统治者，如皇帝、国王。", "军属": "第二音节声母不同：shǔ 为 sh，“主”为 zh。“军属”意思是军人的家属。", "均属": "第二音节声母不同：shǔ 为 sh，“主”为 zh。“均属”意思是都属于某一类。", "军储": "第二音节声母不同：chǔ 为 ch，“主”为 zh。“军储”意思是军用物资的储备。", "菌株": "第二音节声调不同：zhū（第一声）与“主”zhǔ（第三声）。“菌株”意思是微生物的纯培养物。"}, "sentence_index": null, "correct_answer": "君主"}, "level_3": {"options": [{"text": "君主", "is_correct": true, "explanation": "正确。“君主”指古代国家的最高统治者，住在很大的宫殿里符合语境。"}, {"text": "农民", "is_correct": false, "explanation": "语义：“农民”指种地的劳动者，不是统治者，与“住在很大的宫殿里”不合。"}, {"text": "士兵", "is_correct": false, "explanation": "语义：“士兵”是军人，一般住在营房，与“住在很大的宫殿里”不合。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”是商店或公司的主人，不是古代住在宫殿里的统治者。"}], "explanations": {"君主": "正确。“君主”指古代国家的最高统治者，住在很大的宫殿里符合语境。", "农民": "语义：“农民”指种地的劳动者，不是统治者，与“住在很大的宫殿里”不合。", "士兵": "语义：“士兵”是军人，一般住在营房，与“住在很大的宫殿里”不合。", "老板": "语义：“老板”是商店或公司的主人，不是古代住在宫殿里的统治者。"}, "sentence_index": 0, "correct_answer": "君主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的君主每天负责打扫教室。", "explanation": "这里应该用〈班长〉。君主指国家的最高统治者，不能用来称呼班里的负责人。"}, {"text": "他是这个村子的君主，大家都听他的。", "explanation": "这里应该用〈首领〉。君主指国家的最高统治者，不能用来称呼村子的负责人。"}, {"text": "这家公司的君主每天都很忙。", "explanation": "这里应该用〈老板〉。君主指国家的最高统治者，不能用来称呼公司的负责人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "君主", "is_correct": true, "explanation": "正确。“君主”是国家的最高统治者，大臣们敬畏他，与语境相符。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：大臣们不会因为一个小学生而畏惧，“小学生”与“大臣们”的身份不合。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“严厉的”描写管束他人的人，修饰“病人”不搭配。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：“园丁”是照料花木的工人，不是大臣们畏惧的对象。"}], "explanations": {"君主": "正确。“君主”是国家的最高统治者，大臣们敬畏他，与语境相符。", "小学生": "语义：大臣们不会因为一个小学生而畏惧，“小学生”与“大臣们”的身份不合。", "病人": "搭配：“严厉的”描写管束他人的人，修饰“病人”不搭配。", "园丁": "语义：“园丁”是照料花木的工人，不是大臣们畏惧的对象。"}, "sentence_index": 6, "correct_answer": "君主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的君主很严格，学生都怕他。", "explanation": "这里应该用〈校长〉。君主指国家的最高统治者，不能用来称呼学校的负责人。"}, {"text": "他是我们球队的君主，大家都听他指挥。", "explanation": "这里应该用〈队长〉。君主指国家的最高统治者，不能用来称呼球队的队长。"}, {"text": "那家工厂的君主每天都在车间里巡视。", "explanation": "这里应该用〈厂长〉。君主指国家的最高统治者，不能用来称呼工厂的负责人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只君主从小就很喜欢读书。", "corrected_sentence": "那位君主从小就很喜欢读书。", "error_description": "量词错误：“君主”指人，应用量词“位”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想当一位聪明地君主。", "corrected_sentence": "他想当一位聪明的君主。", "error_description": "结构助词错误：修饰名词“君主”要用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
