INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92717, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92717, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "问路是不知道路怎么走，就去问别人。", "primary_collocate": null, "pronunciation": "wèn lù", "ipa": "wən˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "不知道怎么走的时候，最好马上问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走到十字路口，不知道往哪边走，就停下来问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸以前开车出门，常常停车问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迷路了，却不愿意问路，结果越走越远。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在小镇上问路很容易，大家都会指给你看。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，旅行时学会问路很有用。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拦住一位阿姨问路，她还带我走了一段。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次来北京，不会用地图，只能问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找不到饭店，我们下车去问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是找不到地方，可以问路啊。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问了路", "label": "完成体"}, {"form": "问过路", "label": "经历体"}, {"form": "问问路", "label": "重叠"}], "register": "中性", "sense_fingerprint": "不知道路怎么走时去问别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问路", "is_correct": true, "explanation": "正确：不知道怎么走时去询问别人，正是“问路”的意思，与句意一致。"}, {"text": "指路", "is_correct": false, "explanation": "语义：“指路”是给别人指明方向，句中说的是不知道怎么走的人，不能用来指路。"}, {"text": "问好", "is_correct": false, "explanation": "语义：“问好”是打招呼，与不知道怎么走的语境无关，不能用于此处。"}, {"text": "投诉", "is_correct": false, "explanation": "语域：“投诉”偏正式，是对不满意的事表达意见，与日常求助的口语语境不合。"}], "explanations": {"问路": "正确：不知道怎么走时去询问别人，正是“问路”的意思，与句意一致。", "指路": "语义：“指路”是给别人指明方向，句中说的是不知道怎么走的人，不能用来指路。", "问好": "语义：“问好”是打招呼，与不知道怎么走的语境无关，不能用于此处。", "投诉": "语域：“投诉”偏正式，是对不满意的事表达意见，与日常求助的口语语境不合。"}, "sentence_index": 0, "correct_answer": "问路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一进教室，同学们就齐声向老师问路。", "explanation": "这里应该用〈问好〉。问路是打听道路，进教室时齐声向老师打招呼要说问好。"}, {"text": "给远方的朋友打电话，我们先向他问路。", "explanation": "这里应该用〈问候〉。问路表示打听方向，打电话时先向朋友问候近况，应说问候。"}, {"text": "每天早上起床后，他都向父母问路。", "explanation": "这里应该用〈问安〉。早上向父母请安要说问安，问路表示打听道路，与此处情境不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问路", "is_correct": true, "explanation": "正确：拦住阿姨是为了询问道路，之后她带我走了一段，前后文一致。"}, {"text": "请客", "is_correct": false, "explanation": "语义：“请客”是请吃饭，与拦住路人、她带路的情节不符。"}, {"text": "催促", "is_correct": false, "explanation": "语义：“催促”是催人快一点，与她带我走一段路的情节没有关联。"}, {"text": "致谢", "is_correct": false, "explanation": "语域：“致谢”偏书面、正式，口语中拦住路人时不会这样说，且与后文的情节不合。"}], "explanations": {"问路": "正确：拦住阿姨是为了询问道路，之后她带我走了一段，前后文一致。", "请客": "语义：“请客”是请吃饭，与拦住路人、她带路的情节不符。", "催促": "语义：“催促”是催人快一点，与她带我走一段路的情节没有关联。", "致谢": "语域：“致谢”偏书面、正式，口语中拦住路人时不会这样说，且与后文的情节不合。"}, "sentence_index": 6, "correct_answer": "问路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们向他打听去会场的路，他站在岔路口，一边指着方向，一边给我们问路。", "explanation": "这里应该用〈指路〉。我们已经向他打听，他是在指给我们看怎么走，应说指路，问路是打听道路。"}, {"text": "我们向保安问路，他没有回答，只在前面问路，把我们一直带进了会场。", "explanation": "这里应该用〈带路〉。我们是向保安问路，他在前面引导我们走，应说带路，问路是打听道路。"}, {"text": "我们向一位大爷问路，他没有开口，却在前面问路，一直领我们走到了车站。", "explanation": "这里应该用〈领路〉。我们是向大爷问路，他在前面带我们走，应说领路，问路是向人打听道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在国外旅行时，曾经向当地人问路过。", "corrected_sentence": "我在国外旅行时，曾经向当地人问过路。", "error_description": "“过”表示曾经有过的经历，应紧跟动词：“问过路”，不能放在宾语“路”之后说“问路过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车停在路口，我下车给一个路人问路。", "corrected_sentence": "车停在路口，我下车向一个路人问路。", "error_description": "“问路”的对象要用介词“向”引出：“向＋人＋问路”，不能用“给”说“给一个路人问路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
