INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92718, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向人打听道路怎么走。", "primary_collocate": null, "pronunciation": "wèn lù", "ipa": "wən˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "我迷路了，只好向路边的老人问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思问路，一直在街上转圈。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客在地铁站门口向警察问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，我只能找行人问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在陌生的城市第一次问路，大家都很热情。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机把车停在路边，下车去问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车从来不用导航，总是靠问路找地方。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教孩子，迷路时可以向警察叔叔问路。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王问路的时候，声音很小。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国游客用中文问路，我听懂了。", "target_word": "问路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问了路", "label": "完成体"}, {"form": "问过路", "label": "经历体"}, {"form": "问问路", "label": "重叠"}], "register": "中性", "sense_fingerprint": "向人打听道路怎么走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问路", "is_correct": true, "explanation": "正确：“向路边的老人问路”指向人打听道路，与“我迷路了”的语境一致。"}, {"text": "问候", "is_correct": false, "explanation": "语义：“问候”是打招呼、问好，与迷路后只好求助的情境不符。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：“道歉”是认错赔礼，句中没有需要道歉的过失，不能用于此处。"}, {"text": "投诉", "is_correct": false, "explanation": "语域：“投诉”偏正式、书面，多用于对不满意的事表达意见，与口语化的求助语境不合。"}], "explanations": {"问路": "正确：“向路边的老人问路”指向人打听道路，与“我迷路了”的语境一致。", "问候": "语义：“问候”是打招呼、问好，与迷路后只好求助的情境不符。", "道歉": "语义：“道歉”是认错赔礼，句中没有需要道歉的过失，不能用于此处。", "投诉": "语域：“投诉”偏正式、书面，多用于对不满意的事表达意见，与口语化的求助语境不合。"}, "sentence_index": 0, "correct_answer": "问路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察在审讯室里向嫌疑人问路。", "explanation": "这里应该用〈问话〉。问路是打听道路怎么走，此处是警察在审讯室里盘问嫌疑人，应说问话。"}, {"text": "早上在楼下碰到邻居，我们互相问路。", "explanation": "这里应该用〈问候〉。问路表示打听方向，邻居在早上见面时互相打招呼应说问候。"}, {"text": "每天早上给父母打电话，我先向他们问路。", "explanation": "这里应该用〈问安〉。向父母请安要说问安，问路表示打听道路，与早晨通话的情境不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问路", "is_correct": true, "explanation": "正确：“靠问路找地方”指通过询问别人来找地方，与“从来不用导航”的句意一致。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与找地方无关，靠睡觉不可能找到地方。"}, {"text": "喊", "is_correct": false, "explanation": "语义：“喊”只是大声发出声音，靠喊找地方不合常理，也与“不用导航”的说法不搭。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与找地方无关，靠吃饭不可能找到地方。"}], "explanations": {"问路": "正确：“靠问路找地方”指通过询问别人来找地方，与“从来不用导航”的句意一致。", "睡觉": "语义：“睡觉”与找地方无关，靠睡觉不可能找到地方。", "喊": "语义：“喊”只是大声发出声音，靠喊找地方不合常理，也与“不用导航”的说法不搭。", "吃饭": "语义：“吃饭”与找地方无关，靠吃饭不可能找到地方。"}, "sentence_index": 6, "correct_answer": "问路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客问他去车站怎么走，他站在路口，一边比划，一边给游客问路。", "explanation": "这里应该用〈指路〉。游客已经开口问路，此处是他告诉游客怎么走，应说指路，问路是向人打听道路。"}, {"text": "我们向司机问路，他没有回答，只在前面问路，一直把我们送到了大门口。", "explanation": "这里应该用〈带路〉。我们是向司机问路，他在前面引导我们走，应说带路，问路是打听道路。"}, {"text": "我们向一位大爷问路，他没有开口，却在前面问路，一直领我们走到了车站门口。", "explanation": "这里应该用〈领路〉。我们是向大爷问路，他在前面带我们走，应说领路，问路是向人打听道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我迷路了，只好大叔问路。", "corrected_sentence": "我迷路了，只好向大叔问路。", "error_description": "“问路”带人作对象时要用“向＋人＋问路”，此处漏掉介词“向”，应说“只好向大叔问路”，不能说“只好大叔问路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在火车站问路过，但是听不懂方言。", "corrected_sentence": "他在火车站问过路，但是听不懂方言。", "error_description": "“过”表示曾经有过的经历，应紧跟动词：“问过路”，不能放在宾语“路”之后说“问路过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
