INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于预防、治疗疾病的物品。", "primary_collocate": null, "pronunciation": "yào pǐn", "ipa": "jɑʊ̯˥˩ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "药店里的药品都放在高高的架子上。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品过期以后，就不能再吃了。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种药品每天要吃两次。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买药品以前，请先看一看说明书。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门生产治感冒的药品。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品应该放在孩子拿不到的地方。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对药品的价格管得很严。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在药店工作，每天都要检查药品。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，她带了一些常用的药品。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品的包装上写着有效日期。", "target_word": "药品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种药品", "label": "量词"}, {"form": "藥品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用于预防、治疗疾病的物品，如药店里卖的药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6c760cb-57e2-4f62-a33d-bc36fa2b95af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "药品", "is_correct": true, "explanation": "药品指治病用的物品，放在药店架子上的正是药品，句意完整。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：药店不卖蔬菜，蔬菜不会出现在药店的架子上。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“放在高高的架子上”一般用于小件物品，汽车放不上去。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食品，药店的架子上一般不会放面包。"}], "explanations": {"药品": "药品指治病用的物品，放在药店架子上的正是药品，句意完整。", "蔬菜": "语义：药店不卖蔬菜，蔬菜不会出现在药店的架子上。", "汽车": "搭配：“放在高高的架子上”一般用于小件物品，汽车放不上去。", "面包": "语义：面包是食品，药店的架子上一般不会放面包。"}, "sentence_index": 0, "correct_answer": "药品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我经常去药品买药。", "explanation": "这里应该用〈药店〉。药品是物品，不能当作“去”的地方，去买药要说“去药店”。"}, {"text": "我明天要去药品看病。", "explanation": "这里应该用〈医院〉。药品是东西，不是可以去看病的地方，去看病要说“去医院”。"}, {"text": "他很会弹药品。", "explanation": "这里应该用〈钢琴〉。弹的是乐器，药品是治病用的物品，不能用“弹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "药品", "is_correct": true, "explanation": "药品可以定价，国家对它的价格管得严，句意合理。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能定价，“国家对空气的价格管得很严”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的高矮，不是商品，不能说“身高的价格”。"}, {"text": "眼神", "is_correct": false, "explanation": "搭配：“价格”要用于可以定价的东西，“眼神”不能说“眼神的价格”。"}], "explanations": {"药品": "药品可以定价，国家对它的价格管得严，句意合理。", "空气": "语义：空气不能定价，“国家对空气的价格管得很严”说不通。", "身高": "语义：身高是身体的高矮，不是商品，不能说“身高的价格”。", "眼神": "搭配：“价格”要用于可以定价的东西，“眼神”不能说“眼神的价格”。"}, "sentence_index": 6, "correct_answer": "药品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是药品，每天在药房工作。", "explanation": "这里应该用〈药师〉。药师是人，药品是物品，不能说“他是药品”。"}, {"text": "这家饭馆的药品很好吃。", "explanation": "这里应该用〈菜〉。“好吃”用于食物，药品不能说“好吃”。"}, {"text": "这位画家的药品很感人。", "explanation": "这里应该用〈作品〉。“感人”形容作品；药品是治病用的物品，不能用“感人”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我吃过这种药品们，效果很好。", "corrected_sentence": "我吃过这种药品，效果很好。", "error_description": "复数标记错误：“们”不能用于“药品”这类物品名词，且前面已有“这种”，应说“这种药品”，不能说“这种药品们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只药品需要放在阴凉的地方。", "corrected_sentence": "这种药品需要放在阴凉的地方。", "error_description": "量词错误：“药品”要用“种”，应说“这种药品”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
