INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92727, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "四周是一个东西的前面、后面、左边和右边。", "primary_collocate": null, "pronunciation": "sì zhōu", "ipa": "sɨ˥˩ ʈʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "房子的四周种着很多树。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书桌的四周堆满了书。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子的四周都有划痕。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的四周有一条小河。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把椅子放在桌子的四周。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐在老师的四周听故事。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头的四周长满了青苔。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明转过头，看了看教室的四周。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼的四周都是花园。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在院子中间，四周围着一圈人。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个东西前后左右各个方向的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92727, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地板", "is_correct": false, "explanation": "搭配：“种着”要求能种植的场所，地板是室内地面，不能种树。"}, {"text": "四周", "is_correct": true, "explanation": "正确：“四周”指房子前后左右各个方向的地方，可以和“种着很多树”搭配。"}, {"text": "柜子", "is_correct": false, "explanation": "语义：柜子是家具，不是可以种树的地方。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是照明用具，不能用来种树。"}], "explanations": {"地板": "搭配：“种着”要求能种植的场所，地板是室内地面，不能种树。", "四周": "正确：“四周”指房子前后左右各个方向的地方，可以和“种着很多树”搭配。", "柜子": "语义：柜子是家具，不是可以种树的地方。", "灯泡": "语义：灯泡是照明用具，不能用来种树。"}, "sentence_index": 0, "correct_answer": "四周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃掉了四周。", "explanation": "这里应该用〈蛋糕〉这类食物。四周是方位名词，指物体周围的各个方向，不是能吃的东西。"}, {"text": "我把钥匙放进了四周。", "explanation": "这里应该用〈口袋〉。四周指外围的方向，不是能装东西的空间，放进去要说口袋或抽屉。"}, {"text": "他撕碎了四周。", "explanation": "这里应该用〈纸〉。四周是方位，不能被撕碎，撕的对象应是纸之类的具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "语义：重量是数值，不是可以长青苔的部位。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色只指外观的色彩，石头的颜色不会“长满”青苔。"}, {"text": "四周", "is_correct": true, "explanation": "正确：“四周”指石头周围的部位，可以长满青苔。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是钱数，不是实物，不能长青苔。"}], "explanations": {"重量": "语义：重量是数值，不是可以长青苔的部位。", "颜色": "体貌：颜色只指外观的色彩，石头的颜色不会“长满”青苔。", "四周": "正确：“四周”指石头周围的部位，可以长满青苔。", "价格": "语义：价格是钱数，不是实物，不能长青苔。"}, "sentence_index": 6, "correct_answer": "四周"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛开始前，他把四周穿在身上。", "explanation": "这里应该用〈衣服〉。四周是方位，不能穿在身上，穿的应是衣服。"}, {"text": "他把四周抄在了笔记本上。", "explanation": "这里应该用〈课文〉。四周是方位，不能被抄写，抄的应是文字内容。"}, {"text": "她把四周装进了书包。", "explanation": "这里应该用〈课本〉。四周是方位，不是可以装进书包的具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池塘的一个四周长着一圈芦苇。", "corrected_sentence": "池塘的四周长着一圈芦苇。", "error_description": "错误形式：“池塘的一个四周”；正确形式：“池塘的四周”。“四周”是方位名词，不能直接用“一个”修饰，去掉“一个”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子四周的围着一道矮墙。", "corrected_sentence": "院子四周围着一道矮墙。", "error_description": "错误形式：“院子四周的围着一道矮墙”；正确形式：“院子四周围着一道矮墙”。“四周”是方位名词，后面加“的”需要一个中心语，句中没有，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
