INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92728, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "周围；某一中心点或物体的四面。", "primary_collocate": null, "pronunciation": "sì zhōu", "ipa": "sɨ˥˩ ʈʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "这座城市的四周都是高山。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖的四周开满了黄色的花。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "着火了，四周都是烟。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在广场中间停下来，看了看四周。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子四周有一片绿色的田地。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家四周的邻居都很热情。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师走进教室，四周马上安静了。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地的四周围着一道高墙。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四周的人都在看着他。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山后，四周慢慢黑了。", "target_word": "四周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "以某个中心点或物体为中心的周围各面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市中心", "is_correct": false, "explanation": "语义：市中心是城市的中心地带，不会被高山环绕。"}, {"text": "四周", "is_correct": true, "explanation": "正确：“四周”指城市周围的各个方向，与“都是高山”搭配。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是地下的交通系统，不可能是高山。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“都是高山”要说地方或物体，“价格”不能说成山。"}], "explanations": {"市中心": "语义：市中心是城市的中心地带，不会被高山环绕。", "四周": "正确：“四周”指城市周围的各个方向，与“都是高山”搭配。", "地铁": "语义：地铁是地下的交通系统，不可能是高山。", "价格": "搭配：“都是高山”要说地方或物体，“价格”不能说成山。"}, "sentence_index": 0, "correct_answer": "四周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书放进了四周。", "explanation": "这里应该用〈书包〉。四周指外围的方向，不是能装东西的空间，放进去要说书包或抽屉。"}, {"text": "他打碎了四周。", "explanation": "这里应该用〈玻璃〉。四周是方位，不能被打碎，打碎的应是玻璃之类的具体物品。"}, {"text": "他切开了四周。", "explanation": "这里应该用〈面包〉。四周是方位，不能被切开，切的应是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物品，本身没有声音，不会安静。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“安静”多用于人、场所或声音，天气不能说安静。"}, {"text": "四周", "is_correct": true, "explanation": "正确：“四周”指教室周围的人或环境，老师走进来后它们马上安静了。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是布制的遮挡物，不会“安静”。"}], "explanations": {"黑板": "语义：黑板是物品，本身没有声音，不会安静。", "天气": "搭配：“安静”多用于人、场所或声音，天气不能说安静。", "四周": "正确：“四周”指教室周围的人或环境，老师走进来后它们马上安静了。", "窗帘": "语义：窗帘是布制的遮挡物，不会“安静”。"}, "sentence_index": 6, "correct_answer": "四周"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试开始前，他把四周戴在头上。", "explanation": "这里应该用〈帽子〉。四周是方位，不能戴在头上，戴的应是帽子之类的物品。"}, {"text": "她把四周装进了行李箱。", "explanation": "这里应该用〈衣服〉。四周是方位，不是可以装进行李箱的具体物品。"}, {"text": "妈妈把四周抄在了笔记本上。", "explanation": "这里应该用〈字〉。四周是方位，不能被抄写，抄的应是文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村庄四周的围着一圈矮墙。", "corrected_sentence": "村庄四周围着一圈矮墙。", "error_description": "错误形式：“村庄四周的围着一圈矮墙”；正确形式：“村庄四周围着一圈矮墙”。“四周”是方位名词，后面加“的”需要一个中心语，句中没有，应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的一个四周种满了树。", "corrected_sentence": "学校的四周种满了树。", "error_description": "错误形式：“学校的一个四周”；正确形式：“学校的四周”。“四周”是方位名词，不能直接用“一个”修饰，去掉“一个”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92729, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "参加", "is_correct": false, "explanation": "与“认定”没有反义关系，不表示相反的意思。"}, {"text": "怀疑", "is_correct": true, "explanation": "“怀疑”与“认定”的“心里肯定”义正相反。"}, {"text": "保护", "is_correct": false, "explanation": "与“认定”没有反义关系，二者意义无对立。"}, {"text": "离开", "is_correct": false, "explanation": "与“认定”没有反义关系，不表示相反的判断。"}], "correct_answer": "怀疑", "explanations": {"参加": "与“认定”没有反义关系，不表示相反的意思。", "怀疑": "“怀疑”与“认定”的“心里肯定”义正相反。", "保护": "与“认定”没有反义关系，二者意义无对立。", "离开": "与“认定”没有反义关系，不表示相反的判断。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92729, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": false, "explanation": "与“认定”没有反义关系，二者意义无对立。"}, {"text": "放弃", "is_correct": false, "explanation": "与“认定”的“心里肯定”义没有反义关系，不表示相反的判断。"}, {"text": "怀疑", "is_correct": true, "explanation": "“怀疑”与“认定”的“心里肯定”义正相反。"}, {"text": "结婚", "is_correct": false, "explanation": "与“认定”没有反义关系，不表示相反的意思。"}], "correct_answer": "怀疑", "explanations": {"开始": "与“认定”没有反义关系，二者意义无对立。", "放弃": "与“认定”的“心里肯定”义没有反义关系，不表示相反的判断。", "怀疑": "“怀疑”与“认定”的“心里肯定”义正相反。", "结婚": "与“认定”没有反义关系，不表示相反的意思。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92729, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "认定是心里肯定，觉得就是这样。", "primary_collocate": null, "pronunciation": "rèn dìng", "ipa": "ʐən˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我认定他是好人，所以相信他。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里认定哥哥会回来。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么认定我在骗你？", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认定那个人就是自己小时候的朋友。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子认定妈妈不爱他，一直哭。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早就认定这件事不会成功。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认定那只狗是自己弄丢的。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王认定今天会下雨，带了伞。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别太早认定一个人不好。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认定那封信是朋友写的。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认定了", "label": "体标"}], "register": "中性", "sense_fingerprint": "心里肯定，觉得事情就是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "答应", "is_correct": false, "explanation": "配价：“答应”带的是承诺或请求，不能直接接“他是好人”这样的判断句。"}, {"text": "认定", "is_correct": true, "explanation": "“认定”表示心里肯定，与“所以相信他”的语义相符。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与后面“所以相信他”的语气相矛盾。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示看不上，与后面“所以相信他”的语气相矛盾。"}], "explanations": {"答应": "配价：“答应”带的是承诺或请求，不能直接接“他是好人”这样的判断句。", "认定": "“认定”表示心里肯定，与“所以相信他”的语义相符。", "讨厌": "语义：“讨厌”表示厌恶，与后面“所以相信他”的语气相矛盾。", "嫌弃": "语义：“嫌弃”表示看不上，与后面“所以相信他”的语气相矛盾。"}, "sentence_index": 0, "correct_answer": "认定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认定自己明天也许去北京。", "explanation": "这里不能用〈认定〉。认定表示心里很肯定，与“也许”的不确定语气矛盾；表示推测应用〈觉得〉。"}, {"text": "我认定他是好人，可是一点儿也不相信他。", "explanation": "这里不能用〈认定〉。认定表示心里很肯定，与“一点儿也不相信”矛盾；表示不确定应用〈怀疑〉。"}, {"text": "我认定好像要下雨了。", "explanation": "这里不能用〈认定〉。认定表示心里很肯定，与“好像”的推测语气矛盾；表示推测应用〈觉得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庆幸", "is_correct": false, "explanation": "语义：“庆幸”表示为好事而高兴，与“自己弄丢”这种坏事不合。"}, {"text": "看见", "is_correct": false, "explanation": "配价：“看见”带的是具体的人或物，不能直接接“那只狗是自己弄丢的”这样的判断句。"}, {"text": "认定", "is_correct": true, "explanation": "“认定”表示心里肯定，与“那只狗是自己弄丢的”的判断相符。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”的对象是产品或事件，不能用于表示对事情的判断。"}], "explanations": {"庆幸": "语义：“庆幸”表示为好事而高兴，与“自己弄丢”这种坏事不合。", "看见": "配价：“看见”带的是具体的人或物，不能直接接“那只狗是自己弄丢的”这样的判断句。", "认定": "“认定”表示心里肯定，与“那只狗是自己弄丢的”的判断相符。", "制造": "搭配：“制造”的对象是产品或事件，不能用于表示对事情的判断。"}, "sentence_index": 6, "correct_answer": "认定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信认定它是朋友写的。", "explanation": "认定的主语应是人，信件不能“认定”。这里应该用〈证明〉。"}, {"text": "她认定那封信或许是朋友写的。", "explanation": "这里不能用〈认定〉。认定表示心里肯定，与“或许”的不确定语气矛盾；表示推测应用〈猜测〉。"}, {"text": "她认定那封信是朋友写的，可又觉得不是。", "explanation": "这里不能用〈认定〉。认定表示心里肯定，与后面的犹豫矛盾；表示拿不准应用〈怀疑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认定他个诚实的人。", "corrected_sentence": "我认定他是个诚实的人。", "error_description": "错误形式：认定他个诚实的人；正确形式：认定他是个诚实的人。“认定”后接“他”加判断时需要用“是”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师认定他撒谎着。", "corrected_sentence": "老师认定他撒谎了。", "error_description": "错误形式：老师认定他撒谎着；正确形式：老师认定他撒谎了。“撒谎”是已经发生的事，应用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92730, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "参加", "is_correct": false, "explanation": "与“认定”没有反义关系，不表示相反的意思。"}, {"text": "否定", "is_correct": true, "explanation": "“否定”表示断定不是这样，与“认定”的“确认”义正相反。"}, {"text": "保护", "is_correct": false, "explanation": "与“认定”没有反义关系，二者意义无对立。"}, {"text": "离开", "is_correct": false, "explanation": "与“认定”没有反义关系，不表示相反的判断。"}], "correct_answer": "否定", "explanations": {"参加": "与“认定”没有反义关系，不表示相反的意思。", "否定": "“否定”表示断定不是这样，与“认定”的“确认”义正相反。", "保护": "与“认定”没有反义关系，二者意义无对立。", "离开": "与“认定”没有反义关系，不表示相反的判断。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92730, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": false, "explanation": "与“认定”没有反义关系，二者意义无对立。"}, {"text": "放弃", "is_correct": false, "explanation": "与“认定”的“确认”义没有反义关系，不表示相反的判断。"}, {"text": "否定", "is_correct": true, "explanation": "“否定”表示断定不是这样，与“认定”的“确认”义正相反。"}, {"text": "结婚", "is_correct": false, "explanation": "与“认定”没有反义关系，不表示相反的意思。"}], "correct_answer": "否定", "explanations": {"开始": "与“认定”没有反义关系，二者意义无对立。", "放弃": "与“认定”的“确认”义没有反义关系，不表示相反的判断。", "否定": "“否定”表示断定不是这样，与“认定”的“确认”义正相反。", "结婚": "与“认定”没有反义关系，不表示相反的意思。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92730, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "确认；坚定地认为。", "primary_collocate": null, "pronunciation": "rèn dìng", "ipa": "ʐən˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "警方认定他就是那个小偷。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生认定这是感冒，不用住院。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师认定小李一定能考上大学。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认定这件事是他做的。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认定这条路是对的，不会改了。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院认定这份合同无效。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认定这家面包店最好，每周都来买。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司认定这次问题是机器坏了。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认定自己没有错，不想道歉。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认定这张画是真的。", "target_word": "认定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认定了", "label": "体标"}], "register": "中性", "sense_fingerprint": "经判断后确认，并坚定地认为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，与“小偷”的身份相反，句子说警方在称赞小偷，说不通。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆贺喜事，与“那个小偷”的身份不合，句子说不通。"}, {"text": "认定", "is_correct": true, "explanation": "“认定”表示经判断后确定，与警方作出判断的语境相符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“那个小偷”的指控矛盾。"}], "explanations": {"夸奖": "语义：“夸奖”是称赞，与“小偷”的身份相反，句子说警方在称赞小偷，说不通。", "祝贺": "语义：“祝贺”表示庆贺喜事，与“那个小偷”的身份不合，句子说不通。", "认定": "“认定”表示经判断后确定，与警方作出判断的语境相符。", "赞美": "语义：“赞美”表示称赞，与“那个小偷”的指控矛盾。"}, "sentence_index": 0, "correct_answer": "认定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认定明天也许去北京。", "explanation": "这里不能用〈认定〉。认定表示确定，与“也许”的不确定语气矛盾；表示推测应用〈觉得〉。"}, {"text": "警方认定他是小偷，但还不能确定。", "explanation": "这里不能用〈认定〉。认定表示经判断后确认，与“还不能确定”矛盾；应改用〈怀疑〉。"}, {"text": "这件事认定他是小偷。", "explanation": "认定的主语应是人或机构，事情不能“认定”。这里应该用〈证明〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认定", "is_correct": true, "explanation": "“认定”表示断定、坚信，与“最好”的评价和“每周都来买”的行为相符。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示不喜欢，与“最好”和“每周都来买”相矛盾。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是技术或产品，不能用来表示对店铺优劣的判断。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出缺点，与“最好”的评价相反，也与每周光顾的行为不符。"}], "explanations": {"认定": "“认定”表示断定、坚信，与“最好”的评价和“每周都来买”的行为相符。", "讨厌": "语义：“讨厌”表示不喜欢，与“最好”和“每周都来买”相矛盾。", "发明": "搭配：“发明”的对象是技术或产品，不能用来表示对店铺优劣的判断。", "批评": "语义：“批评”指指出缺点，与“最好”的评价相反，也与每周光顾的行为不符。"}, "sentence_index": 6, "correct_answer": "认定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认定了一场比赛。", "explanation": "这里不能用〈认定〉直接带“比赛”这类活动作宾语，活动应说〈举行〉。"}, {"text": "专家认定这张画也许是真的。", "explanation": "这里不能用〈认定〉。认定表示确定、坚信，与“也许”的不确定语气矛盾；表示推测应用〈认为〉。"}, {"text": "这张画认定那位画家是骗子。", "explanation": "认定的主语应是人或机构，画不能“认定”。这里应该用〈证明〉，指由证据显示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官认定这份证据被假。", "corrected_sentence": "法官认定这份证据是假的。", "error_description": "错误形式：法官认定这份证据被假；正确形式：法官认定这份证据是假的。“被”后须接及物动词，“假”是形容词，不能直接用“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "陪审团认定他了无罪。", "corrected_sentence": "陪审团认定了他无罪。", "error_description": "错误形式：认定他了无罪；正确形式：认定了他无罪。“了”应紧跟动词“认定”，表示完成的体标不能放在宾语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
