INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92732, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事报刊编辑、采访、出版工作的人。", "primary_collocate": null, "pronunciation": "bào rén", "ipa": "pau˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他是一位资深报人，一生致力于新闻出版。", "target_word": "报人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位报人长期从事报刊编辑工作。", "target_word": "报人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "许多报人在战争年代坚持出版报纸。", "target_word": "报人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从记者做到总编辑，是有名的报人。", "target_word": "报人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位报人创办了一份有影响的报刊。", "target_word": "报人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为报人，他重视新闻的真实性。", "target_word": "报人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老一辈报人为中国新闻事业付出了很多。", "target_word": "报人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位报人曾在多家报社担任主编。", "target_word": "报人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报人的责任是向社会提供可靠的信息。", "target_word": "报人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以报人的身份参加了这次新闻研讨会。", "target_word": "报人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "報人", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从事报刊编辑、采访、出版的新闻出版从业者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报人", "is_correct": true, "explanation": "正确。报人指从事报刊编辑、采访、出版的人，与“致力于新闻出版”相符。"}, {"text": "画家", "is_correct": false, "explanation": "语义：画家画画，与新闻出版无关。"}, {"text": "诗人", "is_correct": false, "explanation": "语义：诗人写诗，与新闻出版的工作不符。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：“一位资深”修饰人，空调是器物，不能用“一位”或“资深”来形容。"}], "explanations": {"报人": "正确。报人指从事报刊编辑、采访、出版的人，与“致力于新闻出版”相符。", "画家": "语义：画家画画，与新闻出版无关。", "诗人": "语义：诗人写诗，与新闻出版的工作不符。", "空调": "搭配：“一位资深”修饰人，空调是器物，不能用“一位”或“资深”来形容。"}, "sentence_index": 0, "correct_answer": "报人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位报人负责设计这座桥的结构。", "explanation": "这里应该用〈工程师〉。报人指报刊从业者，负责设计桥梁结构的是工程师。"}, {"text": "这份报人很厚，有很多版面。", "explanation": "这里应该用〈报纸〉。报人指从事报刊工作的人，不指报纸这一物件。"}, {"text": "这位报人每天都在理发店里为客人剪头发。", "explanation": "这里应该用〈理发师〉。报人指报刊从业者，为客人剪头发的是理发师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报人", "is_correct": true, "explanation": "正确。老一辈报人指从事报刊工作的前辈，与“为新闻事业付出”相符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民种地，与新闻事业无关。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员参加比赛，与新闻事业不相干。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“老一辈”只修饰人，桌子不能用“老一辈”来形容。"}], "explanations": {"报人": "正确。老一辈报人指从事报刊工作的前辈，与“为新闻事业付出”相符。", "农民": "语义：农民种地，与新闻事业无关。", "运动员": "语义：运动员参加比赛，与新闻事业不相干。", "桌子": "搭配：“老一辈”只修饰人，桌子不能用“老一辈”来形容。"}, "sentence_index": 6, "correct_answer": "报人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位报人每天带领球员训练，准备比赛。", "explanation": "这里应该用〈教练〉。报人指报刊从业者，带领球员训练、准备比赛的是教练。"}, {"text": "那位报人在手术室做了一台手术。", "explanation": "这里应该用〈医生〉。报人是报刊从业者，不做手术。"}, {"text": "他每天早上都报人最新的消息。", "explanation": "这里应该用〈报道〉。报人是名词，不能当动词用，“报道最新的消息”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时过当报人，后来当了老师。", "corrected_sentence": "他年轻时当过报人，后来当了老师。", "error_description": "体标错误：“过”应放在动词“当”之后，说“当过报人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条报人很有名。", "corrected_sentence": "那位报人很有名。", "error_description": "量词错误：报人指人，量词应用〈位〉；“条”用于细长的物体，不能修饰人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
