INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92733, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92733, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "轨道是火车跑的那两条铁路。", "primary_collocate": null, "pronunciation": "guǐ dào", "ipa": "kweɪ̯˨˩ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "火车在轨道上跑得很快。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在修这条轨道。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轨道上有一块大石头，火车停下了。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不要在轨道上玩。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条轨道一直通到山里。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁的轨道在地下。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一列火车离开了轨道，大家很担心。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轨道两边种着很多树。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把耳朵放在轨道上听火车声。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人换了一段旧轨道。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条轨道", "label": "量词"}, {"form": "轨道交通", "label": "复合"}], "register": "中性", "sense_fingerprint": "火车行驶的铁轨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9d6783f-ace1-4265-9d14-fc3a3d5379b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92733, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轨道", "is_correct": true, "explanation": "轨道：火车在铁路上跑，“在……上”搭配正确，与“轨道”的意思一致。"}, {"text": "公路", "is_correct": false, "explanation": "语义：公路供汽车行驶，火车不在公路上跑。"}, {"text": "草地", "is_correct": false, "explanation": "语义：火车不会在草地上跑，草地不是铁路。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“在……上”不用于车站，这里应说“在车站”，与“跑得很快”的铁路路线不符。"}], "explanations": {"轨道": "轨道：火车在铁路上跑，“在……上”搭配正确，与“轨道”的意思一致。", "公路": "语义：公路供汽车行驶，火车不在公路上跑。", "草地": "语义：火车不会在草地上跑，草地不是铁路。", "车站": "搭配：“在……上”不用于车站，这里应说“在车站”，与“跑得很快”的铁路路线不符。"}, "sentence_index": 0, "correct_answer": "轨道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汽车在轨道上行驶得很快。", "explanation": "这里应该用〈道路〉。轨道是供火车、地铁等轨道车辆行驶的铁路，汽车不能在轨道上行驶。"}, {"text": "运动员在轨道上跑了五圈。", "explanation": "这里应该用〈跑道〉。轨道是火车行驶的铁路，不能供人跑步；运动员跑步的场地是跑道。"}, {"text": "工人修了一列轨道。", "explanation": "这里应该用〈条〉。“列”用于火车，轨道的量词是“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92733, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轨道", "is_correct": true, "explanation": "轨道：火车离开了铁路，大家担心，符合“轨道”的意思。"}, {"text": "海面", "is_correct": false, "explanation": "语义：火车不会在海面上行驶，无法离开海面。"}, {"text": "河道", "is_correct": false, "explanation": "语义：火车不沿河道行驶，河道不是铁路。"}, {"text": "车厢", "is_correct": false, "explanation": "搭配：“一列火车”离开的是整体，不能说离开了它的一节车厢。"}], "explanations": {"轨道": "轨道：火车离开了铁路，大家担心，符合“轨道”的意思。", "海面": "语义：火车不会在海面上行驶，无法离开海面。", "河道": "语义：火车不沿河道行驶，河道不是铁路。", "车厢": "搭配：“一列火车”离开的是整体，不能说离开了它的一节车厢。"}, "sentence_index": 6, "correct_answer": "轨道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船只在轨道上行驶得很慢。", "explanation": "这里应该用〈航道〉。轨道是火车行驶的铁路，船只不在铁路上行驶，水上的通道应说航道。"}, {"text": "工人换了一台旧轨道。", "explanation": "这里应该用〈条〉。“台”用于机器，轨道的量词是“条”。"}, {"text": "我们沿着轨道爬到了山顶。", "explanation": "这里应该用〈山路〉。轨道是火车行驶的铁路，人爬山走的是山路，不能说沿着轨道爬山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92733, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们修了一块新轨道。", "corrected_sentence": "工人们修了一条新轨道。", "error_description": "错误：“轨道”的量词用错，“块”不能用来计量轨道。正确：应用量词“条”，即“一条新轨道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92733, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那列火车停在了轨道里。", "corrected_sentence": "那列火车停在了轨道上。", "error_description": "错误：方位词用错，“轨道”是平面的铁路，应该用“上”，不能用“里”。正确：那列火车停在了轨道上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
