INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "轨道是天体运行的路线。", "primary_collocate": null, "pronunciation": "guǐ dào", "ipa": "kweɪ̯˨˩ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "地球沿着轨道绕太阳转。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮的轨道不是正圆形。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星已经进入了轨道。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭把新卫星送上了轨道。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳系里的行星都有自己的轨道。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗星星的轨道很大。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家算出了飞船的轨道。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月球沿着轨道绕地球转。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空间站在轨道上飞了很多年。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上画着行星的轨道。", "target_word": "轨道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条轨道", "label": "量词"}], "register": "中性", "sense_fingerprint": "天体绕行的固定路线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9d6783f-ace1-4265-9d14-fc3a3d5379b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轨道", "is_correct": true, "explanation": "轨道：地球沿着天体运行的路线绕太阳转，与“轨道”的意思一致。"}, {"text": "公路", "is_correct": false, "explanation": "语义：地球不沿公路运动，公路是供车辆行驶的道路。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“沿着”需要表示路线的名词，车站不是路线，不能说“沿着车站”。"}, {"text": "河床", "is_correct": false, "explanation": "语义：河床是河底，与地球绕太阳运行的路线无关。"}], "explanations": {"轨道": "轨道：地球沿着天体运行的路线绕太阳转，与“轨道”的意思一致。", "公路": "语义：地球不沿公路运动，公路是供车辆行驶的道路。", "车站": "搭配：“沿着”需要表示路线的名词，车站不是路线，不能说“沿着车站”。", "河床": "语义：河床是河底，与地球绕太阳运行的路线无关。"}, "sentence_index": 0, "correct_answer": "轨道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动员在轨道上跑了五圈。", "explanation": "这里应该用〈跑道〉。轨道指火车等行驶的铁路或天体运行的路线，不能指运动员跑步的场地，应说跑道。"}, {"text": "图上画着一片行星的轨道。", "explanation": "这里应该用〈条〉。“片”用于片状的东西，轨道的量词是“条”。"}, {"text": "这条河的轨道很长。", "explanation": "这里应该用〈河道〉。轨道指火车等行驶的铁路或天体运行的路线，不能指河床，河床应说河道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轨道", "is_correct": true, "explanation": "轨道：飞船沿着预定路线运行，科学家算出的是它的运行路线，与“轨道”的意思一致。"}, {"text": "心情", "is_correct": false, "explanation": "语义：飞船没有心情，不能被算出。"}, {"text": "性格", "is_correct": false, "explanation": "语义：飞船没有性格，不能用“算出”来说明。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“算出”用于可以计算的数量或路线，颜色不能用“算出”来表达。"}], "explanations": {"轨道": "轨道：飞船沿着预定路线运行，科学家算出的是它的运行路线，与“轨道”的意思一致。", "心情": "语义：飞船没有心情，不能被算出。", "性格": "语义：飞船没有性格，不能用“算出”来说明。", "颜色": "搭配：“算出”用于可以计算的数量或路线，颜色不能用“算出”来表达。"}, "sentence_index": 6, "correct_answer": "轨道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船只沿着轨道驶进了港口。", "explanation": "这里应该用〈航道〉。轨道指火车等行驶的铁路或天体运行的路线，船只在水上行驶，应说航道。"}, {"text": "科学家造了一座轨道。", "explanation": "这里应该用〈条〉。“座”用于建筑物，轨道的量词是“条”。"}, {"text": "我们沿着轨道爬到了山顶。", "explanation": "这里应该用〈山路〉。轨道指天体运行的路线或火车行驶的铁路，人爬山走的是山路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗卫星有一颗轨道。", "corrected_sentence": "这颗卫星有一条轨道。", "error_description": "错误：“轨道”的量词用错，“颗”不能用来计量轨道。正确：应用量词“条”，即“一条轨道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书上画着一块弯弯的轨道。", "corrected_sentence": "书上画着一条弯弯的轨道。", "error_description": "错误：“轨道”的量词用错，“块”不能用来计量轨道。正确：应用量词“条”，即“一条弯弯的轨道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92735, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "反义：“白天”与“夜间”相对，指天亮到天黑的时段。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：厨房是地点，与“夜间”的时间对立无关。"}, {"text": "书本", "is_correct": false, "explanation": "无关：书本是物品，与“夜间”的时间对立无关。"}, {"text": "河流", "is_correct": false, "explanation": "无关：河流是自然事物，与“夜间”的时间对立无关。"}], "correct_answer": "白天", "explanations": {"白天": "反义：“白天”与“夜间”相对，指天亮到天黑的时段。", "厨房": "无关：厨房是地点，与“夜间”的时间对立无关。", "书本": "无关：书本是物品，与“夜间”的时间对立无关。", "河流": "无关：河流是自然事物，与“夜间”的时间对立无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92735, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "反义：“白天”与“夜间”相对，指天亮到天黑的时段。"}, {"text": "冰箱", "is_correct": false, "explanation": "无关：冰箱是家电，与“夜间”的时间对立无关。"}, {"text": "操场", "is_correct": false, "explanation": "无关：操场是地点，与“夜间”的时间对立无关。"}, {"text": "石头", "is_correct": false, "explanation": "无关：石头是物体，与“夜间”的时间对立无关。"}], "correct_answer": "白天", "explanations": {"白天": "反义：“白天”与“夜间”相对，指天亮到天黑的时段。", "冰箱": "无关：冰箱是家电，与“夜间”的时间对立无关。", "操场": "无关：操场是地点，与“夜间”的时间对立无关。", "石头": "无关：石头是物体，与“夜间”的时间对立无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92735, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "夜间是天黑了以后的那段时间。", "primary_collocate": null, "pronunciation": "yè jiān", "ipa": "je˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "夜间路上车很少，开车要小心。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店夜间也开门。", "target_word": "夜间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜间天气很冷，请多穿点衣服。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜间我常常听到外面有声音。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院夜间也有医生值班。", "target_word": "夜间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜间孩子睡了，我才开始工作。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的夜间，公园里很凉快。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜间不要一个人出去。", "target_word": "夜间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜间下了一场大雨，早上路面都湿了。", "target_word": "夜间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜间的城市看起来很漂亮。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "夜间模式", "label": "复合"}, {"form": "夜間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "天黑以后的时间，日常生活中的晚上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92735, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜间", "is_correct": true, "explanation": "夜间：天黑以后的时间，句中指夜里路上车少，开车要小心。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是路面，“路上车很少”的说法不成立。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”与“路上”不搭配，车不会出现在厨房里。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不表示时间，不能作“路上车很少”的时间状语。"}], "explanations": {"夜间": "夜间：天黑以后的时间，句中指夜里路上车少，开车要小心。", "教室": "语义：教室不是路面，“路上车很少”的说法不成立。", "厨房": "搭配：“厨房”与“路上”不搭配，车不会出现在厨房里。", "书包": "语义：书包不表示时间，不能作“路上车很少”的时间状语。"}, "sentence_index": 0, "correct_answer": "夜间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在山里度过了一个夜间，又冷又累。", "explanation": "这里应该用〈一夜〉。“夜间”是时段，不能用量词“个”计量，整段夜里的时间应说“一夜”。"}, {"text": "他从昨天到今天，一只夜间都没有睡。", "explanation": "这里应该用〈一夜〉。量词“只”用于动物或成对的器物，不能计量“夜间”，整夜应说“一夜”。"}, {"text": "这次旅行我们熬过了一台夜间。", "explanation": "这里应该用〈一夜〉。量词“台”用于机器等，不能计量“夜间”，熬过一整夜应说“一夜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92735, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜间", "is_correct": true, "explanation": "夜间：天黑以后的时段，与“夏天的”搭配，指夏夜公园凉快。"}, {"text": "冬季", "is_correct": false, "explanation": "语义：“冬季”与前面的“夏天”矛盾，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“夏天的”修饰时段，不能修饰“冰箱”这类物品。"}, {"text": "教材", "is_correct": false, "explanation": "语义：教材与公园、凉快无关，不能指时间。"}], "explanations": {"夜间": "夜间：天黑以后的时段，与“夏天的”搭配，指夏夜公园凉快。", "冬季": "语义：“冬季”与前面的“夏天”矛盾，句子不通。", "冰箱": "搭配：“夏天的”修饰时段，不能修饰“冰箱”这类物品。", "教材": "语义：教材与公园、凉快无关，不能指时间。"}, "sentence_index": 6, "correct_answer": "夜间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书放在夜间的书架上。", "explanation": "这里不宜用〈夜间〉表示地点。“夜间”是时间词，不能指放置书的场所，应说“书架上”。"}, {"text": "这家店夜间在正午开门营业。", "explanation": "这里应该用〈白天〉。“夜间”指天黑以后的时段，与“正午”矛盾，正午营业应说“白天”或“中午”。"}, {"text": "同学们夜间去上早自习。", "explanation": "这里应该用〈清晨〉。早自习是清晨的学习时段，与“夜间”不搭配，应说“清晨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92735, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区一个夜间很安静。", "corrected_sentence": "这个小区夜间很安静。", "error_description": "量词误用：“夜间”是时间词，作状语时不能用“一个”计量，应去掉“一个”，说“这个小区夜间很安静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92735, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我夜间的出去散步。", "corrected_sentence": "我夜间出去散步。", "error_description": "“夜间”作时间状语修饰动词时后面不加“的”，应说“夜间出去散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92736, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "反义：“白天”与“夜间”相对，指天亮到天黑的时段。"}, {"text": "饭碗", "is_correct": false, "explanation": "无关：饭碗是器物，与“夜间”的时间对立无关。"}, {"text": "课本", "is_correct": false, "explanation": "无关：课本是物品，与“夜间”的时间对立无关。"}, {"text": "山脉", "is_correct": false, "explanation": "无关：山脉是地理事物，与“夜间”的时间对立无关。"}], "correct_answer": "白天", "explanations": {"白天": "反义：“白天”与“夜间”相对，指天亮到天黑的时段。", "饭碗": "无关：饭碗是器物，与“夜间”的时间对立无关。", "课本": "无关：课本是物品，与“夜间”的时间对立无关。", "山脉": "无关：山脉是地理事物，与“夜间”的时间对立无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
