INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "夜晚的时间；从天黑到天亮之间。", "primary_collocate": null, "pronunciation": "yè jiān", "ipa": "je˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "夜间气温将明显下降。", "target_word": "夜间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜间施工应当遵守噪声规定。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "该路段夜间禁止货车通行。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜间航班比白天的便宜许多。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆夜间不对外开放。", "target_word": "夜间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜间行车须开启近光灯。", "target_word": "夜间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "受冷空气影响，夜间有小雨。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜间值班人员应做好记录。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院提供夜间急诊服务。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜间睡眠不足会影响健康。", "target_word": "夜间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "夜间模式", "label": "复合"}, {"form": "夜間", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从天黑到天亮之间的时段，常见于通知、规定、天气预报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜间", "is_correct": true, "explanation": "夜间：从天黑到天亮之间的时段，与“气温将明显下降”的天气语境相符。"}, {"text": "课文", "is_correct": false, "explanation": "语义：课文不是时段，没有气温变化，句子不通。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“气温”只与时间或地点搭配，篮球不能说气温下降。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋不表示时段，“气温将明显下降”无从说起。"}], "explanations": {"夜间": "夜间：从天黑到天亮之间的时段，与“气温将明显下降”的天气语境相符。", "课文": "语义：课文不是时段，没有气温变化，句子不通。", "篮球": "搭配：“气温”只与时间或地点搭配，篮球不能说气温下降。", "拖鞋": "语义：拖鞋不表示时段，“气温将明显下降”无从说起。"}, "sentence_index": 0, "correct_answer": "夜间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在车站等了一个夜间，终于等到了车。", "explanation": "这里应该用〈一夜〉。“夜间”是时段，不与量词“个”搭配，整夜的时间应说“一夜”。"}, {"text": "工人们连续赶工了一只夜间。", "explanation": "这里应该用〈一夜〉。量词“只”不能计量“夜间”，连续一整夜应说“一夜”。"}, {"text": "这位医生守了一台夜间。", "explanation": "这里应该用〈一夜〉。量词“台”用于机器等，不能计量“夜间”，守了一整夜应说“一夜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜间", "is_correct": true, "explanation": "夜间：指天黑到天亮的时段，与“受冷空气影响”的天气语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是室内场所，“有小雨”的主语应是天气发生的时段，厨房不会下雨。"}, {"text": "水杯", "is_correct": false, "explanation": "搭配：“有小雨”的主语应是时段或地点，不能说水杯有小雨。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与天气无关，句中“有小雨”无法成立。"}], "explanations": {"夜间": "夜间：指天黑到天亮的时段，与“受冷空气影响”的天气语境相符。", "厨房": "语义：厨房是室内场所，“有小雨”的主语应是天气发生的时段，厨房不会下雨。", "水杯": "搭配：“有小雨”的主语应是时段或地点，不能说水杯有小雨。", "钢琴": "语义：钢琴与天气无关，句中“有小雨”无法成立。"}, "sentence_index": 6, "correct_answer": "夜间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们夜间在操场上做早操。", "explanation": "这里应该用〈清晨〉。早操是清晨的活动，与“夜间”的时段矛盾，应说“清晨”。"}, {"text": "这家店夜间吃完午饭才开门。", "explanation": "这里应该用〈中午〉。“夜间”指天黑以后的时段，与午饭的时间矛盾，应说“中午”。"}, {"text": "夜间的阳光照进了教室。", "explanation": "这里应该用〈白天〉。阳光照进教室是白天的情形，与“夜间”的时段矛盾，应说“白天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜间地施工时，请居民关好窗户。", "corrected_sentence": "夜间施工时，请居民关好窗户。", "error_description": "“夜间”作状语修饰动词时不加“地”，应说“夜间施工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天夜间里有雨，出门请带伞。", "corrected_sentence": "这几天夜间有雨，出门请带伞。", "error_description": "“夜间”已表示时间，后面不能再加“里”。应说“夜间有雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92737, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "控制", "is_correct": true, "explanation": "控制：与“失控”相反，指能够掌握、约束。"}, {"text": "启动", "is_correct": false, "explanation": "启动：指开始运转，与“失控”没有反义关系。"}, {"text": "前进", "is_correct": false, "explanation": "前进：指向前移动，与“失控”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指悠闲地走路，与“失控”没有反义关系。"}], "correct_answer": "控制", "explanations": {"控制": "控制：与“失控”相反，指能够掌握、约束。", "启动": "启动：指开始运转，与“失控”没有反义关系。", "前进": "前进：指向前移动，与“失控”没有反义关系。", "散步": "散步：指悠闲地走路，与“失控”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
