INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92737, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人或东西不听指挥，管不住。", "primary_collocate": null, "pronunciation": "shī kòng", "ipa": "ʂɨ˥ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "汽车突然失控，撞到了树上。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很生气，一下子失控了。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩得太高兴，场面有点失控。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在空中失控了几秒钟。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到比分，他的情绪完全失控了。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开到一半，场面失控了。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车曾经失控过一次。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让自己的脾气失控。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这匹马受惊后失控，跑进了树林。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝多了，行为开始失控。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失控了", "label": "体标"}, {"form": "失控过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人或东西不听指挥，管不住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：汽车不会唱歌，与“撞到了树上”的情况不符。"}, {"text": "失控", "is_correct": true, "explanation": "正确：“失控”指车辆不受控制，与“撞到了树上”的结果相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：汽车不会睡觉，句子说的是车的运行状况。"}, {"text": "给予", "is_correct": false, "explanation": "配价：“给予”需要说明给谁，句中没有接受者，不能这样单独使用。"}], "explanations": {"唱歌": "语义：汽车不会唱歌，与“撞到了树上”的情况不符。", "失控": "正确：“失控”指车辆不受控制，与“撞到了树上”的结果相符。", "睡觉": "语义：汽车不会睡觉，句子说的是车的运行状况。", "给予": "配价：“给予”需要说明给谁，句中没有接受者，不能这样单独使用。"}, "sentence_index": 0, "correct_answer": "失控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个钟表已经失控了。", "explanation": "这里应该用〈失准〉。失控指管不住，钟表走得不准要说失准。"}, {"text": "我的手机按键失控了，按了没反应。", "explanation": "这里应该用〈失灵〉。按了没反应是功能坏了，失控指不受控制、乱动，要说失灵。"}, {"text": "这个门锁已经失控了。", "explanation": "这里应该用〈失灵〉。失控指人或事物不受控制，门锁不能正常使用要说失灵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失恋", "is_correct": false, "explanation": "语义：“失恋”只用于人，车不会失恋。"}, {"text": "失控", "is_correct": true, "explanation": "正确：“失控”指车辆不受控制，与“曾经……过一次”相符。"}, {"text": "陪伴", "is_correct": false, "explanation": "配价：“陪伴”需要说明陪伴谁，句中缺少对象。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”指人睡不着，车不会失眠。"}], "explanations": {"失恋": "语义：“失恋”只用于人，车不会失恋。", "失控": "正确：“失控”指车辆不受控制，与“曾经……过一次”相符。", "陪伴": "配价：“陪伴”需要说明陪伴谁，句中缺少对象。", "失眠": "语义：“失眠”指人睡不着，车不会失眠。"}, "sentence_index": 6, "correct_answer": "失控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张优惠券已经失控了。", "explanation": "这里应该用〈失效〉。失控指东西或人不受控制，优惠券过期要说失效。"}, {"text": "全家人在战乱中失控了。", "explanation": "这里应该用〈失散〉。失控指管不住，家人在战乱中分开要说失散。"}, {"text": "这段录音失控了。", "explanation": "这里应该用〈失真〉。失控不用于声音变形，录音走样要说失真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑车的时候突然失控过，摔了一跤。", "corrected_sentence": "他骑车的时候突然失控了，摔了一跤。", "error_description": "错误形式：“突然失控过”；正确形式：“突然失控了”。“失控过”表示曾经有过的经历，这里说的是刚刚发生的事，应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆摩托车突然失控了它，滑出了路边。", "corrected_sentence": "那辆摩托车突然失控，滑出了路边。", "error_description": "错误形式：“失控了它”；正确形式：“失控”。“失控”是不及物动词，后面不能带宾语，应去掉“了它”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
