INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92738, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "失去控制；无法掌握或约束。", "primary_collocate": null, "pronunciation": "shī kòng", "ipa": "ʂɨ˥ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "价格一旦失控，市场就会乱。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的病情没有失控。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物价上涨失控了，大家都很担心。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火势很快失控，消防员赶来了。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一带的治安突然失控了。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的成本已经失控了。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局势失控后，政府发了通知。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故是因为现场秩序失控造成的。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的交通几次失控。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要防止风险失控。", "target_word": "失控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失控了", "label": "体标"}, {"form": "失控过", "label": "体标"}], "register": "书面", "sense_fingerprint": "失去控制，局势或事态无法掌握约束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbdcfa36-11f1-4ac4-9d43-8a4a834d23c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失明", "is_correct": false, "explanation": "语义：“失明”指眼睛看不见，价格不能失明。"}, {"text": "失控", "is_correct": true, "explanation": "正确：“失控”指价格不受控制，与“市场就会乱”的后果相符。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：“迷路”指人或动物找不到方向，价格不能迷路。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指人失去工作，价格不能失业。"}], "explanations": {"失明": "语义：“失明”指眼睛看不见，价格不能失明。", "失控": "正确：“失控”指价格不受控制，与“市场就会乱”的后果相符。", "迷路": "语义：“迷路”指人或动物找不到方向，价格不能迷路。", "失业": "语义：“失业”指人失去工作，价格不能失业。"}, "sentence_index": 0, "correct_answer": "失控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这门手艺已经失控了。", "explanation": "这里应该用〈失传〉。失控指管不住，手艺后继无人要说失传。"}, {"text": "这幅画已经失控了。", "explanation": "这里应该用〈失色〉。失控指管不住，颜色褪去要说失色。"}, {"text": "这份报告已经失控了。", "explanation": "这里应该用〈失实〉。失控指管不住，报告内容不真实要说失实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出芽，局势不能发芽。"}, {"text": "给予", "is_correct": false, "explanation": "配价：“给予”需要说明给予的对象，句中没有，不能这样用。"}, {"text": "失控", "is_correct": true, "explanation": "正确：“失控”指局势无法掌握，与“政府发了通知”的背景相符。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”指学校或单位停止工作学习，局势不能放假。"}], "explanations": {"发芽": "语义：“发芽”指植物长出芽，局势不能发芽。", "给予": "配价：“给予”需要说明给予的对象，句中没有，不能这样用。", "失控": "正确：“失控”指局势无法掌握，与“政府发了通知”的背景相符。", "放假": "语义：“放假”指学校或单位停止工作学习，局势不能放假。"}, "sentence_index": 6, "correct_answer": "失控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片颜色失控了。", "explanation": "这里应该用〈失真〉。失控指管不住，照片颜色走样要说失真。"}, {"text": "两兄弟小时候就失控了。", "explanation": "这里应该用〈失散〉。失控指管不住，亲人分开要说失散。"}, {"text": "这张卡已经失控了。", "explanation": "这里应该用〈失效〉。失控指管不住，卡片过期或不能使用要说失效。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那里的局势已经失控着。", "corrected_sentence": "那里的局势已经失控了。", "error_description": "错误形式：“已经失控着”；正确形式：“已经失控了”。“已经”表示变化已经发生，应该用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事态被失控后，部队立刻出动了。", "corrected_sentence": "事态失控后，部队立刻出动了。", "error_description": "错误形式：“事态被失控后”；正确形式：“事态失控后”。“失控”是不及物动词，不能用“被”构成被动句，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28241b85-2d13-4d23-94a9-f9538af0d431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
