INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92741, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学说是一个有学问的人想出来，并讲给大家听的一套道理。", "primary_collocate": null, "pronunciation": "xué shuō", "ipa": "ɕɥɛ˧˥ ʂwɔ˥˥", "syllable_count": 2, "sentences": [{"text": "这位教授提出了一种新的学说。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "达尔文的学说改变了人们对生物的看法。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人不相信这个学说。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一辈子都在研究孔子的学说。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套学说讲的是人应该怎样生活。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了几种有名的学说。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学说在当时很有影响。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学说一开始没有人支持。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里讲了不同学者的学说。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学说太难，我听不懂。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种学说", "label": "量词"}, {"form": "一套学说", "label": "量词"}, {"form": "进化学说", "label": "复合"}], "register": "书面", "sense_fingerprint": "有学问的人想出来并讲给大家听的一套道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学说", "is_correct": true, "explanation": "学说：有学问的人提出并讲给大家听的一套道理。"}, {"text": "学硕", "is_correct": false, "explanation": "shuò（第四声）与 shuō（第一声）声调不同，意思是学术型硕士（学硕）。"}, {"text": "学术", "is_correct": false, "explanation": "shù（第四声）与 shuō（第一声）韵母不同（u 与 uo），声调也不同，意思是学问、学术。"}, {"text": "学书", "is_correct": false, "explanation": "shū（第一声）与 shuō（第一声）韵母不同（u 与 uo），意思是学习书法或写字。"}], "explanations": {"学说": "学说：有学问的人提出并讲给大家听的一套道理。", "学硕": "shuò（第四声）与 shuō（第一声）声调不同，意思是学术型硕士（学硕）。", "学术": "shù（第四声）与 shuō（第一声）韵母不同（u 与 uo），声调也不同，意思是学问、学术。", "学书": "shū（第一声）与 shuō（第一声）韵母不同（u 与 uo），意思是学习书法或写字。"}, "sentence_index": null, "correct_answer": "学说"}, "level_3": {"options": [{"text": "学说", "is_correct": true, "explanation": "学说：有学问的人提出的一套道理，可以被“提出”，与“一种新的”搭配。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“提出”用于观点、理论、问题，不能说“提出一种新的房子”。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是具体的东西，不是能被提出的观点，句意讲不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是作品，这里的“提出”指提出见解，与歌曲不相配。"}], "explanations": {"学说": "学说：有学问的人提出的一套道理，可以被“提出”，与“一种新的”搭配。", "房子": "搭配：“提出”用于观点、理论、问题，不能说“提出一种新的房子”。", "食物": "语义：食物是具体的东西，不是能被提出的观点，句意讲不通。", "歌曲": "语义：歌曲是作品，这里的“提出”指提出见解，与歌曲不相配。"}, "sentence_index": 0, "correct_answer": "学说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很有学说，很多人都向他请教。", "explanation": "这里应该用〈学问〉。“有学问”指知识渊博；“学说”指一套理论，不能用来说人的学识。"}, {"text": "数学是一门重要的学说。", "explanation": "这里应该用〈学科〉。数学是一门学科；“学说”指学者提出的一套理论，不能指一门学科。"}, {"text": "他的学说在操场上踢足球。", "explanation": "这里应该用〈学生〉或〈球员〉。“学说”是一套理论，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92741, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "学说", "is_correct": true, "explanation": "学说：有学问的人提出并讲给大家听的一套道理。"}, {"text": "学士", "is_correct": false, "explanation": "shì（第四声）与 shuō（第一声）韵母不同（i 与 uo），意思是大学本科毕业的学位。"}, {"text": "学时", "is_correct": false, "explanation": "shí（第二声）与 shuō（第一声）韵母不同（i 与 uo），意思是学习的时间或课时。"}, {"text": "学书", "is_correct": false, "explanation": "shū（第一声）与 shuō（第一声）韵母不同（u 与 uo），意思是学习书法或写字。"}], "explanations": {"学说": "学说：有学问的人提出并讲给大家听的一套道理。", "学士": "shì（第四声）与 shuō（第一声）韵母不同（i 与 uo），意思是大学本科毕业的学位。", "学时": "shí（第二声）与 shuō（第一声）韵母不同（i 与 uo），意思是学习的时间或课时。", "学书": "shū（第一声）与 shuō（第一声）韵母不同（u 与 uo），意思是学习书法或写字。"}, "sentence_index": null, "correct_answer": "学说"}, "level_3": {"options": [{"text": "学说", "is_correct": true, "explanation": "学说：学者提出的一套理论，能够在当时产生影响。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不会在当时产生影响，句意讲不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不会在当时产生学术上的影响。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶是植物的一部分，不会在当时产生影响，句意讲不通。"}], "explanations": {"学说": "学说：学者提出的一套理论，能够在当时产生影响。", "石头": "语义：石头是无生命的物体，不会在当时产生影响，句意讲不通。", "天气": "语义：天气是自然现象，不会在当时产生学术上的影响。", "树叶": "语义：树叶是植物的一部分，不会在当时产生影响，句意讲不通。"}, "sentence_index": 6, "correct_answer": "学说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位很有名的学说，大家都很尊敬他。", "explanation": "这里应该用〈学者〉。“学说”是一套理论，不能指人。"}, {"text": "物理是一门重要的学说。", "explanation": "这里应该用〈学科〉。物理是一门学科；“学说”指学者提出的一套理论，不能指一门学科。"}, {"text": "老师让我们在学说门口集合。", "explanation": "这里应该用〈学校〉。“学说”是一套理论，不能指地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "后来人们接受了这种新地学说。", "corrected_sentence": "后来人们接受了这种新的学说。", "error_description": "“新”修饰名词“学说”，应该用“的”，写成“地”是错的。“地”用于修饰动词、形容词，不修饰名词；应写作“新的学说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经学过这只学说了。", "corrected_sentence": "我已经学过这套学说了。", "error_description": "“学说”应使用量词“套”，不能用“只”。“只”多用于动物，不能用来计量学说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
