INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学术上自成系统的理论或主张。", "primary_collocate": null, "pronunciation": "xué shuō", "ipa": "ɕɥɛ˧˥ ʂwɔ˥˥", "syllable_count": 2, "sentences": [{"text": "这位科学家的学说自成一家。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学专门研究古代哲学学说。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种学说的看法完全不同。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学说后来成了一门新学科的基础。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论文比较了几种经济学说。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学说从来没有人证明过。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马克思的学说影响了很多国家。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自己的学说解释了这个现象。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学说有很强的科学依据。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们正在讨论这个学说对不对。", "target_word": "学说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种学说", "label": "量词"}, {"form": "一套学说", "label": "量词"}, {"form": "经济学说", "label": "复合"}], "register": "书面", "sense_fingerprint": "学术上自成系统的理论或主张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b3468b2-e9de-4767-8dc9-fa5cc27facb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学说", "is_correct": true, "explanation": "学说：学术上自成系统的理论或主张。"}, {"text": "学硕", "is_correct": false, "explanation": "shuò（第四声）与 shuō（第一声）声调不同，意思是学术型硕士（学硕）。"}, {"text": "学术", "is_correct": false, "explanation": "shù（第四声）与 shuō（第一声）韵母不同（u 与 uo），声调也不同，意思是学问、学术。"}, {"text": "学书", "is_correct": false, "explanation": "shū（第一声）与 shuō（第一声）韵母不同（u 与 uo），意思是学习书法或写字。"}], "explanations": {"学说": "学说：学术上自成系统的理论或主张。", "学硕": "shuò（第四声）与 shuō（第一声）声调不同，意思是学术型硕士（学硕）。", "学术": "shù（第四声）与 shuō（第一声）韵母不同（u 与 uo），声调也不同，意思是学问、学术。", "学书": "shū（第一声）与 shuō（第一声）韵母不同（u 与 uo），意思是学习书法或写字。"}, "sentence_index": null, "correct_answer": "学说"}, "level_3": {"options": [{"text": "学说", "is_correct": true, "explanation": "学说：学术上自成系统的理论，与“自成一家”相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能“自成一家”，这个说法不用于具体的物品。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不能“自成一家”，句意讲不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是日用品，不能“自成一家”，句意讲不通。"}], "explanations": {"学说": "学说：学术上自成系统的理论，与“自成一家”相合。", "石头": "语义：石头不能“自成一家”，这个说法不用于具体的物品。", "雨伞": "语义：雨伞是日用品，不能“自成一家”，句意讲不通。", "书包": "语义：书包是日用品，不能“自成一家”，句意讲不通。"}, "sentence_index": 0, "correct_answer": "学说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同桌是个学说，每天都很认真。", "explanation": "这里应该用〈学生〉。“学说”是一套理论，不能指人。"}, {"text": "我们班的学说是小王，他很会讲笑话。", "explanation": "这里应该用〈班长〉。“学说”是一套理论，不能指班里的负责人。"}, {"text": "他的学说考了一百分，老师很惊讶。", "explanation": "这里应该用〈科目〉。“学说”是一套理论，不能作为考试的科目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
