INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提出了一部新学说，影响很大。", "corrected_sentence": "他提出了一套新学说，影响很大。", "error_description": "“学说”的量词应用“套”，不用“部”。“部”多用于书籍、影视作品，不能用来计量学说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多人读过这套新地学说。", "corrected_sentence": "很多人读过这套新的学说。", "error_description": "“新”修饰名词“学说”，应该用“的”，写成“地”是错的。“地”不修饰名词，应写作“新的学说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d0f262c-458f-4cf8-8d35-f247ff9e23e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92743, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92743, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学费是上学时要交给学校的钱。", "primary_collocate": null, "pronunciation": "xué fèi", "ipa": "ɕɥɛ˧˥ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "明天要交学费。", "target_word": "学费", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个学期的学费已经交了。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸给我准备了学费。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐自己打工挣学费。", "target_word": "学费", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这所学校的学费不太贵。", "target_word": "学费", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学费要在九月以前交。", "target_word": "学费", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把学费放在书包里。", "target_word": "学费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈担心我们的学费不够。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年学费比去年贵了一点。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了带学费，老师让我明天交。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "學費", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上学时要交给学校的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92743, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学费", "is_correct": true, "explanation": "正确：“交学费”是常用搭配，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用来交付，“交”不能带“空气”作宾语。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“交”不跟“感冒”搭配，不能说交感冒。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不能交出去，句子说不通。"}], "explanations": {"学费": "正确：“交学费”是常用搭配，符合句意。", "空气": "语义：空气不能用来交付，“交”不能带“空气”作宾语。", "感冒": "搭配：“交”不跟“感冒”搭配，不能说交感冒。", "阳光": "语义：阳光不能交出去，句子说不通。"}, "sentence_index": 0, "correct_answer": "学费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间宿舍每个月要交一百元学费。", "explanation": "这里应该用〈住宿费〉。学费是上学时交给学校的钱，宿舍的费用要说住宿费，不能说学费。"}, {"text": "他的学费一个月发一次。", "explanation": "这里应该用〈工资〉。工资是雇主发给员工的钱，学费是学生交给学校的钱，发放的方向正好相反。"}, {"text": "我们租房时交了一个月的学费。", "explanation": "这里应该用〈押金〉。押金是租房时交的担保金，学费是上学时交给学校的钱，不能用来交房租押金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学费", "is_correct": true, "explanation": "正确：“放在书包里”指装钱款，学费可以这样放，符合句意。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪不能装进书包，句子说不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“放在……里”要求可以装进去的物品，不说放天空。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊是抽象概念，不能放进书包。"}], "explanations": {"学费": "正确：“放在书包里”指装钱款，学费可以这样放，符合句意。", "海浪": "语义：海浪不能装进书包，句子说不通。", "天空": "搭配：“放在……里”要求可以装进去的物品，不说放天空。", "友谊": "语义：友谊是抽象概念，不能放进书包。"}, "sentence_index": 6, "correct_answer": "学费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她申请了学费，想减轻家里的负担。", "explanation": "这里应该用〈奖学金〉。学费是交给学校的钱，不能申请；奖学金才是学校发给学生的钱。"}, {"text": "学校每学期给贫困生发一笔学费。", "explanation": "这里应该用〈助学金〉。助学金是学校发给贫困生的钱，学费是学生交给学校的钱。"}, {"text": "他每个月领到学费，用来买菜。", "explanation": "这里应该用〈生活费〉。生活费是每月领取、用于日常开销的钱，学费是交给学校的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他交了一张学费。", "corrected_sentence": "他交了一笔学费。", "error_description": "量词错误：“张”错，应为“笔”。学费是一笔钱，“张”用于纸张、票据等扁平物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忘了带学费们。", "corrected_sentence": "他忘了带学费。", "error_description": "用词错误：“们”只用于指人的名词，“学费”后不能加“们”，应为“他忘了带学费”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
