INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学生入学读书所缴纳的费用。", "primary_collocate": null, "pronunciation": "xué fèi", "ipa": "ɕɥɛ˧˥ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "大学一年的学费是八千元。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校通知学生按时缴纳学费。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "留学的学费比国内高很多。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家培训班的学费怎么算？", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学费包括书本费和住宿费吗？", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她申请了奖学金来减少学费。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学费可以分两次付。", "target_word": "学费", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多家庭为孩子的学费发愁。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生可以在网上查看学费标准。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边工作一边攒下了学费。", "target_word": "学费", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "學費", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学生入学读书所缴纳的费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学费", "is_correct": true, "explanation": "正确：“学费”指上学时交的费用，可以用“八千元”计价，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不能用“八千元”计价，句子说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“是八千元”要求金额类词语，年龄不能这样计算。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以用金额计价的东西。"}], "explanations": {"学费": "正确：“学费”指上学时交的费用，可以用“八千元”计价，符合句意。", "体重": "语义：体重不能用“八千元”计价，句子说不通。", "年龄": "搭配：“是八千元”要求金额类词语，年龄不能这样计算。", "天气": "语义：天气不是可以用金额计价的东西。"}, "sentence_index": 0, "correct_answer": "学费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她申请了学费，好减轻父母的压力。", "explanation": "这里应该用〈奖学金〉。奖学金是学校发给学生的钱，可以申请；学费是学生交给学校的钱，不说“申请了学费”。"}, {"text": "学校每个学期给贫困生发学费。", "explanation": "这里应该用〈助学金〉。助学金是学校发给贫困生的钱，学校不发学费。"}, {"text": "他每个月领学费，用来买菜。", "explanation": "这里应该用〈生活费〉。生活费是每月领取、用于日常开销的钱，学费不能领，也不用来买菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学费", "is_correct": true, "explanation": "正确：“学费”可以分次支付，符合句意。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：友谊不能分两次付，句子说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用来付钱。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“付”后接款项，不说付微笑。"}], "explanations": {"学费": "正确：“学费”可以分次支付，符合句意。", "友谊": "语义：友谊不能分两次付，句子说不通。", "空气": "语义：空气不能用来付钱。", "微笑": "搭配：“付”后接款项，不说付微笑。"}, "sentence_index": 6, "correct_answer": "学费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府每个月给老人发一笔学费。", "explanation": "这里应该用〈补贴〉。补贴是政府或单位发给个人的钱，学费是学生交给学校的钱，政府不给老人发学费。"}, {"text": "他去医院交了一笔学费。", "explanation": "这里应该用〈医药费〉。医药费是看病时交的钱，学费是上学时交给学校的钱，不能用来交医院的费用。"}, {"text": "他把车停在路边，交了一笔学费。", "explanation": "这里应该用〈停车费〉。停车费是停车时交的钱，学费是上学时交给学校的钱，不能用来付停车的费用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸帮我交着学费。", "corrected_sentence": "爸爸帮我交了学费。", "error_description": "体标错误：“交着”错，应为“交了”。“交学费”是一次性完成的动作，表示已经完成要用“了”；“着”表示动作持续进行，与交费这种一次性行为不搭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他攒下了一张学费。", "corrected_sentence": "他攒下了一笔学费。", "error_description": "量词错误：“张”错，应为“笔”。学费是一笔钱，“张”用于纸张、票据等扁平物件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "安慰是别人难过的时候，说好听的话让他好受一点。", "primary_collocate": null, "pronunciation": "ān wèi", "ipa": "an˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "她哭了，我说了几句好听的话安慰她。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人难过的时候，你要多安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他输了比赛，同学们都过来安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会说话，不知道怎么安慰难过的人。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友安慰了我半天，我心里才好受一点。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是用温和的话安慰我。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失败了，你不要笑他，应该安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻声安慰着正在哭的女儿。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说了几句话安慰那个难过的孩子。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想安慰你，可是不知道说什么好。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安慰了", "label": "体标"}, {"form": "安慰着", "label": "体标"}, {"form": "安慰过", "label": "体标"}, {"form": "安慰安慰", "label": "重叠"}], "register": "中性", "sense_fingerprint": "别人难过时说好话让他好受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5f01a3f-0c54-4133-9b25-173d415a41c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安慰", "is_correct": true, "explanation": "“安慰”表示用好话让对方好受，与“说了几句好听的话”的语境一致，正确。"}, {"text": "责骂", "is_correct": false, "explanation": "语义：“责骂”带有斥责的意思，与“好听的话”相矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽，与“好听的话”的语气不相符。"}, {"text": "训斥", "is_correct": false, "explanation": "搭配：“训斥”指严厉说教，一般不说用“好听的话”训斥人。"}], "explanations": {"安慰": "“安慰”表示用好话让对方好受，与“说了几句好听的话”的语境一致，正确。", "责骂": "语义：“责骂”带有斥责的意思，与“好听的话”相矛盾。", "嘲笑": "语义：“嘲笑”带有讥讽，与“好听的话”的语气不相符。", "训斥": "搭配：“训斥”指严厉说教，一般不说用“好听的话”训斥人。"}, "sentence_index": 0, "correct_answer": "安慰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他得了奖，朋友们都过来安慰他。", "explanation": "这里应该用〈祝贺〉。“安慰”针对难过的人，得奖的人应当被祝贺，不该被安慰。"}, {"text": "我把那只旧杯子安慰了一遍。", "explanation": "对象误用：“安慰”的对象应当是有感情的人，不能用于杯子。"}, {"text": "他用拳头安慰了朋友。", "explanation": "方式误用：“安慰”是用言语或温和的行动让人平静，用拳头打人不是安慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安慰", "is_correct": true, "explanation": "“安慰”表示让对方心里好受，前句说“不要笑他”，后句“应该安慰他”与之呼应，符合语境。"}, {"text": "咒骂", "is_correct": false, "explanation": "语义：“咒骂”是恶语相向，与“不要笑他”后的劝导语气不协调。"}, {"text": "威胁", "is_correct": false, "explanation": "语义：“威胁”是用恐吓对待对方，与“应该”后的态度说不通。"}, {"text": "讥讽", "is_correct": false, "explanation": "语义：“讥讽”是拿话挖苦对方，与“不要笑他”的劝诫正相反，说“应该讥讽他”说不通。"}], "explanations": {"安慰": "“安慰”表示让对方心里好受，前句说“不要笑他”，后句“应该安慰他”与之呼应，符合语境。", "咒骂": "语义：“咒骂”是恶语相向，与“不要笑他”后的劝导语气不协调。", "威胁": "语义：“威胁”是用恐吓对待对方，与“应该”后的态度说不通。", "讥讽": "语义：“讥讽”是拿话挖苦对方，与“不要笑他”的劝诫正相反，说“应该讥讽他”说不通。"}, "sentence_index": 6, "correct_answer": "安慰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长安慰了那个主动帮忙的同学。", "explanation": "这里应该用〈感谢〉。“安慰”是为难过的人宽慰，主动帮忙的同学应当感谢。"}, {"text": "他安慰地骂了我一顿。", "explanation": "语义矛盾：“安慰地”表示温和地宽慰，与“骂了我一顿”的责备正相反。"}, {"text": "我安慰了那块石头，它一直不说话。", "explanation": "对象误用：“安慰”的对象应当是有感情的人，不能用于石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被老板骂了，心里很难受，我很安慰他一下。", "corrected_sentence": "他被老板骂了，心里很难受，我去安慰他一下。", "error_description": "错误形式：“我很安慰他一下”；“很安慰”只能作形容词（如“听了很安慰”），后面不能再带宾语“他”。正确形式：“我去安慰他一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚丢了工作，我们应该安慰安慰一下他。", "corrected_sentence": "他刚丢了工作，我们应该安慰安慰他。", "error_description": "错误形式：“安慰安慰一下”；正确形式：“安慰安慰”。动词重叠“安慰安慰”本身已表示短暂、轻松的动作，后面不能再加“一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e06f40c-7698-4b54-b6e3-7f4afe1be718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
