INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92751, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92751, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "几乎不是差一点就没有，就是很少很少。", "primary_collocate": null, "pronunciation": "jī hū bù", "ipa": "tɕi˥ xu˥ pu˥˩", "syllable_count": 3, "sentences": [{"text": "他工作太忙，几乎不在家吃饭。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离海很远，一年几乎不去海边。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷身体很好，几乎不吃药。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹不爱看电视，几乎不开电视。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里冬天很暖和，几乎不下雪。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬家以后，几乎不跟我联系了。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近太累，晚上几乎不出门。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢甜的，所以几乎不吃蛋糕。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很偏，白天几乎不见车。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在山里，几乎不用手机。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "几乎不：表示做某事的次数或数量极少，差不多没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94ef46ac-c75d-4aa5-b593-6bca6ddab68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几乎不", "is_correct": true, "explanation": "正确：“几乎不”表示极少在家吃饭，与“工作太忙”的原因相合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”表示一贯如此，须与“不”或“没”连用，“从来在家吃饭”不成立。"}, {"text": "天天", "is_correct": false, "explanation": "语义：“天天在家吃饭”说每天都在家，与“工作太忙”的前提相矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，不能表示习惯，与句中的习惯语境不合。"}], "explanations": {"几乎不": "正确：“几乎不”表示极少在家吃饭，与“工作太忙”的原因相合。", "从来": "搭配：“从来”表示一贯如此，须与“不”或“没”连用，“从来在家吃饭”不成立。", "天天": "语义：“天天在家吃饭”说每天都在家，与“工作太忙”的前提相矛盾。", "已经": "体貌：“已经”表示动作已经完成，不能表示习惯，与句中的习惯语境不合。"}, "sentence_index": 0, "correct_answer": "几乎不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天几乎不吃饭，所以现在很饿。", "explanation": "这里应该用〈几乎没〉。说的是昨天已经发生的一次性情况，“几乎不”只用于习惯或可能性，不用于已经发生的事。"}, {"text": "他明天一定几乎不来。", "explanation": "这里误把〈几乎不〉（很少）当成了〈完全不〉（肯定不）用。前面的“一定”表示确定，与“很少”的意思相矛盾；要表示肯定不来，应说“一定不来”。"}, {"text": "这件事百分之百几乎不会发生。", "explanation": "这里误把〈几乎不〉（很少）当成了〈完全不〉（绝对不）用。“百分之百”表示完全确定，与“很少”矛盾；应说“百分之百不会发生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几乎不", "is_correct": true, "explanation": "正确：“几乎不”表示极少出门，与“太累”的原因相合。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”说长期一直如此，与句中的“最近”相矛盾。"}, {"text": "压根儿", "is_correct": false, "explanation": "搭配：“压根儿”须与“不”或“没”连用，“压根儿出门”不成立。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作此刻进行，不表示习惯，与“晚上”的习惯性语境不合。"}], "explanations": {"几乎不": "正确：“几乎不”表示极少出门，与“太累”的原因相合。", "一向": "语义：“一向”说长期一直如此，与句中的“最近”相矛盾。", "压根儿": "搭配：“压根儿”须与“不”或“没”连用，“压根儿出门”不成立。", "正在": "体貌：“正在”表示动作此刻进行，不表示习惯，与“晚上”的习惯性语境不合。"}, "sentence_index": 6, "correct_answer": "几乎不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是几乎不回家，天天都在家里吃饭。", "explanation": "“几乎不回家”表示很少回家，但后面说“天天都在家里吃饭”，前后矛盾。"}, {"text": "他特别爱运动，几乎不去健身房，每天都去。", "explanation": "“几乎不”表示很少去，但“特别爱运动”“每天都去”说明他常去，前后矛盾。"}, {"text": "这些学生都很用功，几乎不交作业。", "explanation": "“几乎不交作业”表示很少交作业，与“都很用功”前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸周末几乎不没看电视。", "corrected_sentence": "我爸爸周末几乎不看电视。", "error_description": "重复否定：“几乎不”本身已含否定词“不”，后面不能再加“没”，应说“几乎不看电视”，不能说“几乎不没看电视”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年纪大，夜里几乎不的下楼。", "corrected_sentence": "他年纪大，夜里几乎不下楼。", "error_description": "结构助词误用：“的”不能插在副词“几乎不”和动词“下”之间，应说“几乎不下楼”，不能说“几乎不的下楼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
