INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92752, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92752, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示极少发生或程度极低，接近于不。", "primary_collocate": null, "pronunciation": "jī hū bù", "ipa": "tɕi˥ xu˥ pu˥˩", "syllable_count": 3, "sentences": [{"text": "这个汤几乎不咸，你再加点盐吧。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚学中文，几乎不会写汉字。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太吵了，我几乎不能睡觉。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里太黑，我几乎不敢往前走。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服很旧，几乎不能穿了。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太紧张，几乎不敢说话。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药几乎不苦，孩子也能喝。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新鞋很软，我走路几乎不觉得累。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得太乱，我几乎不认识。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法几乎不可能成功。", "target_word": "几乎不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "几乎不：表示程度或可能性极低，接近于完全不", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94ef46ac-c75d-4aa5-b593-6bca6ddab68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几乎不", "is_correct": true, "explanation": "正确：“几乎不”表示咸味极淡，与“你再加点盐”的语境相合。"}, {"text": "太", "is_correct": false, "explanation": "语义：“太咸”说明汤已经很咸，与“你再加点盐”的建议相矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”须与“不”或“没”连用，“这个汤从来咸”不成立。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行，形容词“咸”不用进行体，“正在咸”不成立。"}], "explanations": {"几乎不": "正确：“几乎不”表示咸味极淡，与“你再加点盐”的语境相合。", "太": "语义：“太咸”说明汤已经很咸，与“你再加点盐”的建议相矛盾。", "从来": "搭配：“从来”须与“不”或“没”连用，“这个汤从来咸”不成立。", "正在": "体貌：“正在”表示动作进行，形容词“咸”不用进行体，“正在咸”不成立。"}, "sentence_index": 0, "correct_answer": "几乎不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题很简单，我几乎不能回答。", "explanation": "“几乎不能回答”表示几乎答不出来，与“问题很简单”相矛盾。"}, {"text": "我的眼睛很好，几乎不能看见远处的山。", "explanation": "“几乎不能看见”表示几乎看不到，与“眼睛很好”相矛盾。"}, {"text": "这道题几乎不能做，我一下就做完了。", "explanation": "这里误把〈几乎不能〉（几乎做不到）当成了〈不难〉（很容易做到）用。“一下就做完了”说明很容易，与“几乎不能做”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几乎不", "is_correct": true, "explanation": "正确：“几乎不”表示几乎没有苦味，与“孩子也能喝”相合。"}, {"text": "压根儿", "is_correct": false, "explanation": "搭配：“压根儿”须与“不”或“没”连用，“这种药压根儿苦”不成立。"}, {"text": "刚刚", "is_correct": false, "explanation": "体貌：“刚刚”表示时间上刚发生，药的苦味不是刚刚出现的，句意不通。"}, {"text": "难", "is_correct": false, "explanation": "语法：“难”不能直接修饰形容词作程度副词，“这种药难苦”不成立。"}], "explanations": {"几乎不": "正确：“几乎不”表示几乎没有苦味，与“孩子也能喝”相合。", "压根儿": "搭配：“压根儿”须与“不”或“没”连用，“这种药压根儿苦”不成立。", "刚刚": "体貌：“刚刚”表示时间上刚发生，药的苦味不是刚刚出现的，句意不通。", "难": "语法：“难”不能直接修饰形容词作程度副词，“这种药难苦”不成立。"}, "sentence_index": 6, "correct_answer": "几乎不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个办法非常可靠，几乎不可能成功。", "explanation": "这里应该用〈很可能〉。“非常可靠”与“几乎不可能成功”前后矛盾。"}, {"text": "他的成绩很好，几乎不可能及格。", "explanation": "“几乎不可能及格”表示很难及格，与“成绩很好”相矛盾。"}, {"text": "这道题非常容易，几乎不可能做错。我们都做错了。", "explanation": "“几乎不可能做错”表示极少有人做错，与“我们都做错了”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这碗粥几乎不没咸，老人能吃。", "corrected_sentence": "这碗粥几乎不咸，老人能吃。", "error_description": "重复否定：“几乎不”本身已含否定词“不”，后面不能再加“没”，应说“几乎不咸”，不能说“几乎不没咸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张床很软，我睡觉几乎几乎不做梦。", "corrected_sentence": "这张床很软，我睡觉几乎不做梦。", "error_description": "重复副词：“几乎”只用一次，应说“几乎不做梦”，不能说“几乎几乎不做梦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度比一般略高。", "primary_collocate": null, "pronunciation": "jiào wéi", "ipa": "tɕjɑʊ˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这个房间不大，但是较为舒服。", "target_word": "较为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家境较为富裕，但从不乱花钱。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路线不是最近的，但走起来较为轻松。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方的冬天较为干燥，要多喝水。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的价格较为合理，所以客人不少。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和哥哥相比，弟弟的性格较为安静。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试的题目较为简单，大家都答完了。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小区的交通较为方便，上班不用开车。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路的灯光较为昏暗，晚上走路要小心。", "target_word": "较为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天雨水较为充足，河水也涨高了。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "较为|副词|程度比一般略高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1bf60fe-067d-49a1-bd98-e843615aaeb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较为", "is_correct": true, "explanation": "正确。“较为”表示程度比一般略高，修饰“舒服”最合适。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，不能修饰“舒服”这类状态形容词。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示时间已完成，与程度无关，句意不通。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的状态，与“不大，但是……”的现状描述不符。"}], "explanations": {"较为": "正确。“较为”表示程度比一般略高，修饰“舒服”最合适。", "正在": "搭配：“正在”表示动作进行，不能修饰“舒服”这类状态形容词。", "已经": "语义：“已经”表示时间已完成，与程度无关，句意不通。", "曾经": "语义：“曾经”指过去的状态，与“不大，但是……”的现状描述不符。"}, "sentence_index": 0, "correct_answer": "较为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天比昨天较为热，大家都出汗了。", "explanation": "这里应该用〈更〉，说“比昨天更热”。“比”字句已经表示比较，要用“更”，不能再用“较为”。"}, {"text": "这道题最较为难，大家都不会做。", "explanation": "这里应该去掉〈较为〉，说“最难”。“最”已表示最高程度，不能与“较为”同用。"}, {"text": "这家店的菜有点较为贵，我们不常来。", "explanation": "这里应该去掉〈较为〉，说“有点贵”。“有点”已表示程度不高，“较为”也表示程度，二者不能同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较为", "is_correct": true, "explanation": "正确。“较为”修饰“简单”，表示程度略高，句意通顺。"}, {"text": "并非", "is_correct": false, "explanation": "语义：“并非简单”与后句“大家都答完了”的语境不协调。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不简单”与后句“大家都答完了”的语境不协调。"}, {"text": "仅仅", "is_correct": false, "explanation": "语义：“仅仅”表示只限于，与“题目简单”这一描述不搭。"}], "explanations": {"较为": "正确。“较为”修饰“简单”，表示程度略高，句意通顺。", "并非": "语义：“并非简单”与后句“大家都答完了”的语境不协调。", "不": "语义：“不简单”与后句“大家都答完了”的语境不协调。", "仅仅": "语义：“仅仅”表示只限于，与“题目简单”这一描述不搭。"}, "sentence_index": 6, "correct_answer": "较为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事非常较为重要，大家都要注意。", "explanation": "这里应该去掉〈非常〉。“较为”本身表示程度适中，不能再用“非常”修饰。"}, {"text": "天气越较为冷，大家都穿上了厚衣服。", "explanation": "这里应该去掉〈较为〉，说“天气越来越冷”。“越……”结构中不能加“较为”。"}, {"text": "这个汤太较为咸，我一口都没喝。", "explanation": "这里应该去掉〈较为〉，说“太咸”。“太”已表示程度过高，不能与“较为”同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条街人少，晚上走起来很较为安静。", "corrected_sentence": "这条街人少，晚上走起来较为安静。", "error_description": "错误：“较为”前面多加了程度副词“很”，写成“很较为安静”。正确：“较为安静”。原因：“较为”本身已表示程度，前面不能再加“很”等程度副词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地方的房租不较为便宜，很多学生都住在这里。", "corrected_sentence": "这个地方的房租较为便宜，很多学生都住在这里。", "error_description": "错误：“不”放在了“较为”前面，写成“不较为便宜”。正确：“较为便宜”。原因：“较为”不能被“不”修饰，表示否定时应说“不便宜”或“不太便宜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
