INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92754, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92754, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度比较高，相当于“比较”。", "primary_collocate": null, "pronunciation": "jiào wéi", "ipa": "tɕjɑʊ˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这本书的内容较为复杂，学生读起来有些难。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的空气较为新鲜，我们每个周末都去。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师讲课较为严格，学生都很认真。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的工作较为辛苦，常常晚上才回家。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给我们的条件较为优厚，大家都想留下。", "target_word": "较为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的物价较为昂贵，租房也不便宜。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的表现较为突出，老师在会上表扬了他。", "target_word": "较为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个问题的看法较为谨慎，不会随便下结论。", "target_word": "较为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的网速较为稳定，视频不会一直卡。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法虽然慢一点，但是较为安全。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "较为|副词|程度副词，相当于比较", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1bf60fe-067d-49a1-bd98-e843615aaeb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较为", "is_correct": true, "explanation": "正确。“较为”表示程度比较高，修饰“复杂”，句意通顺。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，不能修饰“复杂”这类状态形容词。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示时间已完成，与程度无关，句意不通。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的状态，与“学生读起来有些难”的现状不符。"}], "explanations": {"较为": "正确。“较为”表示程度比较高，修饰“复杂”，句意通顺。", "正在": "搭配：“正在”表示动作进行，不能修饰“复杂”这类状态形容词。", "已经": "语义：“已经”表示时间已完成，与程度无关，句意不通。", "曾经": "语义：“曾经”指过去的状态，与“学生读起来有些难”的现状不符。"}, "sentence_index": 0, "correct_answer": "较为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行我比朋友较为早到。", "explanation": "这里应该用〈更〉，说“比朋友更早到”。“比”字句中表示比较要用“更”，不能用“较为”。"}, {"text": "这部电影最较为精彩，值得一看。", "explanation": "这里应该去掉〈较为〉，说“最精彩”。“最”已表示最高程度，不能与“较为”同用。"}, {"text": "这件毛衣有点较为暖和，冬天穿正好。", "explanation": "这里应该去掉〈较为〉，说“有点暖和”。“有点”已表示程度不高，“较为”也表示程度，二者不能同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较为", "is_correct": true, "explanation": "正确。“较为”修饰“突出”，表示程度较高，与“老师表扬了他”相符。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不突出”与“老师表扬了他”的因果关系相矛盾。"}, {"text": "并非", "is_correct": false, "explanation": "语义：“并非突出”否定了表现，与老师的表扬相矛盾。"}, {"text": "仅仅", "is_correct": false, "explanation": "语义：“仅仅”表示只限于，与表扬的因果关系不符。"}], "explanations": {"较为": "正确。“较为”修饰“突出”，表示程度较高，与“老师表扬了他”相符。", "不": "语义：“不突出”与“老师表扬了他”的因果关系相矛盾。", "并非": "语义：“并非突出”否定了表现，与老师的表扬相矛盾。", "仅仅": "语义：“仅仅”表示只限于，与表扬的因果关系不符。"}, "sentence_index": 6, "correct_answer": "较为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的菜越较为好吃，客人也越来越多。", "explanation": "这里应该去掉〈较为〉，说“越好吃”。“越……”结构中不能加“较为”。"}, {"text": "他对这件事非常较为在意，连饭都顾不上吃。", "explanation": "这里应该去掉〈非常〉。“较为”本身表示程度，不能与“非常”同用。"}, {"text": "这盘饺子太较为烫，我没法吃。", "explanation": "这里应该去掉〈较为〉，说“太烫”。“太”已表示程度过高，不能与“较为”同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法特别较为省事，大家都愿意用。", "corrected_sentence": "这个办法较为省事，大家都愿意用。", "error_description": "错误：“较为”前面多加了程度副词“特别”，写成“特别较为省事”。正确：“较为省事”。原因：“较为”本身已表示程度，不能再与其他程度副词同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的治安很较为稳定，晚上也敢出门。", "corrected_sentence": "这个小区的治安较为稳定，晚上也敢出门。", "error_description": "错误：“很”和“较为”同时出现，写成“很较为稳定”。正确：“较为稳定”。原因：“较为”已经表示程度，前面不能再加“很”等程度副词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be722e46-e32d-4a8d-8189-15ca20c8e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
