INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92755, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92755, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "忽然是很快，没想到就发生了。", "primary_collocate": null, "pronunciation": "hū rán", "ipa": "xu˥ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "昨天我在路上忽然看到了老同学。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忽然说他明天要走。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风忽然大了起来。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忽然觉得很累。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的灯忽然灭了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈忽然问我想不想家。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚才还很热，现在忽然冷了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她忽然把门打开了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗忽然从树后跑了出来。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在说话，忽然不说了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忽然间", "label": "复合"}], "register": "中性", "sense_fingerprint": "很快发生，没有想到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b0b43b2-f2a1-4aa0-8f6e-1215570c5942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽然", "is_correct": true, "explanation": "正确：“忽然”表示出乎意料，与“在路上看到老同学”的偶遇相合。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意去做，与“在路上偶然看到”的情况矛盾。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示说话人的确信或推测，句子会变成对过去的判断，而非突然遇见老同学的叙述。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是文言副词，口语中不用于叙述日常经历。"}], "explanations": {"忽然": "正确：“忽然”表示出乎意料，与“在路上看到老同学”的偶遇相合。", "特意": "语义：“特意”表示有意去做，与“在路上偶然看到”的情况矛盾。", "一定": "语义：“一定”表示说话人的确信或推测，句子会变成对过去的判断，而非突然遇见老同学的叙述。", "遂": "语域：“遂”是文言副词，口语中不用于叙述日常经历。"}, "sentence_index": 0, "correct_answer": "忽然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我忽然是他的老师。", "explanation": "语义错误：〈忽然〉表示突然发生，不能用于“是老师”这种身份关系，这里应说〈成了〉。"}, {"text": "我忽然在这里住了十年。", "explanation": "语义错误：“忽然”表示突然发生，不能修饰“住了十年”这种长时段的状态。"}, {"text": "每年冬天，我忽然都要出国一次。", "explanation": "语义错误：〈忽然〉表示没有预料到的情况，不能用于每年都重复的安排，这里应说〈通常〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忽然", "is_correct": true, "explanation": "正确：“忽然”表示突然发生的变化，与“刚才还很热，现在冷了”的转变相合。"}, {"text": "依然", "is_correct": false, "explanation": "语义：“依然”表示仍旧如此，与“刚才很热，现在变冷”的变化矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常发生，与前后明显的转变不合。"}, {"text": "乃", "is_correct": false, "explanation": "语域：“乃”是文言副词，现代口语中不用于描述天气变化。"}], "explanations": {"忽然": "正确：“忽然”表示突然发生的变化，与“刚才还很热，现在冷了”的转变相合。", "依然": "语义：“依然”表示仍旧如此，与“刚才很热，现在变冷”的变化矛盾。", "偶尔": "语义：“偶尔”表示不经常发生，与前后明显的转变不合。", "乃": "语域：“乃”是文言副词，现代口语中不用于描述天气变化。"}, "sentence_index": 6, "correct_answer": "忽然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你应该忽然把作业写完。", "explanation": "语义错误：“忽然”描述已经发生的事，不能与“应该”这种表示要求的情态动词连用。"}, {"text": "请你忽然把灯打开。", "explanation": "语义错误：“忽然”描述出乎意料地发生的事，不能用于对他人提出请求。"}, {"text": "我每天都忽然去跑步。", "explanation": "语义错误：〈忽然〉表示意外的一次性变化，不能与“每天都”这种规律性的重复连用，这里应去掉〈忽然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他突然忽然觉得头很晕。", "corrected_sentence": "他忽然觉得头很晕。", "error_description": "重复错误：“突然”与“忽然”意思相近，不能叠用，应只用“忽然”，说“他忽然觉得头很晕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忽然笑了下来。", "corrected_sentence": "他忽然笑了起来。", "error_description": "补语错误：“笑”之后表示开始的补语应为“起来”，不能说“下来”，应说“他忽然笑了起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
