INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92756, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示情况来得迅速而出人意料。", "primary_collocate": null, "pronunciation": "hū rán", "ipa": "xu˥ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "我正在看书，忽然停电了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天忽然下起雨来。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忽然站了起来。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走着走着，她忽然笑了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里忽然安静了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忽然想起忘了带钥匙。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上忽然出现了一朵大黑云。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子忽然大声哭了起来。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，手机忽然响了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开到一半，忽然停住了。", "target_word": "忽然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忽然间", "label": "复合"}], "register": "中性", "sense_fingerprint": "情况来得很快，出人意料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b0b43b2-f2a1-4aa0-8f6e-1215570c5942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽然", "is_correct": true, "explanation": "正确：“忽然”表示突然发生、出乎意料，与“正在看书，停电了”相合。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“停电”这一突发事件不合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一向如此，与“正在看书，停电了”的突发情况不合。"}, {"text": "必然", "is_correct": false, "explanation": "语域：“必然”语体偏书面，且表示必然结果，与日常突发的停电不合。"}], "explanations": {"忽然": "正确：“忽然”表示突然发生、出乎意料，与“正在看书，停电了”相合。", "一直": "语义：“一直”表示持续不断，与“停电”这一突发事件不合。", "从来": "语义：“从来”指一向如此，与“正在看书，停电了”的突发情况不合。", "必然": "语域：“必然”语体偏书面，且表示必然结果，与日常突发的停电不合。"}, "sentence_index": 0, "correct_answer": "忽然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我忽然学了三年汉语。", "explanation": "语义错误：“忽然”表示突然发生，不能修饰“学了三年”这种持续很久的动作。"}, {"text": "我每个星期六都忽然去打球。", "explanation": "语义错误：〈忽然〉表示情况来得迅速、出人意料，不能用于每个星期六都有的固定安排，这里应去掉〈忽然〉。"}, {"text": "这台电脑我忽然用了十年，至今还很好用。", "explanation": "语义错误：〈忽然〉表示情况来得迅速，不能修饰“用了十年”这种长期持续的状态，这里应表示〈一直〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忽然", "is_correct": true, "explanation": "正确：“忽然”表示突然出现，与“天上出现了一朵大黑云”相合。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常，与“出现一朵云”的一次性事件矛盾。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意为之，云不能有意出现。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是文言色彩很浓的副词，白话口语中不用于此类叙述，且表示“于是”，并不表示出乎意料。"}], "explanations": {"忽然": "正确：“忽然”表示突然出现，与“天上出现了一朵大黑云”相合。", "总是": "语义：“总是”表示经常，与“出现一朵云”的一次性事件矛盾。", "特意": "语义：“特意”表示有意为之，云不能有意出现。", "遂": "语域：“遂”是文言色彩很浓的副词，白话口语中不用于此类叙述，且表示“于是”，并不表示出乎意料。"}, "sentence_index": 6, "correct_answer": "忽然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你忽然安静下来。", "explanation": "语义错误：“忽然”描述出乎意料地发生的事，不能用于对他人提出请求或命令。"}, {"text": "你应该忽然起床。", "explanation": "语义错误：“忽然”描述已经发生的事，不能与“应该”这种表示要求的情态动词连用。"}, {"text": "我们每天早上都忽然跑步。", "explanation": "语义错误：〈忽然〉表示意外的一次性变化，不能与“每天早上都”的规律性重复连用，这里应去掉〈忽然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她突然忽然停下脚步。", "corrected_sentence": "她忽然停下脚步。", "error_description": "重复错误：“突然”与“忽然”意思相近，不能叠用，应只用“忽然”，说“她忽然停下脚步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很忽然哭了起来。", "corrected_sentence": "她忽然哭了起来。", "error_description": "修饰错误：“忽然”是副词，不能被程度副词“很”修饰，应说“她忽然哭了起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
