INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "询问事情的原因或经过的疑问短语。", "primary_collocate": null, "pronunciation": "zěn me huí shì", "ipa": "tʂən˨˩ mɘ xweɪ˧˥ ʂʅ˥˩", "syllable_count": 4, "sentences": [{"text": "你先说说，昨天到底是怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉我，这件事是怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把整件事的经过讲了，我才明白是怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我也不知道这是怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问我：“这是怎么回事？”", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哭了，妈妈想知道怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的脸上有伤，到底怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在看我，我不明白怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们吵什么？先让我弄清楚怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里这么乱，是怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怎么回事儿", "label": "儿化形式"}], "register": "口语", "sense_fingerprint": "询问事情的原因或经过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b0b43b2-f2a1-4aa0-8f6e-1215570c5942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎么回事", "is_correct": true, "explanation": "“怎么回事”询问事情的原因或经过，与“你先说说”的语境相符。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，句子问的是事情的原因或经过。"}, {"text": "怎么", "is_correct": false, "explanation": "配价：“怎么”后面要接动词或形容词，“昨天到底是怎么”句子不完整。"}, {"text": "几", "is_correct": false, "explanation": "配价：“几”后面要接量词或名词，“昨天到底是几”不成立，句子问的也不是数目。"}], "explanations": {"怎么回事": "“怎么回事”询问事情的原因或经过，与“你先说说”的语境相符。", "多少": "语义：“多少”问数量，句子问的是事情的原因或经过。", "怎么": "配价：“怎么”后面要接动词或形容词，“昨天到底是怎么”句子不完整。", "几": "配价：“几”后面要接量词或名词，“昨天到底是几”不成立，句子问的也不是数目。"}, "sentence_index": 0, "correct_answer": "怎么回事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想学游泳，你能教我怎么回事吗？", "explanation": "这里误把〈怎么回事〉当作“怎么做”来用，应该用〈怎么做〉。“怎么回事”问发生了什么或为什么这样，不问具体的做法。"}, {"text": "这部小说你觉得怎么回事？", "explanation": "这里应该用〈怎么样〉。“怎么回事”问原因或经过，不用于征求对小说的评价。"}, {"text": "这台洗衣机我不会用，请你教我怎么回事。", "explanation": "这里应该用〈怎么用〉。“怎么回事”问原因或经过，不问操作的方法，也不能作“教”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎么回事", "is_correct": true, "explanation": "“怎么回事”询问脸上有伤的原因，与句意相符。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，句子问的是受伤的原因，不是伤的数目。"}, {"text": "什么", "is_correct": false, "explanation": "配价：“什么”之后需要谓语，“到底什么”缺少能与之搭配的成分。"}, {"text": "哪种", "is_correct": false, "explanation": "搭配：“哪种”要求后接类别名词，“到底哪种”无法表达这个问句。"}], "explanations": {"怎么回事": "“怎么回事”询问脸上有伤的原因，与句意相符。", "多少": "语义：“多少”问数量，句子问的是受伤的原因，不是伤的数目。", "什么": "配价：“什么”之后需要谓语，“到底什么”缺少能与之搭配的成分。", "哪种": "搭配：“哪种”要求后接类别名词，“到底哪种”无法表达这个问句。"}, "sentence_index": 6, "correct_answer": "怎么回事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题我不会做，你能教我怎么回事。", "explanation": "这里应该用〈怎么做〉。“怎么回事”询问原因或经过，不问具体的做法。"}, {"text": "这次比赛输了，我们下一步怎么回事？", "explanation": "这里应该用〈怎么办〉。“怎么回事”问发生了什么或为什么这样，不问接下来如何处理。"}, {"text": "我想换个发型，请你教我怎么回事。", "explanation": "这里应该用〈怎么做〉。“怎么回事”问原因或经过，不问具体的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不明白这件事到底是怎么回事吗？", "corrected_sentence": "我不明白这件事到底是怎么回事。", "error_description": "语气词错误：“怎么回事”本身已是疑问结构，句中不能再加疑问语气词“吗”。应说“到底是怎么回事”，不说“到底是怎么回事吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里的灯突然很灭了，这是怎么回事？", "corrected_sentence": "屋里的灯突然灭了，这是怎么回事？", "error_description": "程度副词错误：“很”不能修饰“灭”这类动作性的变化动词，“突然很灭了”不成立。去掉“很”即正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911e1fef-8b62-41ef-9787-8082a21bf08f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
