INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92761, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "惨是特别让人难过，看了心里很不好受。", "primary_collocate": null, "pronunciation": "cǎn", "ipa": "tsʰan˨˩˦", "syllable_count": 1, "sentences": [{"text": "那只小狗一个人站在雨里，真惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一个人住，没人照顾，真惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到地震后的照片，我觉得太惨了。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的房子烧了，真是太惨了。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着找妈妈，样子很惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他一个人在外面过年，真惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个电影的结局太惨，我哭了。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事很惨，大家听了都不说话。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他一个人坐在路边，样子多惨啊。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让很多人没有家，生活很惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "惨：情景可怜，让人看了心里难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94ef46ac-c75d-4aa5-b593-6bca6ddab68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "惨", "is_correct": true, "explanation": "惨 cǎn（第三声）意思是凄惨、让人难过，与听到的读音相符。"}, {"text": "残", "is_correct": false, "explanation": "cán（第二声）与 cǎn（第三声）声调不同，意思是残缺、残酷。"}, {"text": "伞", "is_correct": false, "explanation": "sǎn 与 cǎn 声母不同（s 与 c），声调相同，意思是雨伞。"}, {"text": "产", "is_correct": false, "explanation": "chǎn 与 cǎn 声母不同（ch 与 c），声调相同，意思是生产、产品。"}, {"text": "攒", "is_correct": false, "explanation": "zǎn 与 cǎn 声母不同（z 与 c），声调相同，意思是积攒。"}, {"text": "参", "is_correct": false, "explanation": "cān（第一声）与 cǎn（第三声）声调不同，意思是参加。"}], "explanations": {"惨": "惨 cǎn（第三声）意思是凄惨、让人难过，与听到的读音相符。", "残": "cán（第二声）与 cǎn（第三声）声调不同，意思是残缺、残酷。", "伞": "sǎn 与 cǎn 声母不同（s 与 c），声调相同，意思是雨伞。", "产": "chǎn 与 cǎn 声母不同（ch 与 c），声调相同，意思是生产、产品。", "攒": "zǎn 与 cǎn 声母不同（z 与 c），声调相同，意思是积攒。", "参": "cān（第一声）与 cǎn（第三声）声调不同，意思是参加。"}, "sentence_index": null, "correct_answer": "惨"}, "level_3": {"options": [{"text": "惨", "is_correct": true, "explanation": "正确：“惨”形容小狗孤单淋雨的可怜情景，与句中描述相合。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：“真幸福”说的是快乐满足，与“一个人站在雨里”的情形相反。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”指场面人多，不能用来形容“一个人”的情形。"}, {"text": "舒服", "is_correct": false, "explanation": "语义：“真舒服”表示身体或感觉好，与“站在雨里”的情形不合。"}], "explanations": {"惨": "正确：“惨”形容小狗孤单淋雨的可怜情景，与句中描述相合。", "幸福": "语义：“真幸福”说的是快乐满足，与“一个人站在雨里”的情形相反。", "热闹": "搭配：“热闹”指场面人多，不能用来形容“一个人”的情形。", "舒服": "语义：“真舒服”表示身体或感觉好，与“站在雨里”的情形不合。"}, "sentence_index": 0, "correct_answer": "惨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "婚礼上大家都很惨，很多人在唱歌。", "explanation": "这里应该用〈高兴〉。“惨”表示凄凉、让人难过，婚礼是喜事，不能用“惨”形容。"}, {"text": "这首歌很惨，听了让人很开心。", "explanation": "这里应该用〈欢快〉。“惨”表示凄凉、让人难过，与“让人很开心”相矛盾。"}, {"text": "这个小镇的风景很惨，大家都觉得很美。", "explanation": "这里应该用〈美丽〉。“惨”不能形容让人赞美的风景，与“很美”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92761, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "惨", "is_correct": true, "explanation": "惨 cǎn（第三声）意思是凄惨、让人难过，与听到的读音相符。"}, {"text": "蚕", "is_correct": false, "explanation": "cán（第二声）与 cǎn（第三声）声调不同，意思是蚕。"}, {"text": "灿", "is_correct": false, "explanation": "càn（第四声）与 cǎn（第三声）声调不同，意思是灿烂。"}, {"text": "攒", "is_correct": false, "explanation": "zǎn 与 cǎn 声母不同（z 与 c），声调相同，意思是积攒。"}, {"text": "铲", "is_correct": false, "explanation": "chǎn 与 cǎn 声母不同（ch 与 c），声调相同，意思是铲子。"}], "explanations": {"惨": "惨 cǎn（第三声）意思是凄惨、让人难过，与听到的读音相符。", "蚕": "cán（第二声）与 cǎn（第三声）声调不同，意思是蚕。", "灿": "càn（第四声）与 cǎn（第三声）声调不同，意思是灿烂。", "攒": "zǎn 与 cǎn 声母不同（z 与 c），声调相同，意思是积攒。", "铲": "chǎn 与 cǎn 声母不同（ch 与 c），声调相同，意思是铲子。"}, "sentence_index": null, "correct_answer": "惨"}, "level_3": {"options": [{"text": "惨", "is_correct": true, "explanation": "正确：“惨”表示结局凄凉、让人伤心落泪，与“我哭了”相合。"}, {"text": "平淡", "is_correct": false, "explanation": "语义：“平淡”说情节不起波澜，不会让人落泪，与“我哭了”矛盾。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”多用于物品和工艺，不能说结局精致。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物的身形，不能用来形容电影的结局。"}], "explanations": {"惨": "正确：“惨”表示结局凄凉、让人伤心落泪，与“我哭了”相合。", "平淡": "语义：“平淡”说情节不起波澜，不会让人落泪，与“我哭了”矛盾。", "精致": "搭配：“精致”多用于物品和工艺，不能说结局精致。", "高大": "搭配：“高大”形容人或物的身形，不能用来形容电影的结局。"}, "sentence_index": 6, "correct_answer": "惨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祝你生日快乐，每天都过得很惨！", "explanation": "这里应该用〈幸福〉。“惨”表示悲苦，不能用于生日祝福。"}, {"text": "这幅画颜色很惨，色彩鲜艳，让人很喜欢。", "explanation": "这里应该用〈好看〉。“惨”表示让人难过，与“色彩鲜艳，让人很喜欢”相矛盾。"}, {"text": "他的笑话很惨，大家都笑个不停。", "explanation": "这里应该用〈幽默〉。“惨”表示让人难过，与“大家都笑个不停”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个孩子找不到妈妈，哭很惨。", "corrected_sentence": "那个孩子找不到妈妈，哭得很惨。", "error_description": "“哭很惨”漏掉补语标记“得”，应说“哭得很惨”。“惨”作补语时，要用“得”连接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很惨故事，大家都哭了。", "corrected_sentence": "这是一个很惨的故事，大家都哭了。", "error_description": "“很惨故事”漏掉定语标记“的”，应说“很惨的故事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
