INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92762, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "悲痛；凄苦；程度严重而使人不忍。", "primary_collocate": null, "pronunciation": "cǎn", "ipa": "tsʰan˨˩˦", "syllable_count": 1, "sentences": [{"text": "昨天的比赛，我们队输得很惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试我考得太惨了，才三十分。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔得很惨，腿都不能动了。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚下大雨，我淋得好惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近生意很惨，一天只来两个人。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在车祸中伤得很惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年天旱，农民的收成很惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家人的日子过得很惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上课说话，被老师骂得很惨。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场车祸太惨了，路上到处是血。", "target_word": "惨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "惨：遭遇或结果严重，程度很深，让人不忍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94ef46ac-c75d-4aa5-b593-6bca6ddab68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92762, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "惨", "is_correct": true, "explanation": "惨 cǎn（第三声）意思是严重、很糟，与听到的读音相符。"}, {"text": "残", "is_correct": false, "explanation": "cán（第二声）与 cǎn（第三声）声调不同，意思是残缺、残酷。"}, {"text": "参", "is_correct": false, "explanation": "cān（第一声）与 cǎn（第三声）声调不同，意思是参加。"}, {"text": "灿", "is_correct": false, "explanation": "càn（第四声）与 cǎn（第三声）声调不同，意思是灿烂。"}, {"text": "攒", "is_correct": false, "explanation": "zǎn 与 cǎn 声母不同（z 与 c），声调相同，意思是积攒。"}], "explanations": {"惨": "惨 cǎn（第三声）意思是严重、很糟，与听到的读音相符。", "残": "cán（第二声）与 cǎn（第三声）声调不同，意思是残缺、残酷。", "参": "cān（第一声）与 cǎn（第三声）声调不同，意思是参加。", "灿": "càn（第四声）与 cǎn（第三声）声调不同，意思是灿烂。", "攒": "zǎn 与 cǎn 声母不同（z 与 c），声调相同，意思是积攒。"}, "sentence_index": null, "correct_answer": "惨"}, "level_3": {"options": [{"text": "惨", "is_correct": true, "explanation": "正确：“惨”表示输得严重、很彻底，与“输得很”相合。"}, {"text": "着急", "is_correct": false, "explanation": "语义：“着急”指心里焦躁，不能用来形容比赛输得怎样。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“输得很高兴”与输掉比赛的结果矛盾。"}, {"text": "得意", "is_correct": false, "explanation": "语义：“得意”指因成功而自满，输了比赛不能说得意。"}], "explanations": {"惨": "正确：“惨”表示输得严重、很彻底，与“输得很”相合。", "着急": "语义：“着急”指心里焦躁，不能用来形容比赛输得怎样。", "高兴": "语义：“输得很高兴”与输掉比赛的结果矛盾。", "得意": "语义：“得意”指因成功而自满，输了比赛不能说得意。"}, "sentence_index": 0, "correct_answer": "惨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们队这次赢得很惨。", "explanation": "这里应该用〈漂亮〉。“惨”表示结果糟糕，用于胜利的结果会自相矛盾。"}, {"text": "这次考试他考得很惨，成绩全班第一。", "explanation": "这里应该用〈好〉。“惨”说结果很糟，与“成绩全班第一”相矛盾。"}, {"text": "这场演出他演得很惨，观众给了很多掌声。", "explanation": "这里应该用〈精彩〉。“惨”表示糟糕，与热烈的掌声相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92762, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "惨", "is_correct": true, "explanation": "惨 cǎn（第三声）意思是严重、很糟，与听到的读音相符。"}, {"text": "蚕", "is_correct": false, "explanation": "cán（第二声）与 cǎn（第三声）声调不同，意思是蚕。"}, {"text": "伞", "is_correct": false, "explanation": "sǎn 与 cǎn 声母不同（s 与 c），声调相同，意思是雨伞。"}, {"text": "攒", "is_correct": false, "explanation": "zǎn 与 cǎn 声母不同（z 与 c），声调相同，意思是积攒。"}, {"text": "产", "is_correct": false, "explanation": "chǎn 与 cǎn 声母不同（ch 与 c），声调相同，意思是生产、产品。"}], "explanations": {"惨": "惨 cǎn（第三声）意思是严重、很糟，与听到的读音相符。", "蚕": "cán（第二声）与 cǎn（第三声）声调不同，意思是蚕。", "伞": "sǎn 与 cǎn 声母不同（s 与 c），声调相同，意思是雨伞。", "攒": "zǎn 与 cǎn 声母不同（z 与 c），声调相同，意思是积攒。", "产": "chǎn 与 cǎn 声母不同（ch 与 c），声调相同，意思是生产、产品。"}, "sentence_index": null, "correct_answer": "惨"}, "level_3": {"options": [{"text": "惨", "is_correct": true, "explanation": "正确：“惨”表示收成很糟，与“天旱”的原因相合。"}, {"text": "丰富", "is_correct": false, "explanation": "语义：“收成丰富”与“天旱”的原因相矛盾。"}, {"text": "充足", "is_correct": false, "explanation": "语义：“收成充足”说收成够多，与“天旱”的语境不合。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能说收成清脆。"}], "explanations": {"惨": "正确：“惨”表示收成很糟，与“天旱”的原因相合。", "丰富": "语义：“收成丰富”与“天旱”的原因相矛盾。", "充足": "语义：“收成充足”说收成够多，与“天旱”的语境不合。", "清脆": "搭配：“清脆”形容声音，不能说收成清脆。"}, "sentence_index": 6, "correct_answer": "惨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节日的街道很惨，到处都是灯笼和笑声。", "explanation": "这里应该用〈热闹〉。“惨”表示凄凉，与灯笼和笑声的节日气氛相矛盾。"}, {"text": "这次旅行我们过得很惨，每个人都很满足。", "explanation": "这里应该用〈愉快〉。“惨”表示凄苦，与“很满足”相矛盾。"}, {"text": "这辆新车开起来很惨，又快又稳。", "explanation": "这里应该用〈好〉。“惨”表示结果很糟，与“又快又稳”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个小孩摔很惨，哭个不停。", "corrected_sentence": "那个小孩摔得很惨，哭个不停。", "error_description": "“摔很惨”漏掉补语标记“得”，应说“摔得很惨”。“惨”作补语时，要用“得”连接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨晚的比赛，他们输地很惨。", "corrected_sentence": "昨晚的比赛，他们输得很惨。", "error_description": "“输地很惨”用错了结构助词，补语前应用“得”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb7c6870-df9b-44cd-b239-97d633319a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拔出", "is_correct": true, "explanation": "拔出：把陷在里面的东西拉出来，与“陷入泥坑”的意思相反。"}, {"text": "观看", "is_correct": false, "explanation": "观看：指用眼睛看，与“陷入”没有反义关系，句中不通顺。"}, {"text": "准备", "is_correct": false, "explanation": "准备：指事先安排，与“陷入”不构成反义，句中也不合适。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指把坏的东西修好，与“陷入泥坑”没有反义关系。"}], "correct_answer": "拔出", "explanations": {"拔出": "拔出：把陷在里面的东西拉出来，与“陷入泥坑”的意思相反。", "观看": "观看：指用眼睛看，与“陷入”没有反义关系，句中不通顺。", "准备": "准备：指事先安排，与“陷入”不构成反义，句中也不合适。", "修理": "修理：指把坏的东西修好，与“陷入泥坑”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱出", "is_correct": true, "explanation": "脱出：从流沙里出来，与“陷入流沙”的意思相反。"}, {"text": "购买", "is_correct": false, "explanation": "购买：指花钱买东西，与“陷入”没有反义关系，句中不通顺。"}, {"text": "测量", "is_correct": false, "explanation": "测量：指量出长度或大小，与“陷入流沙”不构成反义。"}, {"text": "粉刷", "is_correct": false, "explanation": "粉刷：指给墙面涂颜料，与“陷入流沙”没有反义关系。"}], "correct_answer": "脱出", "explanations": {"脱出": "脱出：从流沙里出来，与“陷入流沙”的意思相反。", "购买": "购买：指花钱买东西，与“陷入”没有反义关系，句中不通顺。", "测量": "测量：指量出长度或大小，与“陷入流沙”不构成反义。", "粉刷": "粉刷：指给墙面涂颜料，与“陷入流沙”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "陷入是掉进去，出不来。", "primary_collocate": null, "pronunciation": "xiàn rù", "ipa": "ɕjɛn⁵¹ ɻu⁵¹", "syllable_count": 2, "sentences": [{"text": "汽车陷入了泥里。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚陷入雪地里。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车轮陷入沙子里，开不出来。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一不小心，鞋子陷入了泥坑。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的腿陷入了河边的烂泥。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发太软，人一坐就陷入其中。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的脚陷入沼泽，拔不出来。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车陷入深深的泥坑。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小车陷入雪中，走不动了。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢陷入了流沙里。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陷入了", "label": "体标"}], "register": "书面", "sense_fingerprint": "身体或物体掉进泥、雪、沙等里面出不来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陷入", "is_correct": true, "explanation": "正确答案：陷入（xiànrù）。"}, {"text": "线路", "is_correct": false, "explanation": "线路 xiànlù 与 陷入 xiànrù 只有第二个音节不同：lù 与 rù 声母不同（l 与 r），意思是线路。"}, {"text": "先入", "is_correct": false, "explanation": "先入 xiānrù 与 陷入 xiànrù 只有第一个音节声调不同（xiān 为第一声，xiàn 为第四声），意思是先进入。"}, {"text": "现任", "is_correct": false, "explanation": "现任 xiànrèn 与 陷入 xiànrù 第二个音节只有韵母不同（rèn 与 rù），意思是现在担任某个职务。"}], "explanations": {"陷入": "正确答案：陷入（xiànrù）。", "线路": "线路 xiànlù 与 陷入 xiànrù 只有第二个音节不同：lù 与 rù 声母不同（l 与 r），意思是线路。", "先入": "先入 xiānrù 与 陷入 xiànrù 只有第一个音节声调不同（xiān 为第一声，xiàn 为第四声），意思是先进入。", "现任": "现任 xiànrèn 与 陷入 xiànrù 第二个音节只有韵母不同（rèn 与 rù），意思是现在担任某个职务。"}, "sentence_index": null, "correct_answer": "陷入"}, "level_3": {"options": [{"text": "陷入", "is_correct": true, "explanation": "陷入：物体掉进泥里出不来，与句意相合。"}, {"text": "跳进", "is_correct": false, "explanation": "语义：“跳进”的主语要能跳，汽车不能跳进泥里。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”多搭配物体表面，不说擦拭泥里。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”多搭配房间、场地，不说打扫泥里。"}], "explanations": {"陷入": "陷入：物体掉进泥里出不来，与句意相合。", "跳进": "语义：“跳进”的主语要能跳，汽车不能跳进泥里。", "擦拭": "搭配：“擦拭”多搭配物体表面，不说擦拭泥里。", "打扫": "搭配：“打扫”多搭配房间、场地，不说打扫泥里。"}, "sentence_index": 0, "correct_answer": "陷入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳慢慢陷入了西山。", "explanation": "这里应该用〈沉入〉。陷入指东西掉进泥、雪里出不来，太阳落山并不是被困住，要用沉入。"}, {"text": "他把牛奶陷入了碗里。", "explanation": "这里应该用〈倒入〉。陷入指东西掉进泥、雪里出不来，把牛奶倒进碗里是移动，不是陷住，要用倒入。"}, {"text": "他把钥匙陷入了抽屉里。", "explanation": "这里应该用〈扔进〉。陷入指东西陷进泥、雪里出不来，把钥匙扔进抽屉不是陷住，要用扔进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陷入", "is_correct": true, "explanation": "陷入：脚陷进沼泽里，符合句意。"}, {"text": "扔进", "is_correct": false, "explanation": "语义：“扔进”指把物体抛进去，脚不能被扔进沼泽。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语多是衣物、身体，不说洗沼泽。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的宾语多是球或物件，踢沼泽不合常理。"}], "explanations": {"陷入": "陷入：脚陷进沼泽里，符合句意。", "扔进": "语义：“扔进”指把物体抛进去，脚不能被扔进沼泽。", "洗": "搭配：“洗”的宾语多是衣物、身体，不说洗沼泽。", "踢": "搭配：“踢”的宾语多是球或物件，踢沼泽不合常理。"}, "sentence_index": 6, "correct_answer": "陷入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水陷入了大海。", "explanation": "这里应该用〈流入〉。陷入指东西掉进泥、雪里出不来，河水流入大海是流动，不是被困住，要用流入。"}, {"text": "他们陷入了新房子。", "explanation": "这里应该用〈搬进〉。陷入指东西掉进泥、雪里出不来，搬进新房子是入住，不是被困住，要用搬进。"}, {"text": "他把水陷入了杯子里。", "explanation": "这里应该用〈注入〉。陷入指东西掉进泥、雪里出不来，往杯子里注水不是被困住，要用注入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车子陷入在沙坑，动不了。", "corrected_sentence": "车子陷入了沙坑，动不了。", "error_description": "“在”误用：“陷入”后可直接带处所，不需要“在”，应说“陷入了沙坑”（或说“陷在沙坑里”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小船被陷入了湖底的淤泥。", "corrected_sentence": "小船陷入了湖底的淤泥。", "error_description": "“被”误用：“陷入”不能用“被”构成被动式，应说“小船陷入了湖底的淤泥”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "摆脱", "is_correct": true, "explanation": "摆脱：指脱离困境或束缚，与“陷入不利境地”的意思相反。"}, {"text": "完成", "is_correct": false, "explanation": "完成：指做完某件事，与“陷入”不构成反义关系，句中也不通顺。"}, {"text": "观察", "is_correct": false, "explanation": "观察：指仔细看，与“陷入”没有反义关系，不能替代句中的意思。"}, {"text": "准备", "is_correct": false, "explanation": "准备：指事先安排，与“陷入”的意思不相对，句中也不合适。"}], "correct_answer": "摆脱", "explanations": {"摆脱": "摆脱：指脱离困境或束缚，与“陷入不利境地”的意思相反。", "完成": "完成：指做完某件事，与“陷入”不构成反义关系，句中也不通顺。", "观察": "观察：指仔细看，与“陷入”没有反义关系，不能替代句中的意思。", "准备": "准备：指事先安排，与“陷入”的意思不相对，句中也不合适。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走出", "is_correct": true, "explanation": "走出：从回忆中出来，与“陷入回忆”的意思相反。"}, {"text": "尝试", "is_correct": false, "explanation": "尝试：指动手试一试，与“陷入”没有反义关系，句中不通顺。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指把坏的东西修好，与“陷入回忆”没有反义关系。"}, {"text": "考虑", "is_correct": false, "explanation": "考虑：指思量，与“陷入”不构成反义，不能替代句中的意思。"}], "correct_answer": "走出", "explanations": {"走出": "走出：从回忆中出来，与“陷入回忆”的意思相反。", "尝试": "尝试：指动手试一试，与“陷入”没有反义关系，句中不通顺。", "修理": "修理：指把坏的东西修好，与“陷入回忆”没有反义关系。", "考虑": "考虑：指思量，与“陷入”不构成反义，不能替代句中的意思。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "落入不利的境地或状态；深深地进入。", "primary_collocate": null, "pronunciation": "xiàn rù", "ipa": "ɕjɛn⁵¹ ɻu⁵¹", "syllable_count": 2, "sentences": [{"text": "公司陷入了困难。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着照片，陷入了沉思。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家陷入了战争。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到消息，她陷入了痛苦。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人陷入了激烈的争吵。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电后，小城陷入一片黑暗。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生意陷入了危机。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太累了，很快就陷入了沉睡。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能让自己陷入麻烦。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老房子，爸爸陷入了回忆。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陷入了", "label": "体标"}], "register": "书面", "sense_fingerprint": "落入困难、沉思等不利或深沉的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陷入", "is_correct": true, "explanation": "正确答案：陷入（xiànrù）。"}, {"text": "线路", "is_correct": false, "explanation": "线路 xiànlù 与 陷入 xiànrù 只有第二个音节不同：lù 与 rù 声母不同（l 与 r），意思是线路。"}, {"text": "先入", "is_correct": false, "explanation": "先入 xiānrù 与 陷入 xiànrù 只有第一个音节声调不同（xiān 为第一声，xiàn 为第四声），意思是先进入，多见于“先入为主”。"}, {"text": "现任", "is_correct": false, "explanation": "现任 xiànrèn 与 陷入 xiànrù 第二个音节只有韵母不同（rèn 与 rù），意思是现在担任某个职务。"}], "explanations": {"陷入": "正确答案：陷入（xiànrù）。", "线路": "线路 xiànlù 与 陷入 xiànrù 只有第二个音节不同：lù 与 rù 声母不同（l 与 r），意思是线路。", "先入": "先入 xiānrù 与 陷入 xiànrù 只有第一个音节声调不同（xiān 为第一声，xiàn 为第四声），意思是先进入，多见于“先入为主”。", "现任": "现任 xiànrèn 与 陷入 xiànrù 第二个音节只有韵母不同（rèn 与 rù），意思是现在担任某个职务。"}, "sentence_index": null, "correct_answer": "陷入"}, "level_3": {"options": [{"text": "陷入", "is_correct": true, "explanation": "陷入：落入困难的境地，与句意相合。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象是场所、展览等，困难不能被参观。"}, {"text": "赢得", "is_correct": false, "explanation": "搭配：“赢得”多搭配胜利、尊重，不说赢得困难。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多搭配生活、待遇，不说享受困难。"}], "explanations": {"陷入": "陷入：落入困难的境地，与句意相合。", "参观": "语义：“参观”的对象是场所、展览等，困难不能被参观。", "赢得": "搭配：“赢得”多搭配胜利、尊重，不说赢得困难。", "享受": "搭配：“享受”多搭配生活、待遇，不说享受困难。"}, "sentence_index": 0, "correct_answer": "陷入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她陷入了一顿丰盛的晚饭。", "explanation": "这里应该用〈吃〉。陷入指落入不利的境地或深陷某种状态，不用来指吃饭，要用吃。"}, {"text": "会议陷入了高潮，大家都很兴奋。", "explanation": "这里应该用〈进入〉。陷入指落入不利的境地，会议热烈地发展属于正常过程，要用进入。"}, {"text": "他陷入了一场晚会。", "explanation": "这里应该用〈参加〉。陷入指落入不利的境地或深陷某种状态，不表示到场参加，要用参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陷入", "is_correct": true, "explanation": "陷入：陷入危机，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多搭配艺术品、风景，不说欣赏危机。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指尝食物的味道，与危机无关。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：“建造”多搭配房屋、桥梁，不说建造危机。"}], "explanations": {"陷入": "陷入：陷入危机，符合句意。", "欣赏": "搭配：“欣赏”多搭配艺术品、风景，不说欣赏危机。", "品尝": "语义：“品尝”指尝食物的味道，与危机无关。", "建造": "搭配：“建造”多搭配房屋、桥梁，不说建造危机。"}, "sentence_index": 6, "correct_answer": "陷入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直陷入锻炼身体。", "explanation": "这里应该用〈坚持〉。陷入表示落入不利的境地或深陷某种状态，不用于持续做某件事，坚持锻炼要用坚持。"}, {"text": "我们在海边陷入了温暖的阳光。", "explanation": "这里应该用〈享受〉。陷入表示落入不利或沉重的状态，享受阳光是愉快的事，要用享受。"}, {"text": "他陷入了一封信，很高兴。", "explanation": "这里应该用〈收到〉。陷入表示落入某种境地或深陷某种状态，不能表示接受信件，要用收到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很陷入了深深的忧虑。", "corrected_sentence": "她陷入了深深的忧虑。", "error_description": "“很”误用：“很”不能修饰动词“陷入”，应去掉“很”，说“她陷入了深深的忧虑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的心情被陷入了低谷。", "corrected_sentence": "她的心情陷入了低谷。", "error_description": "“被”误用：“陷入”不能用“被”构成被动式，应说“心情陷入了低谷”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92765, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92765, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92765, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "成效是你做了一件事以后，得到的好结果。", "primary_collocate": null, "pronunciation": "chéng xiào", "ipa": "ʈʂʰɤŋ˧˥ ɕjɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这个办法的成效很明显。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习，成效不错。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的努力终于有了成效。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次学习的成效怎么样？", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这种方法成效很好。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用了新办法，成效很快就出来了。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她锻炼了三个月，已经看到了成效。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "治理污染需要时间，成效不会马上出现。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王坚持跑步，成效慢慢出现了。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个计划没有什么成效。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "做事以后得到的好结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：体重只用于人或动物，办法没有体重，这句话说不通。"}, {"text": "成效", "is_correct": true, "explanation": "成效指做事以后得到的效果，“这个办法的成效很明显”搭配自然。"}, {"text": "相貌", "is_correct": false, "explanation": "语义：相貌指人的外貌，不能用来描述办法。"}, {"text": "颜值", "is_correct": false, "explanation": "语义：颜值指人的外貌好不好看，办法没有颜值，这句话说不通。"}], "explanations": {"体重": "语义：体重只用于人或动物，办法没有体重，这句话说不通。", "成效": "成效指做事以后得到的效果，“这个办法的成效很明显”搭配自然。", "相貌": "语义：相貌指人的外貌，不能用来描述办法。", "颜值": "语义：颜值指人的外貌好不好看，办法没有颜值，这句话说不通。"}, "sentence_index": 0, "correct_answer": "成效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新机器的成效很高。", "explanation": "这里应该用〈效率〉。机器工作的快慢、能力的高低要说效率；成效指做事以后得到的结果。"}, {"text": "这次旅行让我有很多成效。", "explanation": "这里应该用〈收获〉。个人从经历中得到的东西要说收获，成效多指有计划的努力所产生的效果。"}, {"text": "这份合同有很强的法律成效。", "explanation": "这里应该用〈效力〉。合同、法律有没有约束力要说效力，成效不用于这种场合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：温度是冷热的程度，要靠感觉，不能说“看到了温度”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看到”只能接看得见的东西，声音要说“听到”。"}, {"text": "成效", "is_correct": true, "explanation": "成效是锻炼之后得到的效果，“已经看到了成效”搭配自然。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道要用“尝到”或“闻到”，不说“看到了味道”。"}], "explanations": {"温度": "语义：温度是冷热的程度，要靠感觉，不能说“看到了温度”。", "声音": "搭配：“看到”只能接看得见的东西，声音要说“听到”。", "成效": "成效是锻炼之后得到的效果，“已经看到了成效”搭配自然。", "味道": "搭配：味道要用“尝到”或“闻到”，不说“看到了味道”。"}, "sentence_index": 6, "correct_answer": "成效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试我的成效很好。", "explanation": "这里应该用〈成绩〉。考试或比赛的分数要说成绩，成效指做事以后产生的效果。"}, {"text": "这位歌手的成效很高，粉丝遍布各地。", "explanation": "这里应该用〈人气〉。受欢迎的程度要说人气，成效指做事以后得到的结果，不能用来形容歌手受欢迎的程度。"}, {"text": "这部电影的成效有两个小时。", "explanation": "这里应该用〈时长〉。电影、节目的长度要说时长，成效指做事之后的结果，不能用来说时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些措施慢慢有了的成效。", "corrected_sentence": "这些措施慢慢有了成效。", "error_description": "多了一个“的”：“有了成效”是正确说法，“有了的成效”多出了“的”，不符合“有了”带宾语“成效”的结构。错误形式：有了的成效；正确形式：有了成效。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法很成效。", "corrected_sentence": "这个办法很有成效。", "error_description": "“很有成效”是正确说法，“成效”是名词，前面要用动词“有”，不能直接接在“很”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92766, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92766, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92766, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情做过之后所取得的效果。", "primary_collocate": null, "pronunciation": "chéng xiào", "ipa": "ʈʂʰɤŋ˧˥ ɕjɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这项工作取得了很大的成效。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校花了很多钱，可是成效不大。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种药的成效要等一个月才知道。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改了方法以后，我们的成效提高了。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们合作了一年，成效让大家很满意。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做成效太小，我们换个办法吧。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节约用水的成效已经看得出来了。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这次培训的成效很满意。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要坚持下去，一定会有成效。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动的成效比去年好。", "target_word": "成效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事情做过后取得的效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f09b97c-38a8-4ff2-bcb2-0a886cdc7162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或动物活了多久，工作没有年龄。"}, {"text": "成效", "is_correct": true, "explanation": "成效指做事以后得到的效果，“取得很大的成效”搭配自然。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“取得”接的是成绩、成果这类可以获得的东西，身高不能取得。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被取得，“取得很大的成效”说不通。"}], "explanations": {"年龄": "语义：年龄指人或动物活了多久，工作没有年龄。", "成效": "成效指做事以后得到的效果，“取得很大的成效”搭配自然。", "身高": "搭配：“取得”接的是成绩、成果这类可以获得的东西，身高不能取得。", "石头": "语义：石头不能被取得，“取得很大的成效”说不通。"}, "sentence_index": 0, "correct_answer": "成效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的成效很轻。", "explanation": "这里应该用〈重量〉。物体轻重要说重量，成效是做事之后的结果，不能用来形容东西。"}, {"text": "这朵花的成效很鲜艳。", "explanation": "这里应该用〈颜色〉。鲜艳说的是颜色，成效不能用来形容花的样子。"}, {"text": "这条路的成效很远。", "explanation": "这里应该用〈距离〉。两地之间的远近要说距离，成效指做事以后得到的结果，不能用来说路的远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厚度", "is_correct": false, "explanation": "语义：厚度是物体的厚薄，节约用水不涉及厚度，这句话说不通。"}, {"text": "成效", "is_correct": true, "explanation": "成效指做事之后的结果，“看得出来”正适用于这种结果。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重属于人或动物的身体，不能是节约用水的结果。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是冷热的程度，不是能看得出来的成效。"}], "explanations": {"厚度": "语义：厚度是物体的厚薄，节约用水不涉及厚度，这句话说不通。", "成效": "成效指做事之后的结果，“看得出来”正适用于这种结果。", "体重": "语义：体重属于人或动物的身体，不能是节约用水的结果。", "温度": "语义：温度是冷热的程度，不是能看得出来的成效。"}, "sentence_index": 6, "correct_answer": "成效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的成效比上次好。", "explanation": "这里应该用〈味道〉。评价菜好不好吃要说味道，成效指做事的结果，不用于菜的口感。"}, {"text": "这首歌的成效比上次好听。", "explanation": "这里应该用〈声音〉。好听不好听说的是声音，成效不能用来评价歌曲。"}, {"text": "他的成效比以前瘦了。", "explanation": "这里应该用〈体型〉。胖瘦说的是人的体型，成效不能用来说人的胖瘦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些措施已经成效了。", "corrected_sentence": "这些措施已经见到成效了。", "error_description": "“成效”是名词，不能当动词用，前面要加动词“见到”或“取得”。错误形式：成效了；正确形式：见到成效了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种方法很成效。", "corrected_sentence": "这种方法很有成效。", "error_description": "“很有成效”是正确说法，“成效”是名词，前面要用动词“有”，不能直接接在“很”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f13dd8b-44f3-452d-9085-3d547cbca762') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
