INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92767, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电信是用电话和网络把话传到很远的地方。", "primary_collocate": null, "pronunciation": "diàn xìn", "ipa": "tjɛn˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "有了电信，远方的人也能马上说话。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电信让两个城市的人可以通话。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前没有电信，写信要走很多天。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电信把声音传到很远的地方。", "target_word": "电信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代电信发展得很快。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "靠电信，我每天都能和奶奶视频。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有海底电线，电信就不能把声音送过大洋。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电信的发展改变了人们的生活。", "target_word": "电信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有电信，山里的人很难联系外面。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电信使世界变得越来越小。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "電信", "label": "繁体"}, {"form": "电信公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "电信：用电话、网络把声音传到远处的通信手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a80d1613-ad74-4c77-841d-4a5ae0d1a4c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电信", "is_correct": true, "explanation": "“电信”指用电话、网络传递声音的通信手段，句意是“有了它，远方的人才能马上说话”。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视只能播放节目，不能让远方的人马上说话。"}, {"text": "邮局", "is_correct": false, "explanation": "语义：邮局传递的是信件，速度慢，与“马上说话”不符。"}, {"text": "电报", "is_correct": false, "explanation": "语义：电报传递的是文字，不能让远方的人马上说话。"}], "explanations": {"电信": "“电信”指用电话、网络传递声音的通信手段，句意是“有了它，远方的人才能马上说话”。", "电视": "语义：电视只能播放节目，不能让远方的人马上说话。", "邮局": "语义：邮局传递的是信件，速度慢，与“马上说话”不符。", "电报": "语义：电报传递的是文字，不能让远方的人马上说话。"}, "sentence_index": 0, "correct_answer": "电信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电信把信件送到很远的地方。", "explanation": "这里应该用〈邮政〉。电信靠电话和网络传递声音，送信件是邮政的业务。"}, {"text": "电信把货物运送到很远的地方。", "explanation": "这里应该用〈物流〉。电信传递的是声音和信息，运送货物属于物流，不是电信的业务。"}, {"text": "电信把电力送到很远的地方。", "explanation": "这里应该用〈电网〉。电信传递的是声音和信息，输送电力是电网的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电信", "is_correct": true, "explanation": "“电信”指用电话、网络传递声音的通信手段，“没有海底电线，电信就不能把声音送过大洋”说的是这种手段跨洋要靠海底电线。"}, {"text": "铁路", "is_correct": false, "explanation": "语义：铁路不能传递声音，与“把声音送过大洋”不符，句意说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不能把声音送过大洋，句意完全不合。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯只用于照明，不能把声音送过大洋，句意完全不合。"}], "explanations": {"电信": "“电信”指用电话、网络传递声音的通信手段，“没有海底电线，电信就不能把声音送过大洋”说的是这种手段跨洋要靠海底电线。", "铁路": "语义：铁路不能传递声音，与“把声音送过大洋”不符，句意说不通。", "厨房": "语义：厨房不能把声音送过大洋，句意完全不合。", "电灯": "语义：电灯只用于照明，不能把声音送过大洋，句意完全不合。"}, "sentence_index": 6, "correct_answer": "电信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想买一台新的电信，声音特别清楚。", "explanation": "这里应该用〈电话〉。电信指通信业务，不是话机，买设备时应说“电话”。"}, {"text": "这家电信的东西又便宜又新鲜。", "explanation": "这里应该用〈超市〉。电信不卖商品，“东西又便宜又新鲜”说的是超市。"}, {"text": "电信把自来水送到每家每户。", "explanation": "这里应该用〈水管〉。电信传递声音和信息，不能输送自来水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们电信联系远方的亲人。", "corrected_sentence": "我们通过电信联系远方的亲人。", "error_description": "介词遗漏：表示凭借的“电信”前要加“通过”，应说“通过电信联系”，不能说“电信联系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一台电信让两个城市的人可以随时通话。", "corrected_sentence": "电信让两个城市的人可以随时通话。", "error_description": "量词错误：“台”用于机器设备，“电信”是抽象的通信业务，不能说“一台电信”，应直接说“电信让……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
