INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92768, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用电话、电报、网络等传送信息的通信业务。", "primary_collocate": null, "pronunciation": "diàn xìn", "ipa": "tjɛn˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他在电信工作，每天处理客户的电话。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸在电信工作了二十年。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家用的电信服务很稳定，网络很少断。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家电信的服务很好，客服很快就回电话。", "target_word": "电信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电信的工人正在街上修电线。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想去电信办一张新的手机卡。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的网络是电信提供的。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电信的客服告诉我，明天会有人来修网。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电信这个行业每年都有很多新技术。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学毕业后进了电信，负责网络服务。", "target_word": "电信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "電信", "label": "繁体"}, {"form": "电信公司", "label": "复合"}, {"form": "电信业务", "label": "复合"}], "register": "中性", "sense_fingerprint": "电信：提供电话、网络等通信服务的行业或业务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a80d1613-ad74-4c77-841d-4a5ae0d1a4c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电信", "is_correct": true, "explanation": "“电信”指经营电话、网络服务的行业，“在……工作”后接行业名称，句中“处理客户的电话”也与之相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是一种设备，不是可以工作的行业或单位，“在手机工作”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是烹饪的地方，与“处理客户的电话”这类工作不符，句意不合。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”指通话本身或话机，不是工作单位，且与“处理客户的电话”重复。"}], "explanations": {"电信": "“电信”指经营电话、网络服务的行业，“在……工作”后接行业名称，句中“处理客户的电话”也与之相符。", "手机": "语义：手机是一种设备，不是可以工作的行业或单位，“在手机工作”说不通。", "厨房": "语义：厨房是烹饪的地方，与“处理客户的电话”这类工作不符，句意不合。", "电话": "语义：“电话”指通话本身或话机，不是工作单位，且与“处理客户的电话”重复。"}, "sentence_index": 0, "correct_answer": "电信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在电信工作，每天负责送信和包裹。", "explanation": "这里应该用〈邮政〉。电信提供电话、网络等通信服务，送信和包裹属于邮政的业务。"}, {"text": "我买了一部新电信，音质很好。", "explanation": "这里应该用〈电话〉。电信指通信业务，不是话机，买设备时应说“电话”。"}, {"text": "这家餐厅的电信很好，菜也很新鲜。", "explanation": "这里应该用〈服务〉。电信指通信业务，餐厅的好坏应说“服务”，不能说成电信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电信", "is_correct": true, "explanation": "“电信”指提供网络、电话服务的企业，“提供的”说明它是服务的提供方，符合句意。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能提供网络服务，句子说的是网络的提供方。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：网络通常由运营商提供，说“电脑提供的网络”搭配不当。"}, {"text": "水电", "is_correct": false, "explanation": "语义：“水电”指水和电的供应，与网络无关，“水电提供的网络”说不通。"}], "explanations": {"电信": "“电信”指提供网络、电话服务的企业，“提供的”说明它是服务的提供方，符合句意。", "电视": "语义：电视不能提供网络服务，句子说的是网络的提供方。", "电脑": "搭配：网络通常由运营商提供，说“电脑提供的网络”搭配不当。", "水电": "语义：“水电”指水和电的供应，与网络无关，“水电提供的网络”说不通。"}, "sentence_index": 6, "correct_answer": "电信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她大学毕业后进了一条电信，负责网络服务。", "explanation": "这里应该用〈家〉。电信指企业，“条”多用于河流、道路等长条形事物，不能计量企业。"}, {"text": "她大学毕业后进了电信，负责给病人看病。", "explanation": "这里应该用〈医院〉。电信提供电话、网络服务，给病人看病是医院的工作。"}, {"text": "她大学毕业后进了一只电信，负责网络服务。", "explanation": "这里应该用〈家〉。“只”用于动物或成对器官中的一个，不能计量企业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐电信上班，负责网络维护。", "corrected_sentence": "我姐姐在电信上班，负责网络维护。", "error_description": "介词遗漏：表示工作地点的“电信”前要加介词“在”，应说“在电信上班”，不能说“电信上班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司的宽带是一台电信安装的。", "corrected_sentence": "我们公司的宽带是电信安装的。", "error_description": "量词错误：“台”用于机器设备，“电信”指通信企业，不能说“一台电信”，应直接说“电信安装的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
