INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92770, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书刊的一页，也指网页的显示画面。", "primary_collocate": null, "pronunciation": "yè miàn", "ipa": "jɛ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个网站的页面做得很漂亮。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点一下这里，就会打开新的页面。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志的每个页面都有照片。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网速太慢，页面一直打不开。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把页面往下拉，就能看到价格。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个页面上的字太小了。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在设计公司做网站页面。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网速变慢时，刷新一下页面就好了。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸的页面上有大大的标题。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "页面上跳出了一个红色的小窗口。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个页面", "label": "量词"}, {"form": "頁面", "label": "繁体"}, {"form": "页面设计", "label": "复合"}], "register": "中性", "sense_fingerprint": "书刊的一页，也指网页显示出来的画面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6c760cb-57e2-4f62-a33d-bc36fa2b95af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "页面", "is_correct": true, "explanation": "正确：“网站的页面”指网站显示的画面，“做得很漂亮”符合网页设计的说法。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是网站的一部分，“这个网站的房子”说不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能被“做”，也不属于网站，“这个网站的心情做得很漂亮”说不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不是可以制作的东西，“这个网站的时间做得很漂亮”说不通。"}], "explanations": {"页面": "正确：“网站的页面”指网站显示的画面，“做得很漂亮”符合网页设计的说法。", "房子": "语义：房子不是网站的一部分，“这个网站的房子”说不通。", "心情": "搭配：“心情”不能被“做”，也不属于网站，“这个网站的心情做得很漂亮”说不通。", "时间": "搭配：“时间”不是可以制作的东西，“这个网站的时间做得很漂亮”说不通。"}, "sentence_index": 0, "correct_answer": "页面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个网站有三本页面。", "explanation": "这里量词用错。“本”用于书，网站的页面应用“个”计量。"}, {"text": "这块木板的页面很光滑。", "explanation": "这里应该用〈表面〉。页面指书刊的一页或网页的画面，木板的表面应说“表面”。"}, {"text": "他在网上找到一首页面。", "explanation": "这里量词用错。“首”用于诗词、歌曲，页面应用“个”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "页面", "is_correct": true, "explanation": "正确：“做网站页面”是设计网页的常用搭配，符合“他在设计公司”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：网站不能用来做桌子，“做网站桌子”句意不通。"}, {"text": "面条", "is_correct": false, "explanation": "语义：网站不是可以用来做面条的对象，“做网站面条”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“做”需要可以制作的对象，“空气”不能说“做网站空气”，搭配不当。"}], "explanations": {"页面": "正确：“做网站页面”是设计网页的常用搭配，符合“他在设计公司”的语境。", "桌子": "语义：网站不能用来做桌子，“做网站桌子”句意不通。", "面条": "语义：网站不是可以用来做面条的对象，“做网站面条”说不通。", "空气": "搭配：“做”需要可以制作的对象，“空气”不能说“做网站空气”，搭配不当。"}, "sentence_index": 6, "correct_answer": "页面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在地址栏输入页面，就能打开这个网站。", "explanation": "这里应该用〈网址〉。输入的是网址，页面是打开之后显示的内容。"}, {"text": "我的书包里有一座页面。", "explanation": "这里量词用错。“座”用于山、桥等大型建筑，页面应用“个”计量。"}, {"text": "院子里有一棵页面。", "explanation": "这里量词用错。“棵”用于树木等植物，页面不是植物，不能用“棵”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个网站的一本页面打不开。", "corrected_sentence": "这个网站的一个页面打不开。", "error_description": "量词错误：网站的页面应用“个”计量，“一本”用于书，不能用于网页。应改为“一个页面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个网站有三页面打不开。", "corrected_sentence": "这个网站有三个页面打不开。", "error_description": "量词缺失：页面前的数词后要加量词，应说“三个页面”，“三页面”不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b7ac681-9e51-4b44-934e-da4f669e7e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
