INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻深入找出还没有被发现的人才、潜力、真相等。", "primary_collocate": null, "pronunciation": "wā jué", "ipa": "ua˥ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "老师帮我挖掘了自己的潜力。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想挖掘更多有能力的年轻人。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在努力挖掘这件事背后的真相。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要挖掘这座老城的历史故事。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从数据里挖掘出了一个新问题。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把这个小镇的美食文化挖掘出来。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教练很会挖掘球员的优点。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家到农村去挖掘写作的好材料。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在挖掘市场里的新机会。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师能挖掘每个学生的长处。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挖掘了", "label": "完成体"}, {"form": "挖掘着", "label": "持续体"}, {"form": "挖掘过", "label": "经历体"}, {"form": "数据挖掘", "label": "复合词"}], "register": "中性", "sense_fingerprint": "比喻深入找出还没有被发现的人才、潜力、真相等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdadcb77-e6c4-4c9d-9376-79a977628fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”是白白用掉或丢掉，与“老师帮我”的积极语境相反。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发，不能说修剪潜力。"}, {"text": "挖掘", "is_correct": true, "explanation": "“挖掘”在这里指深入发现还没被发现的潜力，与“老师帮我挖掘了自己的潜力”相符。"}, {"text": "埋没", "is_correct": false, "explanation": "语义：“埋没”是让人才或能力不被发现，与“老师帮我”的语境矛盾。"}], "explanations": {"浪费": "语义：“浪费”是白白用掉或丢掉，与“老师帮我”的积极语境相反。", "修剪": "搭配：“修剪”用于枝叶、头发，不能说修剪潜力。", "挖掘": "“挖掘”在这里指深入发现还没被发现的潜力，与“老师帮我挖掘了自己的潜力”相符。", "埋没": "语义：“埋没”是让人才或能力不被发现，与“老师帮我”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "挖掘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶挖掘了一块蛋糕。", "explanation": "这里应该用〈切〉。挖掘指挖开地面或深入发现，切蛋糕要用切。"}, {"text": "学生们挖掘了一张白纸。", "explanation": "这里应该用〈折〉。挖掘指深入发现隐藏的事物，纸张没有可挖掘的内容，折纸要用折。"}, {"text": "警察挖掘了嫌疑人的房间。", "explanation": "这里应该用〈搜查〉。挖掘指深入发现隐藏的事物，搜查房间要用搜查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挑剔", "is_correct": false, "explanation": "搭配：“挑剔”针对缺点和毛病，不能说挑剔球员的优点。"}, {"text": "剥夺", "is_correct": false, "explanation": "语义：“剥夺”是夺去别人的权利，不能用来形容教练对球员优点的态度。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”针对错误和缺点，与“优点”搭配不当。"}, {"text": "挖掘", "is_correct": true, "explanation": "“挖掘”指深入找出球员的优点，与“这位教练很会挖掘球员的优点”相符。"}], "explanations": {"挑剔": "搭配：“挑剔”针对缺点和毛病，不能说挑剔球员的优点。", "剥夺": "语义：“剥夺”是夺去别人的权利，不能用来形容教练对球员优点的态度。", "批评": "搭配：“批评”针对错误和缺点，与“优点”搭配不当。", "挖掘": "“挖掘”指深入找出球员的优点，与“这位教练很会挖掘球员的优点”相符。"}, "sentence_index": 6, "correct_answer": "挖掘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师挖掘了一锅汤。", "explanation": "这里应该用〈煮〉。挖掘指挖开地面或深入发现，煮汤要用煮。"}, {"text": "小明挖掘了那块黑板。", "explanation": "这里应该用〈擦〉。挖掘指挖开地面或深入发现，擦黑板要用擦。"}, {"text": "妈妈在厨房挖掘衣服。", "explanation": "这里应该用〈洗〉。挖掘指深入发现隐藏的事物，洗衣服要用洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位学者挖掘了得很深。", "corrected_sentence": "这位学者挖掘得很深。", "error_description": "“了”与程度补语“得”不能同时出现：应说“挖掘得很深”，不能说“挖掘了得很深”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究员挖掘了出一个隐藏的规律。", "corrected_sentence": "研究员挖掘出了一个隐藏的规律。", "error_description": "语序错误：“了”应放在补语“出”之后，应为“挖掘出了”，不能说“挖掘了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6205d22-05d7-4d8a-99ec-90516221c3f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
