INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不然是说如果不是这样，就会怎么样。", "primary_collocate": null, "pronunciation": "bù rán", "ipa": "pu˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "快走吧，不然我们要迟到了。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要多穿点衣服，不然会感冒的。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早点睡觉，不然明天起不来。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你小声说话，不然会吵醒孩子。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我得马上走，不然就赶不上火车了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把门关好，不然猫会跑出去。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要认真听课，不然考试会很难。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在出发吧，不然路上会堵车。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一定是忘了，不然早就来电话了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带上伞吧，不然下雨会淋湿的。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不然的话", "label": "复合"}], "register": "中性", "sense_fingerprint": "连词，表示假设前面的情况不成立，引出另一种结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不然", "is_correct": true, "explanation": "不然：表示如果不快走，就会出现迟到的结果，引出另一种结果。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果结果，“快走吧”推不出“我们要迟到了”。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”是书面语，与口语催促的语境不协调；语义上也推不出迟到。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，“快走吧”与“迟到”不是先后关系。"}], "explanations": {"不然": "不然：表示如果不快走，就会出现迟到的结果，引出另一种结果。", "所以": "语义：“所以”表示因果结果，“快走吧”推不出“我们要迟到了”。", "故而": "语域：“故而”是书面语，与口语催促的语境不协调；语义上也推不出迟到。", "然后": "语义：“然后”表示先后顺序，“快走吧”与“迟到”不是先后关系。"}, "sentence_index": 0, "correct_answer": "不然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先吃饭，不然去看电影。", "explanation": "这里应该用〈然后〉。不然表示假设不成立时的后果，不能表示先后顺序。"}, {"text": "下雨了，不然我们取消了比赛。", "explanation": "这里应该用〈因此〉。不然表示假设不成立时的后果，不能表示由前一件事导致的结果。"}, {"text": "天冷了，不然我多穿了一件衣服。", "explanation": "这里应该用〈所以〉。不然引出的是不这样做就会出现的后果，表示因果要用所以。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不然", "is_correct": true, "explanation": "不然：表示如果不认真听课，考试就会很难，引出后果。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示由前面的原因得出结果，“认真听课”不会导致“考试很难”，句意不通。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示承接的结果，“认真听课”与“考试很难”之间没有这种承接关系。"}, {"text": "不料", "is_correct": false, "explanation": "语义：“不料”表示出乎意料，句中并没有意外的情况。"}], "explanations": {"不然": "不然：表示如果不认真听课，考试就会很难，引出后果。", "因此": "语义：“因此”表示由前面的原因得出结果，“认真听课”不会导致“考试很难”，句意不通。", "于是": "语义：“于是”表示承接的结果，“认真听课”与“考试很难”之间没有这种承接关系。", "不料": "语义：“不料”表示出乎意料，句中并没有意外的情况。"}, "sentence_index": 6, "correct_answer": "不然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很远，不然风景很好。", "explanation": "这里应该用〈不过〉。不然表示假设不成立时的后果，不能表示转折。"}, {"text": "如果你有空，不然我们就出发。", "explanation": "这里应该用〈那么〉。不然要求前面是不成立的情况，前句是“如果有空”这样的假设时不能用不然。"}, {"text": "他会游泳，不然游得很快。", "explanation": "这里应该用〈而且〉。不然表示不这样就会出现的后果，不能用来补充并列的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们得快点走，不然的会赶不上车。", "corrected_sentence": "我们得快点走，不然会赶不上车。", "error_description": "“不然”后面不能直接接“的”，“的”只能组成“不然的话”。这里应去掉“的”，写成“……，不然会赶不上车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你得多练习，就不然口语会很难提高。", "corrected_sentence": "你得多练习，不然口语会很难提高。", "error_description": "“不然”是连词，前面不能加副词“就”，应直接写成“……，不然口语会很难提高”。这里多加了“就”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
