INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示如果不是前面所说的情况，就会出现另一种结果。", "primary_collocate": null, "pronunciation": "bù rán", "ipa": "pu˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "多亏你提醒我，不然我就忘了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好带着伞，不然衣服都湿了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快点儿吃，不然饭就凉了。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一定有事，不然不会不来。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们得早点去，不然没有座位了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先写完作业，不然不能出去玩。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好学习，不然你以后会后悔的。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上开慢点，不然很危险。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "幸亏朋友帮忙，不然我一个人做不完。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把水杯放好，不然会掉在地上。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不然的话", "label": "复合"}], "register": "中性", "sense_fingerprint": "连词，前面是已有的情况，用不然说明否则会出现的另一种结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不然", "is_correct": true, "explanation": "不然：表示如果没有你的提醒，就会出现“忘了”的结果。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，“多亏你提醒我”与“我就忘了”不是因果关系。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出由原因导致的结果，“多亏你提醒我”不会导致“我就忘了”，句意矛盾。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示递进补充，此处没有补充的理由，“我就忘了”与前句矛盾。"}], "explanations": {"不然": "不然：表示如果没有你的提醒，就会出现“忘了”的结果。", "所以": "语义：“所以”引出结果，“多亏你提醒我”与“我就忘了”不是因果关系。", "因此": "语义：“因此”引出由原因导致的结果，“多亏你提醒我”不会导致“我就忘了”，句意矛盾。", "况且": "语义：“况且”表示递进补充，此处没有补充的理由，“我就忘了”与前句矛盾。"}, "sentence_index": 0, "correct_answer": "不然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我没去，不然我生病了。", "explanation": "这里应该用〈因为〉。不然表示假设不成立时的后果，不能说明原因。"}, {"text": "我感冒了，不然今天没去上班。", "explanation": "这里应该用〈所以〉。不然表示如果不这样就会出现的后果，前句是原因、后句是结果时要用所以。"}, {"text": "他很聪明，不然很努力。", "explanation": "这里应该用〈而且〉。不然表示不这样就会出现的后果，不能用来补充并列的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不然", "is_correct": true, "explanation": "不然：表示如果不好好学习，你以后就会后悔，引出另一种结果。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”是书面语，与口语劝告的语境不符；语义上“好好学习”不导致“后悔”。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”引出承接的动作结果，“好好学习”与“后悔”不是承接关系。"}, {"text": "那么", "is_correct": false, "explanation": "语义：“那么”表示推论或结论，“好好学习”推不出“你以后会后悔”。"}], "explanations": {"不然": "不然：表示如果不好好学习，你以后就会后悔，引出另一种结果。", "故而": "语域：“故而”是书面语，与口语劝告的语境不符；语义上“好好学习”不导致“后悔”。", "于是": "语义：“于是”引出承接的动作结果，“好好学习”与“后悔”不是承接关系。", "那么": "语义：“那么”表示推论或结论，“好好学习”推不出“你以后会后悔”。"}, "sentence_index": 6, "correct_answer": "不然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃完饭，不然去散步。", "explanation": "这里应该用〈然后〉。不然表示假设不成立时的后果，不能表示动作的先后。"}, {"text": "明天天气好，不然我们就去爬山。", "explanation": "这里应该用〈那么〉。不然要求前面是不成立的情况，前句“天气好”是肯定的假设，不能用不然。"}, {"text": "这个菜很辣，不然很好吃。", "explanation": "这里应该用〈不过〉。不然表示假设不成立时的后果，不能表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们得早点出门，不然的会没有座位。", "corrected_sentence": "我们得早点出门，不然会没有座位。", "error_description": "“不然”后面不能直接接“的”，应去掉“的”，写成“……，不然会没有座位”。“的”只能组成“不然的话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "好好复习，就不然考试会不及格。", "corrected_sentence": "好好复习，不然考试会不及格。", "error_description": "“不然”是连词，前面不能加副词“就”，应直接写成“……，不然考试会不及格”。这里多加了“就”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
