INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92775, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搞笑是做出让别人哈哈大笑的事。", "primary_collocate": null, "pronunciation": "gǎo xiào", "ipa": "kau˨˩˦ ɕjau˥˩", "syllable_count": 2, "sentences": [{"text": "他总爱在班上搞笑，同学们笑个不停。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让大家开心，他故意搞笑。", "target_word": "搞笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在晚会上搞笑，观众笑得很大声。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟最爱搞笑，常常学小狗叫。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把帽子戴反了，想搞笑一下。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别在课堂上搞笑，老师会生气的。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们聚会时，他负责搞笑。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个演员靠搞笑出名。", "target_word": "搞笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在台上搞笑，孩子们哈哈大笑。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次搞笑，妈妈都忍不住笑。", "target_word": "搞笑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "搞笑片", "label": "复合"}, {"form": "搞笑视频", "label": "复合"}], "register": "口语", "sense_fingerprint": "故意做出让别人大笑的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搞笑", "is_correct": true, "explanation": "正确：“搞笑”是故意做出逗人笑的事，与“同学们笑个不停”的结果吻合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是正式测验，安静作答不会让同学笑个不停，与句意不符。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：“写作业”是安静的学习活动，不会引起同学大笑，与句意相反。"}, {"text": "抄写", "is_correct": false, "explanation": "语义：“抄写”是安静地誊写文字，不会引起同学大笑，与句末的结果不合。"}], "explanations": {"搞笑": "正确：“搞笑”是故意做出逗人笑的事，与“同学们笑个不停”的结果吻合。", "考试": "语义：“考试”是正式测验，安静作答不会让同学笑个不停，与句意不符。", "写作业": "语义：“写作业”是安静的学习活动，不会引起同学大笑，与句意相反。", "抄写": "语义：“抄写”是安静地誊写文字，不会引起同学大笑，与句末的结果不合。"}, "sentence_index": 0, "correct_answer": "搞笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在背后搞笑，想陷害同事。", "explanation": "这里应该用〈搞鬼〉。搞笑是做出让人发笑的事，陷害同事是暗中做坏事，应说搞鬼。"}, {"text": "工人们聚在厂门口搞笑，还堵住了大门。", "explanation": "这里应该用〈闹事〉。搞笑是逗人发笑，此处是聚众堵门，应说闹事。"}, {"text": "他考试时偷偷搞笑，想看旁边同学的答案。", "explanation": "这里应该用〈作弊〉。搞笑是逗人发笑，偷看答案是作弊，应说作弊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搞笑", "is_correct": true, "explanation": "正确：聚会上负责的事是逗大家开心，“搞笑”与前后文一致。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”令人伤心，与聚会上的欢乐气氛不符，也不是可以负责的事。"}, {"text": "沉默", "is_correct": false, "explanation": "搭配：“负责”后面接的是任务，“沉默”不是可以承担的任务，二者搭配不当。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是需要负责的事，聚会时睡觉与活跃的气氛相悖。"}], "explanations": {"搞笑": "正确：聚会上负责的事是逗大家开心，“搞笑”与前后文一致。", "哭泣": "语义：“哭泣”令人伤心，与聚会上的欢乐气氛不符，也不是可以负责的事。", "沉默": "搭配：“负责”后面接的是任务，“沉默”不是可以承担的任务，二者搭配不当。", "睡觉": "语义：“睡觉”不是需要负责的事，聚会时睡觉与活跃的气氛相悖。"}, "sentence_index": 6, "correct_answer": "搞笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了逃避责任，一直搞笑，编造了一堆假话。", "explanation": "这里应该用〈撒谎〉。搞笑是做出让人发笑的事，编造假话逃避责任应说撒谎。"}, {"text": "为了抗议，他搞笑了整整三天，一口饭也不吃。", "explanation": "这里应该用〈绝食〉。搞笑是逗人发笑，不吃饭以示抗议应说绝食。"}, {"text": "他想走后门，就悄悄给考官搞笑，还塞了一个红包。", "explanation": "这里应该用〈行贿〉。搞笑是逗人发笑，此处是送红包求关照，应说行贿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别在图书馆里没搞笑，大家都在看书呢。", "corrected_sentence": "别在图书馆里搞笑，大家都在看书呢。", "error_description": "“别”本身表示否定的劝阻，后面不能再加“没”，应说“别在图书馆里搞笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位主持人靠搞笑得走红了。", "corrected_sentence": "这位主持人靠搞笑走红了。", "error_description": "“靠搞笑走红”中“搞笑”直接连“走红”，中间不能加“得”，不能说“靠搞笑得走红”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
