INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92776, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做出可笑的言行逗人发笑；滑稽有趣。", "primary_collocate": null, "pronunciation": "gǎo xiào", "ipa": "kau˨˩˦ ɕjau˥˩", "syllable_count": 2, "sentences": [{"text": "这个电影很搞笑，我笑了一晚上。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的表情太搞笑了。", "target_word": "搞笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段视频特别搞笑，我发给了朋友。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话很搞笑，大家都爱听。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一部搞笑的电视剧。", "target_word": "搞笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿着一件搞笑的衣服去上班。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗跑步的样子真搞笑。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢看搞笑节目，放松心情。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的故事一点也不搞笑。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍得太搞笑了，我不想删。", "target_word": "搞笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搞笑片", "label": "复合"}, {"form": "搞笑视频", "label": "复合"}], "register": "口语", "sense_fingerprint": "言行滑稽有趣、逗人发笑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0006e141-8dc4-4804-a206-f5967740a580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搞笑", "is_correct": true, "explanation": "正确：“很搞笑”说明电影好笑，与“我笑了一晚上”一致。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”是难过，与“我笑了一晚上”的说法矛盾。"}, {"text": "恐怖", "is_correct": false, "explanation": "语义：“恐怖”让人害怕，看了一晚上的电影不会是笑个不停，与句意不符。"}, {"text": "威严", "is_correct": false, "explanation": "语域：“威严”偏庄重书面，口语中评价电影不用此词，且与笑的情境不合。"}], "explanations": {"搞笑": "正确：“很搞笑”说明电影好笑，与“我笑了一晚上”一致。", "悲伤": "语义：“悲伤”是难过，与“我笑了一晚上”的说法矛盾。", "恐怖": "语义：“恐怖”让人害怕，看了一晚上的电影不会是笑个不停，与句意不符。", "威严": "语域：“威严”偏庄重书面，口语中评价电影不用此词，且与笑的情境不合。"}, "sentence_index": 0, "correct_answer": "搞笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个消息让她心里很搞笑，半天说不出话。", "explanation": "这里应该用〈悲伤〉。搞笑形容引人发笑的事，此处是听到坏消息后心里难过，应说悲伤。"}, {"text": "考试前，他心里很搞笑，手心直冒汗。", "explanation": "这里应该用〈紧张〉。搞笑形容引人发笑的事，此处是考试前手心出汗，应说紧张。"}, {"text": "这座大桥很搞笑，人们都站在桥边惊叹。", "explanation": "这里应该用〈壮观〉。搞笑形容引人发笑的事，此处是人们惊叹桥的宏伟，应说壮观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搞笑", "is_correct": true, "explanation": "正确：“真搞笑”评价跑步的样子很可笑，与句意一致。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，说样子真高大描写的是体型，不是动作的可笑。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容地方或场面没有人气，与狗跑步的样子无关。"}, {"text": "晴朗", "is_correct": false, "explanation": "搭配：“晴朗”形容天气或心情，不能用来评价动物跑步的样子。"}], "explanations": {"搞笑": "正确：“真搞笑”评价跑步的样子很可笑，与句意一致。", "高大": "体貌：“高大”形容身材，说样子真高大描写的是体型，不是动作的可笑。", "冷清": "语义：“冷清”形容地方或场面没有人气，与狗跑步的样子无关。", "晴朗": "搭配：“晴朗”形容天气或心情，不能用来评价动物跑步的样子。"}, "sentence_index": 6, "correct_answer": "搞笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜深人静，走廊里的脚步声很搞笑，让人不敢出门。", "explanation": "这里应该用〈恐怖〉。搞笑形容引人发笑的事，此处是夜里的脚步声让人害怕，应说恐怖。"}, {"text": "这次事故的伤亡很搞笑，大家都很焦虑。", "explanation": "这里应该用〈严重〉。搞笑形容引人发笑的事，伤亡和焦虑应说严重。"}, {"text": "这座废弃的工厂很搞笑，没人知道里面藏着什么。", "explanation": "这里应该用〈神秘〉。搞笑形容引人发笑的事，此处是废弃工厂让人好奇，应说神秘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部动画片被搞笑，孩子们看得很开心。", "corrected_sentence": "这部动画片很搞笑，孩子们看得很开心。", "error_description": "“搞笑”是形容词，表示“让人发笑”，不能用“被”构成被动句，应说“很搞笑”，不能说“被搞笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目一点也很搞笑，我看得很无聊。", "corrected_sentence": "这个节目一点也不搞笑，我看得很无聊。", "error_description": "“一点也”要与否定词“不”搭配，应说“一点也不搞笑”，不能用“很”说“一点也很搞笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f74798a-5a73-4add-9ed7-fed78d2d8d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "反义：“反对”与“拥护”意思相反，指不赞成甚至加以抵制。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”是日常活动，与“拥护”的赞成之义不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”是一种活动，与“拥护”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”是休息的行为，与“拥护”没有反义关系。"}], "correct_answer": "反对", "explanations": {"反对": "反义：“反对”与“拥护”意思相反，指不赞成甚至加以抵制。", "散步": "无关：“散步”是日常活动，与“拥护”的赞成之义不构成反义。", "唱歌": "无关：“唱歌”是一种活动，与“拥护”没有反义关系。", "睡觉": "无关：“睡觉”是休息的行为，与“拥护”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "反义：“反对”与“拥护”意思相反，指不赞成甚至加以抵制。"}, {"text": "跑步", "is_correct": false, "explanation": "无关：“跑步”是体育活动，与“拥护”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：“游泳”是体育活动，与“拥护”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "无关：“画画”是一种爱好，与“拥护”没有反义关系。"}], "correct_answer": "反对", "explanations": {"反对": "反义：“反对”与“拥护”意思相反，指不赞成甚至加以抵制。", "跑步": "无关：“跑步”是体育活动，与“拥护”没有反义关系。", "游泳": "无关：“游泳”是体育活动，与“拥护”没有反义关系。", "画画": "无关：“画画”是一种爱好，与“拥护”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人或主张表示赞成并全力支持。", "primary_collocate": null, "pronunciation": "yōng hù", "ipa": "joŋ˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "大家都拥护这个好办法。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民拥护政府的新政策。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一致拥护他当班长。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都拥护这个决定。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人很拥护新来的村长。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数人拥护这项规定。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拥护过这个计划，现在也一样。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们拥护公司提出的办法。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学都举手拥护他的意见。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不拥护这种做法，因为不公平。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥护了", "label": "体标"}, {"form": "拥护过", "label": "体标"}, {"form": "拥护者", "label": "复合"}, {"form": "擁護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或主张表示赞成并全力支持", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11634477-b3a7-490b-8534-8c42b7d88671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拥护", "is_correct": true, "explanation": "正确：“拥护”表示赞成并全力支持，与“好办法”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“吃办法”搭配不当。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲等，办法不能唱，句意不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”含有讥讽之意，与“好办法”的褒义相矛盾。"}], "explanations": {"拥护": "正确：“拥护”表示赞成并全力支持，与“好办法”相符。", "吃": "搭配：“吃”的宾语应是食物，“吃办法”搭配不当。", "唱": "语义：“唱”的对象是歌曲等，办法不能唱，句意不通。", "嘲笑": "语义：“嘲笑”含有讥讽之意，与“好办法”的褒义相矛盾。"}, "sentence_index": 0, "correct_answer": "拥护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都拥护这道菜。", "explanation": "这里应该用〈喜欢〉。拥护用于人或主张，表示公开赞成；对食物的好感要用“喜欢”。"}, {"text": "我们都拥护这首歌。", "explanation": "这里应该用〈赞美〉。拥护用于人或主张；对歌曲的称赞要用“赞美”。"}, {"text": "我们都拥护这盏灯。", "explanation": "这里应该用〈喜爱〉。拥护用于人或主张；对物品的喜爱要用“喜爱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥护", "is_correct": true, "explanation": "正确：“拥护过”表示曾经赞成并支持，与“这个计划”及“现在也一样”相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，“喝计划”搭配不当。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，计划不能被喂，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是可以清洗的东西，计划不能洗，句意不通。"}], "explanations": {"拥护": "正确：“拥护过”表示曾经赞成并支持，与“这个计划”及“现在也一样”相符。", "喝": "搭配：“喝”的宾语应是饮品，“喝计划”搭配不当。", "喂": "语义：“喂”的对象是人或动物，计划不能被喂，句意不通。", "洗": "语义：“洗”的对象是可以清洗的东西，计划不能洗，句意不通。"}, "sentence_index": 6, "correct_answer": "拥护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们都拥护这张桌子，天天用它写作业。", "explanation": "这里应该用〈喜欢〉。拥护用于人或主张，表示公开赞成；对桌子的好感只能说“喜欢”。"}, {"text": "同学们都拥护这支钢笔，每天都带着它。", "explanation": "这里应该用〈喜爱〉。拥护用于人或主张，表示公开赞成；对钢笔的喜爱要用“喜爱”。"}, {"text": "大家都拥护这把椅子，常常坐在上面。", "explanation": "这里应该用〈中意〉。拥护用于人或主张，表示公开赞成；对椅子这类物品的喜好应用“中意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都拥护这只主张。", "corrected_sentence": "大家都拥护这个主张。", "error_description": "错误形式：“拥护这只主张”。正确形式：“拥护这个主张”。“主张”前应用量词“个”，“只”多用于动物、手等，不能修饰“主张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们从不拥护过这个决定。", "corrected_sentence": "他们从没拥护过这个决定。", "error_description": "错误形式：“从不拥护过这个决定”。正确形式：“从没拥护过这个决定”。表示“从未有过”的经历要用否定词“没”，“不”不能与表示经历的“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f598e8ae-1636-45ab-81a3-f378b9be4510') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
