INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92782, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "团体或国家因内部不和而分开，分成几派或几个部分。", "primary_collocate": null, "pronunciation": "fēn liè", "ipa": "fən˥˥ lie˥˩", "syllable_count": 2, "sentences": [{"text": "因为意见不同，这个小组分裂了。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的人为了钱，分裂成了两派。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家后来分裂成了两个国家。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队内部有矛盾，差点分裂。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政党因为争权，分裂成了两个党。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家要团结，不要让班级分裂。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板走后，公司的人分裂成了好几派。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个乐队吵了很久，最后还是分裂了。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怕家庭分裂，所以不愿意吵架。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体分裂以后，很多人都离开了。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分裂了", "label": "体标（了）"}, {"form": "分裂过", "label": "体标（过）"}, {"form": "分裂主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "团体、国家因内部不和而分成几部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5582003f-0fa5-4559-bf80-a34613800f6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分裂", "is_correct": true, "explanation": "正确答案：分裂（fēn liè），指团体因内部不和而分开。"}, {"text": "分类", "is_correct": false, "explanation": "fēn lèi（第四声）与 fēn liè 只有第二个音节的韵母不同（-ei 与 -ie），意思是按类别分开。"}, {"text": "分界", "is_correct": false, "explanation": "fēn jiè（第四声）与 fēn liè 只有第二个音节的声母不同（j 与 l），意思是划分界限。"}, {"text": "分离", "is_correct": false, "explanation": "fēn lí（第二声）与 fēn liè 的声调和韵母都不同，意思是使彼此分开、不再相连。"}], "explanations": {"分裂": "正确答案：分裂（fēn liè），指团体因内部不和而分开。", "分类": "fēn lèi（第四声）与 fēn liè 只有第二个音节的韵母不同（-ei 与 -ie），意思是按类别分开。", "分界": "fēn jiè（第四声）与 fēn liè 只有第二个音节的声母不同（j 与 l），意思是划分界限。", "分离": "fēn lí（第二声）与 fēn liè 的声调和韵母都不同，意思是使彼此分开、不再相连。"}, "sentence_index": null, "correct_answer": "分裂"}, "level_3": {"options": [{"text": "分裂", "is_correct": true, "explanation": "正确答案：分裂，指团体因意见不同而分成几部分。"}, {"text": "团结", "is_correct": false, "explanation": "语义：“因为意见不同”与“团结”的意思相反，这里不能说“团结了”。"}, {"text": "生病", "is_correct": false, "explanation": "语义：小组不会“生病”，这里不能用“生病”。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”多用于火、灯等，不能用于“小组”。"}], "explanations": {"分裂": "正确答案：分裂，指团体因意见不同而分成几部分。", "团结": "语义：“因为意见不同”与“团结”的意思相反，这里不能说“团结了”。", "生病": "语义：小组不会“生病”，这里不能用“生病”。", "熄灭": "搭配：“熄灭”多用于火、灯等，不能用于“小组”。"}, "sentence_index": 0, "correct_answer": "分裂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个社团因为没有人参加活动，最后分裂了。", "explanation": "这里应该用〈解散〉。分裂指团体因内部不和而分成几派；社团因无人参加而撤销要用解散，两者的原因不同。"}, {"text": "这对恋人因为误会分裂了。", "explanation": "这里应该用〈分手〉。分裂指团体或组织内部分开，两个人的感情破裂要用分手。"}, {"text": "这两家小公司分裂成了一家大公司。", "explanation": "这里应该用〈合并〉。分裂是一分为多，两家公司合成一家要用合并，两者方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分裂", "is_correct": true, "explanation": "正确答案：分裂，指团体因内部不和而分开，形成几派。"}, {"text": "统一", "is_correct": false, "explanation": "语义：“统一”是合为一致，与“成了好几派”的结果相反。"}, {"text": "合并", "is_correct": false, "explanation": "语义：合并是合为一体，与“成了好几派”的结果相反。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化”多用于冰雪，不能用于“公司的人”。"}], "explanations": {"分裂": "正确答案：分裂，指团体因内部不和而分开，形成几派。", "统一": "语义：“统一”是合为一致，与“成了好几派”的结果相反。", "合并": "语义：合并是合为一体，与“成了好几派”的结果相反。", "融化": "搭配：“融化”多用于冰雪，不能用于“公司的人”。"}, "sentence_index": 6, "correct_answer": "分裂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "聚会结束后，大家慢慢分裂了。", "explanation": "这里应该用〈散开〉。分裂指团体因意见不合而分成几派；聚会后人群各自走开要用散开，没有内部矛盾。"}, {"text": "公司的规模分裂了。", "explanation": "这里应该用〈扩大〉。分裂表示分开，规模变大要用扩大。"}, {"text": "几个小组分裂在一起，形成了一个大组。", "explanation": "这里应该用〈结合〉。分裂是分开，几个小组凑在一起要用结合，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "由于路线不同，这支探险队最后分裂了成两支队伍。", "corrected_sentence": "由于路线不同，这支探险队最后分裂成了两支队伍。", "error_description": "错误：“分裂了成两支队伍”；正确：“分裂成了两支队伍”。“了”应放在结果补语“成”之后，不能插在“分裂”和“成”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团体去年分裂了过一次，后来又重新组建了。", "corrected_sentence": "这个团体去年分裂过一次，后来又重新组建了。", "error_description": "错误：“分裂了过一次”；正确：“分裂过一次”。“过”是紧跟动词的体标，“了”不能插在“分裂”和“过”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d88747a-ad7c-4c30-8cd2-ef8e3ad8f667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
