INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92785, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地区经济是一个地方做买卖、挣钱的情况。", "primary_collocate": null, "pronunciation": "dì qū jīng jì", "ipa": "ti˥˩ tɕʰy˥ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "这里的地区经济不太好，很多人去外地打工。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地区经济好的地方，商店也多。", "target_word": "地区经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了解南方的地区经济怎么样。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年我们这儿的地区经济越来越好。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂关门以后，地区经济一下子变差了。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地游客多了，地区经济也好起来了。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新市场开了，让地区经济活跃起来。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地区经济主要靠种地和卖水果。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地区经济不好，买东西的人就少。", "target_word": "地区经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写了一篇关于地区经济的文章。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，指一个地方做买卖、挣钱的好坏情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地区经济", "is_correct": true, "explanation": "地区经济：一个地方做买卖、挣钱的情况，“不太好”说明挣钱的情况差，所以很多人外出打工。"}, {"text": "书法", "is_correct": false, "explanation": "语义：“书法”不是挣钱的情况，“书法不太好”与外出打工没有关系。"}, {"text": "字体", "is_correct": false, "explanation": "语义：“字体”指字的形状与风格，与挣钱的情况无关，句子推不出“很多人去外地打工”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不涉及挣钱状况，句子推不出“很多人去外地打工”。"}], "explanations": {"地区经济": "地区经济：一个地方做买卖、挣钱的情况，“不太好”说明挣钱的情况差，所以很多人外出打工。", "书法": "语义：“书法”不是挣钱的情况，“书法不太好”与外出打工没有关系。", "字体": "语义：“字体”指字的形状与风格，与挣钱的情况无关，句子推不出“很多人去外地打工”。", "歌曲": "语义：“歌曲”不涉及挣钱状况，句子推不出“很多人去外地打工”。"}, "sentence_index": 0, "correct_answer": "地区经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的地区经济很高兴。", "explanation": "这里应该用〈居民〉。地区经济指经济状况，不能用“高兴”来形容；说人高兴应该用居民、大家。"}, {"text": "这几年我们这儿的地区经济越来越多。", "explanation": "这里应该用〈人口〉。地区经济说的是经济状况，不能用“越来越多”来形容。"}, {"text": "这家地区经济越来越受欢迎。", "explanation": "这里应该用〈餐馆〉。地区经济是一个地方的经济情况，不能指一家店受欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地区经济", "is_correct": true, "explanation": "地区经济：一个地方做买卖、挣钱的情况，市场开了，经济就会活跃起来。"}, {"text": "空调", "is_correct": false, "explanation": "语义：“空调”是电器，不能“活跃起来”，与句意不符。"}, {"text": "血压", "is_correct": false, "explanation": "搭配：“活跃”不能用于“血压”，搭配不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，“活跃起来”与它的意义不符。"}], "explanations": {"地区经济": "地区经济：一个地方做买卖、挣钱的情况，市场开了，经济就会活跃起来。", "空调": "语义：“空调”是电器，不能“活跃起来”，与句意不符。", "血压": "搭配：“活跃”不能用于“血压”，搭配不成立。", "冰箱": "语义：“冰箱”是家电，“活跃起来”与它的意义不符。"}, "sentence_index": 6, "correct_answer": "地区经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的生意最近很忙，地区经济也很忙。", "explanation": "这里应该用〈市场〉。地区经济指经济情况，不能说它“很忙”；形容买卖热闹应说市场很忙。"}, {"text": "这家地区经济的菜很好吃。", "explanation": "这里应该用〈餐馆〉。地区经济是地方的经济情况，不能指一家店的菜好吃。"}, {"text": "我这个月的地区经济很少。", "explanation": "这里应该用〈收入〉。地区经济指地方的经济状况，不能指个人这个月的收入多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校关门以后，地区经济了一下子变差了。", "corrected_sentence": "学校关门以后，地区经济一下子变差了。", "error_description": "“了”用错位置：它直接加在主语“地区经济”后面，使“地区经济”后接“了”，结构不通。正确写法是“地区经济一下子变差了”，“了”放在句末的动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新政策实施后，我们的地区经济的慢慢活跃起来了。", "corrected_sentence": "新政策实施后，我们的地区经济慢慢活跃起来了。", "error_description": "“的”不能放在“地区经济”与状语“慢慢”之间，这里应直接写成“地区经济慢慢活跃起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
