INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一地区范围内的经济活动及其发展状况。", "primary_collocate": null, "pronunciation": "dì qū jīng jì", "ipa": "ti˥˩ tɕʰy˥ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "这个地区经济发展得很快。", "target_word": "地区经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "西部地区经济比沿海慢一些。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想帮助西部地区经济发展。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新修的铁路让沿线地区经济变好了。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的地区经济主要靠旅游。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了东北地区经济的变化。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地区经济好了，年轻人就不用去外地工作。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年地区经济增长了百分之八。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河对周围地区经济很重要。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新公路对当地的地区经济很有帮助。", "target_word": "地区经济", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词，指一个地区的经济活动和发展状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd2a1ec9-6f0b-449f-8068-f924ac67d7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地区经济", "is_correct": true, "explanation": "地区经济：某一地区范围内的经济活动及其发展状况，可以作“发展”的主语，句意通顺。"}, {"text": "个人收入", "is_correct": false, "explanation": "搭配：“发展”多用于经济、产业等，个人收入一般说“增长”，不说“发展得很快”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气可以“变化”，但不会“发展”，与句意不符。"}, {"text": "地理", "is_correct": false, "explanation": "语义：“地理”指地形、地貌等，不能说“发展得很快”。"}], "explanations": {"地区经济": "地区经济：某一地区范围内的经济活动及其发展状况，可以作“发展”的主语，句意通顺。", "个人收入": "搭配：“发展”多用于经济、产业等，个人收入一般说“增长”，不说“发展得很快”。", "天气": "语义：天气可以“变化”，但不会“发展”，与句意不符。", "地理": "语义：“地理”指地形、地貌等，不能说“发展得很快”。"}, "sentence_index": 0, "correct_answer": "地区经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新修的铁路让全国的地区经济变好了。", "explanation": "这里应该用〈国民经济〉。地区经济指某一地区范围内的经济，说全国的整体经济要用国民经济。"}, {"text": "这几年我家的地区经济提高了很多。", "explanation": "这里应该用〈收入〉。地区经济指一个地区的经济状况，不能指一个家庭的收入。"}, {"text": "这个地区经济很美。", "explanation": "这里应该用〈风景〉。地区经济指经济状况，不能用“很美”来形容，形容好看要说风景或环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地区经济", "is_correct": true, "explanation": "地区经济：一个地区的经济状况，“好了”说明经济变好，年轻人就不用外出工作。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能用“好了”来说状况，与后句的就业语境也无关。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”不是经济状况，“眼睛好了”与“不用去外地工作”之间没有关系。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”与年轻人外出工作的语境不相关，推不出就业的结果。"}], "explanations": {"地区经济": "地区经济：一个地区的经济状况，“好了”说明经济变好，年轻人就不用外出工作。", "体温": "搭配：“体温”不能用“好了”来说状况，与后句的就业语境也无关。", "眼睛": "语义：“眼睛”不是经济状况，“眼睛好了”与“不用去外地工作”之间没有关系。", "作业": "语义：“作业”与年轻人外出工作的语境不相关，推不出就业的结果。"}, "sentence_index": 6, "correct_answer": "地区经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他父母在家里负责管理地区经济。", "explanation": "这里应该用〈家庭经济〉。地区经济指一个地区的经济，管理一个家庭的开支要用家庭经济。"}, {"text": "他的地区经济提高了很多。", "explanation": "这里应该用〈成绩〉。地区经济指地区的经济状况，不能指个人的学习成绩。"}, {"text": "政府的地区经济用来建新学校。", "explanation": "这里应该用〈资金〉。地区经济指经济状况，不是可以用来花的钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的地区经济的变好了。", "corrected_sentence": "这个城市的地区经济变好了。", "error_description": "“地区经济”后面不能直接加“的”接谓语，“的”只用于名词修饰语之后。这里多加了“的”，应写成“这个城市的地区经济变好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沿线的地区经济好起去了。", "corrected_sentence": "沿线的地区经济好起来了。", "error_description": "“好起来”表示变好的趋势，“起去”不能这样用，应写成“好起来”。这里把“来”错写成“去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f9bab58-da2f-4ece-9e35-f06ef4287688') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92787, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陈旧", "is_correct": false, "explanation": "与“天然”没有反义关系，二者意义无对立。"}, {"text": "人工", "is_correct": true, "explanation": "“人工”指人为制造，与“天然”的非人为义正相反。"}, {"text": "严肃", "is_correct": false, "explanation": "与“天然”没有反义关系，不表示相反的意思。"}, {"text": "美丽", "is_correct": false, "explanation": "与“天然”没有反义关系，二者意义无对立。"}], "correct_answer": "人工", "explanations": {"陈旧": "与“天然”没有反义关系，二者意义无对立。", "人工": "“人工”指人为制造，与“天然”的非人为义正相反。", "严肃": "与“天然”没有反义关系，不表示相反的意思。", "美丽": "与“天然”没有反义关系，二者意义无对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92787, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快乐", "is_correct": false, "explanation": "与“天然”没有反义关系，二者意义无对立。"}, {"text": "人工", "is_correct": true, "explanation": "“人工”指人为制造，与“天然”的非人为义正相反。"}, {"text": "吵闹", "is_correct": false, "explanation": "与“天然”没有反义关系，不表示相反的意思。"}, {"text": "宽阔", "is_correct": false, "explanation": "与“天然”没有反义关系，二者意义无对立。"}], "correct_answer": "人工", "explanations": {"快乐": "与“天然”没有反义关系，二者意义无对立。", "人工": "“人工”指人为制造，与“天然”的非人为义正相反。", "吵闹": "与“天然”没有反义关系，不表示相反的意思。", "宽阔": "与“天然”没有反义关系，二者意义无对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92787, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是人做的，本来就有的。", "primary_collocate": null, "pronunciation": "tiān rán", "ipa": "tʰiɛn˥ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "她的卷发是天然的。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的美景都是天然的。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片森林是天然的，没有人种过树。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在河边捡到一块天然的鹅卵石。", "target_word": "天然", "complexity_tier": "T3", "furigana": "tiān rán", "sentence_source": "generated"}, {"text": "这种颜色是天然的，不是染的。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗宝石的颜色是天然的，没有经过处理。", "target_word": "天然", "complexity_tier": "T3", "furigana": "tiān rán", "sentence_source": "generated"}, {"text": "洞里有天然的冰。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些石头的花纹是天然的。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护天然的树林。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天然的东西不一定都好。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然气", "label": "复合"}], "register": "中性", "sense_fingerprint": "不是人做的，本来就有的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材或建筑的体量，不用于描述头发。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音或不吵闹，与“卷发”不相干，句子不通。"}, {"text": "天然", "is_correct": true, "explanation": "“天然”指本来就有、非人为，说明卷发不是烫出来的，与句意相符。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，只能形容人，不能用于描述卷发。"}], "explanations": {"高大": "体貌：“高大”形容人的身材或建筑的体量，不用于描述头发。", "安静": "语义：“安静”指没有声音或不吵闹，与“卷发”不相干，句子不通。", "天然": "“天然”指本来就有、非人为，说明卷发不是烫出来的，与句意相符。", "沉默": "语义：“沉默”指不说话，只能形容人，不能用于描述卷发。"}, "sentence_index": 0, "correct_answer": "天然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们天然了这间房子。", "explanation": "这里不能用〈天然〉作动词。天然只作形容词，不能表示“使……天然”的动作，应说〈改造〉。"}, {"text": "这颗珠子是天然的，是工厂做的。", "explanation": "这里应该用〈人工〉。天然指非人为，珠子是工厂做的，应说“人工的”，不能用“天然的”。"}, {"text": "我天然遇到了一位老朋友。", "explanation": "这里应该用〈偶然〉。天然不修饰“遇到”这样的偶发事件，应说“偶然遇到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雄伟", "is_correct": false, "explanation": "语义：“雄伟”形容建筑或山河的气势，不能用来描述洞里的冰。"}, {"text": "天然", "is_correct": true, "explanation": "“天然”指本来就有、非人为，与“洞里的冰”的语境相符。"}, {"text": "高挑", "is_correct": false, "explanation": "体貌：“高挑”形容人的身材，不能用来描述冰。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来描述洞里的冰。"}], "explanations": {"雄伟": "语义：“雄伟”形容建筑或山河的气势，不能用来描述洞里的冰。", "天然": "“天然”指本来就有、非人为，与“洞里的冰”的语境相符。", "高挑": "体貌：“高挑”形容人的身材，不能用来描述冰。", "聪明": "语义：“聪明”形容人的智力，不能用来描述洞里的冰。"}, "sentence_index": 6, "correct_answer": "天然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器是天然的，所以很好用。", "explanation": "这里不能用〈天然〉修饰“机器”。天然指非人为，机器是人造的，应说〈人造〉。"}, {"text": "这些东西的天然很重要。", "explanation": "这里不能用〈天然〉作名词。天然是形容词，应说“这些东西是不是天然的很重要”。"}, {"text": "这片田地是天然的，是农民一点点开垦出来的。", "explanation": "前后矛盾：天然指非人为，田地经农民开垦，应说〈人工〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的头发是天然。", "corrected_sentence": "她的头发是天然的。", "error_description": "错误形式：她的头发是天然；正确形式：她的头发是天然的。“天然”作谓语时后面要加“的”，省略后句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山谷里有天然地湖。", "corrected_sentence": "山谷里有天然的湖。", "error_description": "错误形式：山谷里有天然地湖；正确形式：山谷里有天然的湖。“天然”作定语修饰名词“湖”时用“的”，“地”只用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92788, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": false, "explanation": "与“天然”没有反义关系，二者意义无对立。"}, {"text": "人工", "is_correct": true, "explanation": "“人工”指人为制造，与“天然”的非人为义正相反。"}, {"text": "美丽", "is_correct": false, "explanation": "与“天然”没有反义关系，不表示相反的意思。"}, {"text": "宽阔", "is_correct": false, "explanation": "与“天然”没有反义关系，二者意义无对立。"}], "correct_answer": "人工", "explanations": {"安静": "与“天然”没有反义关系，二者意义无对立。", "人工": "“人工”指人为制造，与“天然”的非人为义正相反。", "美丽": "与“天然”没有反义关系，不表示相反的意思。", "宽阔": "与“天然”没有反义关系，二者意义无对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92788, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快乐", "is_correct": false, "explanation": "与“天然”没有反义关系，二者意义无对立。"}, {"text": "人工", "is_correct": true, "explanation": "“人工”指人为制造，与“天然”的非人为义正相反。"}, {"text": "吵闹", "is_correct": false, "explanation": "与“天然”没有反义关系，不表示相反的意思。"}, {"text": "严肃", "is_correct": false, "explanation": "与“天然”没有反义关系，二者意义无对立。"}], "correct_answer": "人工", "explanations": {"快乐": "与“天然”没有反义关系，二者意义无对立。", "人工": "“人工”指人为制造，与“天然”的非人为义正相反。", "吵闹": "与“天然”没有反义关系，不表示相反的意思。", "严肃": "与“天然”没有反义关系，二者意义无对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92788, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自然存在的，不是人为的。", "primary_collocate": null, "pronunciation": "tiān rán", "ipa": "tʰiɛn˥ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "这个湖是天然的，不是人做的。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天然的珍珠很贵。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里有很多天然的温泉。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢用天然的材料做衣服。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个洞是天然形成的。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的天然环境很好。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种果汁是天然的，不加糖，味道很好。", "target_word": "天然", "complexity_tier": "T3", "furigana": "tiān rán", "sentence_source": "generated"}, {"text": "河边有一座天然的石桥。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢吃天然食品，少吃加工食品。", "target_word": "天然", "complexity_tier": "T3", "furigana": "tiān rán", "sentence_source": "generated"}, {"text": "这片天然草地没有人管理。", "target_word": "天然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然气", "label": "复合"}], "register": "中性", "sense_fingerprint": "自然形成、非人工制造的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ca222-7212-4bdc-9eea-f9ef5dd8b36e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精致", "is_correct": false, "explanation": "语义：“精致”指做工讲究，与“不是人做的”相矛盾，不能用来描述湖。"}, {"text": "天然", "is_correct": true, "explanation": "“天然”指自然存在、不是人为，与“不是人做的”相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或体量，不用于描述湖泊。"}, {"text": "奢侈", "is_correct": false, "explanation": "语义：“奢侈”指花费很多，与“不是人做的”的语境不符，湖不能是奢侈的。"}], "explanations": {"精致": "语义：“精致”指做工讲究，与“不是人做的”相矛盾，不能用来描述湖。", "天然": "“天然”指自然存在、不是人为，与“不是人做的”相符。", "高大": "体貌：“高大”形容身材或体量，不用于描述湖泊。", "奢侈": "语义：“奢侈”指花费很多，与“不是人做的”的语境不符，湖不能是奢侈的。"}, "sentence_index": 0, "correct_answer": "天然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他天然地笑了一下。", "explanation": "这里应该用〈自然〉。天然指本来就有、非人为，修饰动作表示自然而然要用“自然”。"}, {"text": "这座桥是天然的，是工人一年修好的。", "explanation": "前后矛盾：天然指非人为，不能和“工人修好”同时出现，这里应说“人工的”。"}, {"text": "我天然遇到了一位老朋友。", "explanation": "这里应该用〈偶然〉。天然不修饰“遇到”这样的偶发事件，应说“偶然遇到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雄伟", "is_correct": false, "explanation": "语义：“雄伟”形容建筑或山河的气势，不能用来描述果汁。"}, {"text": "天然", "is_correct": true, "explanation": "“天然”指不加人工、自然生长，与“不加糖”的语境相符。"}, {"text": "高挑", "is_correct": false, "explanation": "体貌：“高挑”形容人的身材，不能用来描述果汁。"}, {"text": "秘密", "is_correct": false, "explanation": "语义：“秘密”指不让人知道的，不能用来描述果汁的性质。"}], "explanations": {"雄伟": "语义：“雄伟”形容建筑或山河的气势，不能用来描述果汁。", "天然": "“天然”指不加人工、自然生长，与“不加糖”的语境相符。", "高挑": "体貌：“高挑”形容人的身材，不能用来描述果汁。", "秘密": "语义：“秘密”指不让人知道的，不能用来描述果汁的性质。"}, "sentence_index": 6, "correct_answer": "天然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是天然的。", "explanation": "这里不能用〈天然〉修饰“电脑”。天然指非人为，电脑是人造的，应说〈人造〉。"}, {"text": "我们天然了这片草地。", "explanation": "这里不能用〈天然〉作动词。天然只作形容词，不能表示“使……天然”的动作，应说〈保护〉。"}, {"text": "我们天然地完成了作业。", "explanation": "这里不能用〈天然〉。天然指非人为，作业是人做的，应说“顺利地完成了作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个湖是天然，没有人工干预。", "corrected_sentence": "这个湖是天然的，没有人工干预。", "error_description": "错误形式：这个湖是天然，没有人工干预；正确形式：这个湖是天然的，没有人工干预。“天然”作谓语时后面要加“的”，省略后句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢这片天然地草地。", "corrected_sentence": "我喜欢这片天然草地。", "error_description": "错误形式：我喜欢这片天然地草地；正确形式：我喜欢这片天然草地。“天然”修饰名词“草地”时直接放在名词前，不加“地”；“地”只用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3bd1675-72ce-453b-947b-21e1b4733c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开通", "is_correct": true, "explanation": "正确：“开通”指让道路重新可以通行，与“封锁”相对，是反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "无关：“修建”指建造，与“封锁”不构成反义。"}, {"text": "观看", "is_correct": false, "explanation": "无关：“观看”指看，与“封锁”不构成反义。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”指把东西归类摆好，与“封锁”不构成反义。"}], "correct_answer": "开通", "explanations": {"开通": "正确：“开通”指让道路重新可以通行，与“封锁”相对，是反义关系。", "修建": "无关：“修建”指建造，与“封锁”不构成反义。", "观看": "无关：“观看”指看，与“封锁”不构成反义。", "整理": "无关：“整理”指把东西归类摆好，与“封锁”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
