INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "封锁是把路堵住，谁也过不去。", "primary_collocate": null, "pronunciation": "fēng suǒ", "ipa": "fɤŋ˥ suɔ˨˩", "syllable_count": 2, "sentences": [{"text": "大雪封锁了山路，车开不过去。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察封锁了路口，谁也不能进去。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故发生后，警方马上封锁了那段公路。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "倒下的大树封锁了小路。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水封锁了回村的路，我们只能等着。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把桥封锁了，行人都得绕路。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人封锁着这条街，正在修路。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，公园把东门封锁了。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天他们封锁了这条路两个小时。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾封锁了高速公路，很多车停在路边。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封锁了", "label": "体标"}, {"form": "封锁着", "label": "体标"}, {"form": "封锁过", "label": "体标"}, {"form": "封锁线", "label": "复合"}], "register": "中性", "sense_fingerprint": "把道路、路口、现场堵住，使人和车无法通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd4150c-a1b6-4a5e-a02d-612dc66104b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修整", "is_correct": false, "explanation": "语义：“修整”指修好、整理，与“车开不过去”的结果矛盾，句子不通。"}, {"text": "封锁", "is_correct": true, "explanation": "正确：“封锁”指把路堵住，所以车开不过去，与句意一致。"}, {"text": "祝愿", "is_correct": false, "explanation": "搭配：“祝愿”的对象是人或事情，不能说祝愿山路。"}, {"text": "修筑", "is_correct": false, "explanation": "语义：“修筑”的施事是人，大雪不能修筑山路。"}], "explanations": {"修整": "语义：“修整”指修好、整理，与“车开不过去”的结果矛盾，句子不通。", "封锁": "正确：“封锁”指把路堵住，所以车开不过去，与句意一致。", "祝愿": "搭配：“祝愿”的对象是人或事情，不能说祝愿山路。", "修筑": "语义：“修筑”的施事是人，大雪不能修筑山路。"}, "sentence_index": 0, "correct_answer": "封锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司封锁了那位员工，让他回家。", "explanation": "这里应该用〈辞退〉。“封锁”的对象是通道或区域，不能用于人。"}, {"text": "警察封锁了这场打架，把两个人带走了。", "explanation": "这里应该用〈制止〉。“封锁”的对象是通道或区域，不能用于打架这类事件。"}, {"text": "妈妈封锁了窗户，怕冷风进来。", "explanation": "这里应该用〈关上〉。“封锁”指用强力封住通道，不用于日常关窗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏，与“正在修路”不协调，句子说不通。"}, {"text": "封锁", "is_correct": true, "explanation": "正确：“封锁”指把街道堵住，与“正在修路”的情境相符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题、意见，不能说讨论这条街。"}, {"text": "追问", "is_correct": false, "explanation": "搭配：“追问”的对象是人或问题，不能用于街道。"}], "explanations": {"欣赏": "语义：“欣赏”指赞赏，与“正在修路”不协调，句子说不通。", "封锁": "正确：“封锁”指把街道堵住，与“正在修路”的情境相符。", "讨论": "搭配：“讨论”的对象是问题、意见，不能说讨论这条街。", "追问": "搭配：“追问”的对象是人或问题，不能用于街道。"}, "sentence_index": 6, "correct_answer": "封锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗帘封锁了阳光，屋里暗了下来。", "explanation": "这里应该用〈遮挡〉。“封锁”的对象是道路、港口等通道，不能用于阳光。"}, {"text": "我们封锁了博物馆，待了一整天。", "explanation": "这里应该用〈参观〉。“封锁”指封住通道或区域，不用于参观场所。"}, {"text": "老师封锁了那个座位，不让别人坐。", "explanation": "这里应该用〈占用〉。“封锁”指封住道路等通道，不用于座位；把座位占下、不让别人坐，要用“占用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人封锁了了这条山路，车开不过去。", "corrected_sentence": "工人封锁了这条山路，车开不过去。", "error_description": "“了”重复：动词后只能带一个“了”，“封锁了了”不合语法，应为“封锁了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人封锁了着这段路，正在修桥。", "corrected_sentence": "工人封锁着这段路，正在修桥。", "error_description": "“封锁”后不能同时带“了”和“着”，“了着”连用不合语法。正确说法是“工人封锁着这段路”，表示持续的状态，错误在于“了着”连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
