INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用强力或其他手段封闭，使对外联系中断。", "primary_collocate": null, "pronunciation": "fēng suǒ", "ipa": "fɤŋ˥ suɔ˨˩", "syllable_count": 2, "sentences": [{"text": "军队封锁了通往城里的所有港口。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人封锁了边境，外面的人进不来。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想封锁消息，不让记者知道。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家封锁海面已经三个月了。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察封锁了整个小岛，没有船能出去。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争期间，敌人封锁着这座城市。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方封锁了我们的网络，我们联系不上总部。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把村子封锁起来，不让外人进出。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府没有封锁边界，两国人员还能往来。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人封锁海面后，岛上缺少粮食和药。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封锁了", "label": "体标"}, {"form": "封锁着", "label": "体标"}, {"form": "封锁过", "label": "体标"}, {"form": "封锁线", "label": "复合"}], "register": "书面", "sense_fingerprint": "用强力封闭港口、边境、消息等，使内外联系中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd4150c-a1b6-4a5e-a02d-612dc66104b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”的对象是人，不能说祝福港口。"}, {"text": "封锁", "is_correct": true, "explanation": "正确：“封锁”指用强力封住港口，使对外联系中断，与句中的“军队”相符。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指刷墙面，用于港口句意不通。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”后接活动或集体，不能接港口。"}], "explanations": {"祝福": "搭配：“祝福”的对象是人，不能说祝福港口。", "封锁": "正确：“封锁”指用强力封住港口，使对外联系中断，与句中的“军队”相符。", "粉刷": "语义：“粉刷”指刷墙面，用于港口句意不通。", "参加": "配价：“参加”后接活动或集体，不能接港口。"}, "sentence_index": 0, "correct_answer": "封锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震封锁了电线，附近停了电。", "explanation": "这里应该用〈切断〉。“封锁”用于港口、边境、道路等通道，不用于电线这类设施。"}, {"text": "海关封锁了那批货物，要等检查完才能取走。", "explanation": "这里应该用〈扣押〉。“封锁”指封住道路、港口等通道，不用于扣下货物。"}, {"text": "医生封锁了那个病人，不让他接触别人。", "explanation": "这里应该用〈隔离〉。“封锁”的对象是通道或区域，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维修", "is_correct": false, "explanation": "语义：“维修”是把设备修好，与“联系不上总部”的结果相反，句意不通。"}, {"text": "封锁", "is_correct": true, "explanation": "正确：“封锁”使网络中断，正好导致“联系不上总部”。"}, {"text": "检测", "is_correct": false, "explanation": "语义：“检测”是检查功能，不会导致“联系不上总部”。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”用于人或成就，不能接“网络”。"}], "explanations": {"维修": "语义：“维修”是把设备修好，与“联系不上总部”的结果相反，句意不通。", "封锁": "正确：“封锁”使网络中断，正好导致“联系不上总部”。", "检测": "语义：“检测”是检查功能，不会导致“联系不上总部”。", "祝贺": "搭配：“祝贺”用于人或成就，不能接“网络”。"}, "sentence_index": 6, "correct_answer": "封锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵封锁了那只小狗，怕它跑出去。", "explanation": "这里应该用〈关住〉。“封锁”的对象是道路、港口等通道，不能用于动物。"}, {"text": "大树封锁了阳光，屋里暗了下来。", "explanation": "这里应该用〈遮挡〉。“封锁”的对象是道路、港口等通道，不能用于阳光。"}, {"text": "他封锁了钱包，没人能找到它。", "explanation": "这里应该用〈隐藏〉。“封锁”指封住通道，不用于藏东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敌人封锁着了这座港口，外面的船进不来。", "corrected_sentence": "敌人封锁了这座港口，外面的船进不来。", "error_description": "表示已经完成的动作时，“封锁”应带“了”，不能与“着”连用。正确说法是“敌人封锁了这座港口”，错误在于“着了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们封锁了了这座港口，外界的船进不来。", "corrected_sentence": "他们封锁了这座港口，外界的船进不来。", "error_description": "“了”重复：动词后只能带一个“了”，“封锁了了”不合语法，应为“封锁了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88e85394-3196-432d-b8dc-b046576e6b13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
