INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专题是只讲一件事情的一个题目。", "primary_collocate": null, "pronunciation": "zhuān tí", "ipa": "ʈʂwan⁵⁵ tʰi³⁵", "syllable_count": 2, "sentences": [{"text": "杂志这期的专题是旅行。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们换一个专题，谈谈音乐吧。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专题只讲一件事，就是睡眠。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台做了一个关于水的专题。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一周每天讲一个专题。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专题很短，十分钟就讲完了。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢看科学方面的专题。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个专题都有自己的小标题。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请选一个你熟悉的专题发言。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这期专题介绍了中国茶。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "专题报道", "label": "复合"}, {"form": "专题节目", "label": "复合"}], "register": "中性", "sense_fingerprint": "只围绕一件事来讲的一个题目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专题", "is_correct": true, "explanation": "正确。“杂志这期的专题”指这期围绕一件事的内容，“是旅行”说得通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指价钱，“杂志这期的价格是旅行”说不通。"}, {"text": "编辑", "is_correct": false, "explanation": "语义：“编辑”指人，不能是“旅行”这样的内容。"}, {"text": "页数", "is_correct": false, "explanation": "语义：“页数”指纸张的张数，“杂志这期的页数是旅行”说不通。"}], "explanations": {"专题": "正确。“杂志这期的专题”指这期围绕一件事的内容，“是旅行”说得通。", "价格": "语义：“价格”指价钱，“杂志这期的价格是旅行”说不通。", "编辑": "语义：“编辑”指人，不能是“旅行”这样的内容。", "页数": "语义：“页数”指纸张的张数，“杂志这期的页数是旅行”说不通。"}, "sentence_index": 0, "correct_answer": "专题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的专题很美。", "explanation": "这里应该用〈题目〉。诗有自己的名字，叫“题目”，“专题”指只讲一件事的内容安排，不用来称诗的名字。"}, {"text": "这张桌子的专题很结实。", "explanation": "这里应该用〈材质〉。桌子的用料叫“材质”，“专题”指只讲一件事的题目，不指物品的质地。"}, {"text": "这篇论文的专题很有说服力。", "explanation": "这里应该用〈论点〉。论文的观点叫“论点”，“专题”指只讲一件事的题目，不用来说是否有说服力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专题", "is_correct": true, "explanation": "正确。“看科学方面的专题”指阅读围绕科学一件事的节目或文章。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格，不是可以阅读或观看的对象，与“科学方面”不搭。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”可带“节目”“文章”，“看味道”搭配不当。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是收入，“喜欢看科学方面的工资”说不通。"}], "explanations": {"专题": "正确。“看科学方面的专题”指阅读围绕科学一件事的节目或文章。", "脾气": "语义：“脾气”指性格，不是可以阅读或观看的对象，与“科学方面”不搭。", "味道": "搭配：“看”可带“节目”“文章”，“看味道”搭配不当。", "工资": "语义：“工资”是收入，“喜欢看科学方面的工资”说不通。"}, "sentence_index": 6, "correct_answer": "专题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的专题是爱情。", "explanation": "这里应该用〈题材〉。电影的题材指作品写的内容范围，“专题”不用于说电影的内容。"}, {"text": "这家餐厅的专题很好吃。", "explanation": "这里应该用〈招牌菜〉。餐厅的主打菜叫“招牌菜”，“专题”指只讲一件事的题目，不指食物。"}, {"text": "这家公司的专题是赚钱。", "explanation": "这里应该用〈宗旨〉。公司的根本目标叫“宗旨”，“专题”指只讲一件事的题目，不指公司的目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班这次做了一件专题。", "corrected_sentence": "我们班这次做了一个专题。", "error_description": "错误在量词：“件”用于衣物、物品，“专题”应用量词“个”。应说“一个专题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些专题们都很有意思。", "corrected_sentence": "这些专题都很有意思。", "error_description": "错误在复数标记：“们”只加在指人的名词后，“专题”指事物，不能说“专题们”。应说“这些专题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
