INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专门研究或讨论的题目。", "primary_collocate": null, "pronunciation": "zhuān tí", "ipa": "ʈʂwan⁵⁵ tʰi³⁵", "syllable_count": 2, "sentences": [{"text": "这次会议的专题是环境保护。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个小组布置了一个专题。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专题我们已经讨论了两个星期。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她选了饮食文化作为研究专题。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下节课的专题是中国古代历史。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专题太大，一节课讲不完。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家先准备好自己的专题。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为这个专题查了很多资料。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本周论坛的专题与健康有关。", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想好论文的专题了吗？", "target_word": "专题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "专题研究", "label": "复合"}, {"form": "专题讲座", "label": "复合"}], "register": "中性", "sense_fingerprint": "专门拿来研究或讨论的题目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7018439-109a-4c8c-8d0d-ce7e3899b663') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专题", "is_correct": true, "explanation": "正确。“专题”作“是”的主语，指会议要讨论的题目，与“环境保护”相合。"}, {"text": "嘉宾", "is_correct": false, "explanation": "语义：“嘉宾”指受邀的人，“这次会议的嘉宾是环境保护”说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时段，不能等同于“环境保护”这样的主题。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”指场所，“这次会议的地点是环境保护”说不通。"}], "explanations": {"专题": "正确。“专题”作“是”的主语，指会议要讨论的题目，与“环境保护”相合。", "嘉宾": "语义：“嘉宾”指受邀的人，“这次会议的嘉宾是环境保护”说不通。", "时间": "语义：“时间”指时段，不能等同于“环境保护”这样的主题。", "地点": "语义：“地点”指场所，“这次会议的地点是环境保护”说不通。"}, "sentence_index": 0, "correct_answer": "专题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的专题很结实。", "explanation": "这里应该用〈材质〉。椅子的用料叫“材质”，“专题”指专门研究或讨论的题目，不指物品的质地。"}, {"text": "这篇文章的专题很长。", "explanation": "这里应该用〈标题〉。单篇文章的名字叫“标题”，“专题”指专门研究或讨论的题目，不说“很长”。"}, {"text": "这首歌的专题很感人。", "explanation": "这里应该用〈歌词〉。歌曲的文字叫“歌词”，“专题”指专门研究或讨论的题目，不用来说歌曲的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专题", "is_correct": true, "explanation": "正确。“准备好自己的专题”指备好要讲或要研究的题目。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不能被“准备好”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“准备”可带“材料”“行李”，“天气”不能被准备。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，不能被“准备好”。"}], "explanations": {"专题": "正确。“准备好自己的专题”指备好要讲或要研究的题目。", "体重": "语义：“体重”是身体的重量，不能被“准备好”。", "天气": "搭配：“准备”可带“材料”“行李”，“天气”不能被准备。", "年龄": "语义：“年龄”是人的岁数，不能被“准备好”。"}, "sentence_index": 6, "correct_answer": "专题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的专题是红色。", "explanation": "这里应该用〈颜色〉。衣服的色彩叫“颜色”，“专题”指专门研究或讨论的题目，不指物品的颜色。"}, {"text": "这幅画的专题是春天。", "explanation": "这里应该用〈主题〉。画作表达的中心思想叫“主题”，“专题”不指作品的中心思想。"}, {"text": "这家公司的专题是赚钱。", "explanation": "这里应该用〈宗旨〉。公司的根本目标叫“宗旨”，“专题”指研究或讨论的题目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这学期我们研究了一本专题。", "corrected_sentence": "这学期我们研究了一个专题。", "error_description": "错误在量词：“本”用于书籍、杂志，不能修饰“专题”。应说“一个专题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些专题们我们都要认真准备。", "corrected_sentence": "这些专题我们都要认真准备。", "error_description": "错误在复数标记：“们”只加在指人的名词后，“专题”指事物，不能说“专题们”。应说“这些专题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '093b16e4-030e-40ed-8cbe-9fc7fc0231ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
