INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "尸体是人或动物死了以后留下的身体。", "primary_collocate": null, "pronunciation": "shī tǐ", "ipa": "ʂɻ̩⁵⁵ tʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "河里漂着一具男人的尸体。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们在山下找到了他的尸体。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田里发现了一只羊的尸体。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这具尸体已经放了三天。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把尸体从水里拉了上来。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要对尸体做检查。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里有很多尸体，我不敢看。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不敢看地上的尸体。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那棵树下埋着一具尸体。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尸体旁边有一把刀。", "target_word": "尸体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一具尸体", "label": "量词"}], "register": "中性", "sense_fingerprint": "人或动物死了以后留下的身体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2247d90f-0ad5-44a6-82f3-355e9a0b1ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92795, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尸体", "is_correct": true, "explanation": "尸体指死去的人或动物的身体，是正确答案。"}, {"text": "实体", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，实体指实在的物质，不是尸体。"}, {"text": "试题", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，tí（第二声）与 tǐ（第三声）声调也不同，试题指考试的题目。"}, {"text": "施礼", "is_correct": false, "explanation": "shī 相同，lǐ 与 tǐ 声母不同（l 与 t），施礼指行礼致意。"}], "explanations": {"尸体": "尸体指死去的人或动物的身体，是正确答案。", "实体": "shí（第二声）与 shī（第一声）声调不同，实体指实在的物质，不是尸体。", "试题": "shì（第四声）与 shī（第一声）声调不同，tí（第二声）与 tǐ（第三声）声调也不同，试题指考试的题目。", "施礼": "shī 相同，lǐ 与 tǐ 声母不同（l 与 t），施礼指行礼致意。"}, "sentence_index": null, "correct_answer": "尸体"}, "level_3": {"options": [{"text": "尸体", "is_correct": true, "explanation": "尸体指死去的身体，与“河里漂着”和“男人”的语境相符。"}, {"text": "机器", "is_correct": false, "explanation": "语义：“机器”不是男人的遗体，也不会作为一具东西漂在河里，与句意不符。"}, {"text": "人偶", "is_correct": false, "explanation": "语义：“人偶”是玩具，不是男人的遗体，与“漂着”的情境不符。"}, {"text": "模型", "is_correct": false, "explanation": "搭配：“男人的模型”与“河里漂着”搭配不当，漂着的应是真实的遗体。"}], "explanations": {"尸体": "尸体指死去的身体，与“河里漂着”和“男人”的语境相符。", "机器": "语义：“机器”不是男人的遗体，也不会作为一具东西漂在河里，与句意不符。", "人偶": "语义：“人偶”是玩具，不是男人的遗体，与“漂着”的情境不符。", "模型": "搭配：“男人的模型”与“河里漂着”搭配不当，漂着的应是真实的遗体。"}, "sentence_index": 0, "correct_answer": "尸体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个运动员的尸体很结实。", "explanation": "这里应该用〈身体〉。“尸体”指死去的身体，不能用来形容活人的体格结实。"}, {"text": "一只人的尸体漂在河里。", "explanation": "这里应该用〈具〉。量词“只”不用于人的尸体，指人的遗体要用“具”。"}, {"text": "她的尸体很苗条。", "explanation": "这里应该用〈身材〉。“尸体”指死去的身体，不能用来形容活人身材苗条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92795, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尸体", "is_correct": true, "explanation": "尸体指死去的人或动物的身体，是正确答案。"}, {"text": "石梯", "is_correct": false, "explanation": "shí 与 shī 声调不同，tī（第一声）与 tǐ（第三声）声调也不同，石梯指石头砌成的台阶。"}, {"text": "失礼", "is_correct": false, "explanation": "shī 相同，lǐ 与 tǐ 声母不同（l 与 t），失礼指言行没有礼貌。"}, {"text": "诗题", "is_correct": false, "explanation": "shī 相同，tí（第二声）与 tǐ（第三声）声调不同，诗题指诗歌的标题。"}], "explanations": {"尸体": "尸体指死去的人或动物的身体，是正确答案。", "石梯": "shí 与 shī 声调不同，tī（第一声）与 tǐ（第三声）声调也不同，石梯指石头砌成的台阶。", "失礼": "shī 相同，lǐ 与 tǐ 声母不同（l 与 t），失礼指言行没有礼貌。", "诗题": "shī 相同，tí（第二声）与 tǐ（第三声）声调不同，诗题指诗歌的标题。"}, "sentence_index": null, "correct_answer": "尸体"}, "level_3": {"options": [{"text": "尸体", "is_correct": true, "explanation": "尸体指死去的身体，与“电影里有很多”和“我不敢看”的恐怖氛围相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”不会让人害怕到不敢看，与后句“我不敢看”的情绪矛盾。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：“鲜花”令人愉悦，不会让人不敢看，与后句的情绪不符。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“电影里有很多书包”与“我不敢看”搭配不当，恐怖场景不会用书包来描述。"}], "explanations": {"尸体": "尸体指死去的身体，与“电影里有很多”和“我不敢看”的恐怖氛围相符。", "蛋糕": "语义：“蛋糕”不会让人害怕到不敢看，与后句“我不敢看”的情绪矛盾。", "鲜花": "语义：“鲜花”令人愉悦，不会让人不敢看，与后句的情绪不符。", "书包": "搭配：“电影里有很多书包”与“我不敢看”搭配不当，恐怖场景不会用书包来描述。"}, "sentence_index": 6, "correct_answer": "尸体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天跑步锻炼尸体。", "explanation": "这里应该用〈身体〉。“尸体”指死去的身体，不能用来指活人锻炼的身体。"}, {"text": "一条人的尸体躺在床上。", "explanation": "这里应该用〈具〉。量词“条”用于细长的东西，指人的尸体要用“具”。"}, {"text": "热水澡能让尸体放松。", "explanation": "这里应该用〈身体〉。“尸体”指死去的身体，不能用来说活人的身体被热水澡放松。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖里漂着一只女人的尸体，警察已经赶到。", "corrected_sentence": "湖里漂着一具女人的尸体，警察已经赶到。", "error_description": "错误：“一只”，正确：“一具”。人的遗体应用量词“具”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民在地里挖出了两具的尸体，吓坏了。", "corrected_sentence": "农民在地里挖出了两具尸体，吓坏了。", "error_description": "错误：“两具的尸体”，正确：“两具尸体”。数量词与名词之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41b17ac9-90e3-47d7-bc08-ac64f78b44c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
