INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "平民是普通的人，不是国王或大官。", "primary_collocate": null, "pronunciation": "píng mín", "ipa": "pʰiŋ˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "他不是国王，只是一个平民。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个平民救了国王的命。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从前，这个平民住在小村子里。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王遇到了一个平民，问他路怎么走。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大官同一个平民坐在一起吃饭。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他本来是平民，后来成了大官。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王穿上旧衣服，装成平民的样子。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里的英雄是一个年轻的平民。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平民没有马，只能走路去城里。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在平民家里，从小就很努力。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "平民百姓", "label": "复合"}], "register": "书面语", "sense_fingerprint": "没有高贵身份的普通人，常与国王、大官相对，多见于故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，与“国王”对比后句意不通。"}, {"text": "平民", "is_correct": true, "explanation": "平民：没有高贵身份的普通人，与国王相对，句意通顺。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”不能与国王对比作身份，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：主语“他”不能指花园，“只是一个花园”不成立。"}], "explanations": {"石头": "语义：石头不是人，与“国王”对比后句意不通。", "平民": "平民：没有高贵身份的普通人，与国王相对，句意通顺。", "城市": "语义：“城市”不能与国王对比作身份，句意不通。", "花园": "搭配：主语“他”不能指花园，“只是一个花园”不成立。"}, "sentence_index": 0, "correct_answer": "平民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国王住在平民里，每天很开心。", "explanation": "“平民”指人，不指地方，不能说“住在平民里”。"}, {"text": "国王遇到了一座平民，问他路怎么走。", "explanation": "这里“平民”指人，量词“座”用于建筑、山等，不能用于人；指人应说〈个〉或〈位〉。"}, {"text": "那只狗是平民，很听话。", "explanation": "这里“平民”被误用来指动物，好像是〈普通〉的意思；“平民”是名词，只指没有高贵身份的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能装成……的样子，句意不通。"}, {"text": "平民", "is_correct": true, "explanation": "平民：没有高贵身份的普通人，穿旧衣服装成平民，句意通顺。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能装成……的样子，句意不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是人，不能装成……的样子，句意不通。"}], "explanations": {"桌子": "语义：桌子不是人，不能装成……的样子，句意不通。", "平民": "平民：没有高贵身份的普通人，穿旧衣服装成平民，句意通顺。", "月亮": "语义：月亮是天体，不能装成……的样子，句意不通。", "大海": "语义：大海不是人，不能装成……的样子，句意不通。"}, "sentence_index": 6, "correct_answer": "平民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的工作很平民，但很认真。", "explanation": "这里应该用〈平凡〉。“平民”是名词，指普通人；形容工作普通、不出众要用“平凡”。"}, {"text": "这栋平民很大，有三层楼。", "explanation": "这里“平民”被用成了〈房子〉的意思；“平民”指没有高贵身份的普通人，不指建筑。"}, {"text": "这位平民负责管理全国的财政，权力很大。", "explanation": "这里“平民”被用成了〈官员〉的意思；“平民”与官员相对，不能用来指管理财政的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他父亲一直是只平民。", "corrected_sentence": "他父亲一直是个平民。", "error_description": "“平民”指人，量词要用“个”，不用“只”（“只”多用于动物）。错误句用“只”修饰“平民”，应改为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他出生在一个非常平民家庭，从小就很努力。", "corrected_sentence": "他出生在一个平民家庭，从小就很努力。", "error_description": "错误只在“非常”一处：“平民”是名词，不能受程度副词“非常”修饰。删去“非常”，即为正确句“他出生在一个平民家庭，从小就很努力。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92798, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92798, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "普通老百姓；与官员、贵族相对。", "primary_collocate": null, "pronunciation": "píng mín", "ipa": "pʰiŋ˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "官员与平民在法律面前一样平等。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的贵族很有钱，平民却很穷。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贵族住大房子，平民只能住小房子。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去平民很难去大学读书。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位官员常常去看平民的生活。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平民生活不容易，每天都要工作。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府应该多为平民着想。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个时代，平民不能和贵族结婚。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平民穿的衣服比贵族简单得多。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平民的孩子也应该有机会读书。", "target_word": "平民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "平民百姓", "label": "复合"}], "register": "书面语", "sense_fingerprint": "普通老百姓这一社会群体，与官员、贵族等阶层相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能与官员并列在法律面前平等。"}, {"text": "平民", "is_correct": true, "explanation": "平民：普通老百姓，与官员相对，“在法律面前一样平等”相合。"}, {"text": "特权", "is_correct": false, "explanation": "搭配：“特权”不是人，不能与官员并列说“一样平等”。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不能与官员并列在法律面前平等，句意不通。"}], "explanations": {"石头": "语义：石头不是人，不能与官员并列在法律面前平等。", "平民": "平民：普通老百姓，与官员相对，“在法律面前一样平等”相合。", "特权": "搭配：“特权”不是人，不能与官员并列说“一样平等”。", "动物": "语义：动物不能与官员并列在法律面前平等，句意不通。"}, "sentence_index": 0, "correct_answer": "平民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工作很平民，没有特别之处。", "explanation": "这里应该用〈平凡〉。“平民”是名词，指普通老百姓；形容工作普通要用“平凡”。"}, {"text": "这个小镇里住着一个平民，他是州里的大官。", "explanation": "这里“平民”被用成了〈官员〉的意思；“平民”与官员相对，不能指大官。"}, {"text": "我每天去平民上班。", "explanation": "“平民”指人，不指地方，不能说“去平民上班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敌人", "is_correct": false, "explanation": "语义：政府为敌人着想，与“多为……着想”的意思矛盾。"}, {"text": "平民", "is_correct": true, "explanation": "平民：普通老百姓，政府应为之着想，句意通顺。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“为……着想”要求对象是人，“为机器着想”不成立。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：政府为垃圾着想，句意不通。"}], "explanations": {"敌人": "语义：政府为敌人着想，与“多为……着想”的意思矛盾。", "平民": "平民：普通老百姓，政府应为之着想，句意通顺。", "机器": "搭配：“为……着想”要求对象是人，“为机器着想”不成立。", "垃圾": "语义：政府为垃圾着想，句意不通。"}, "sentence_index": 6, "correct_answer": "平民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所大学是平民。", "explanation": "这里“平民”被用成了〈机构〉的意思；“平民”只指普通人，不指学校或单位。"}, {"text": "这个问题很平民，我们都解决不了。", "explanation": "这里“平民”被用成了〈简单〉的意思；“平民”指普通老百姓，不能用来形容问题。"}, {"text": "这位公主是平民，住在皇宫里。", "explanation": "这里“平民”被用成了〈贵族〉的意思；“平民”与贵族相对，公主是贵族，不能说是平民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个老人是一只平民，从来不爱说话。", "corrected_sentence": "那个老人是一位平民，从来不爱说话。", "error_description": "“平民”指人，修饰它的量词要用“位”或“个”，不能用“只”。错误句用“只”，应改为“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很平民，从来没做过官。", "corrected_sentence": "他是一个平民，从来没做过官。", "error_description": "“平民”是名词，前面不能加程度副词“很”。错误句说“一个很平民”，应去掉“很”，说“一个平民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92799, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92799, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92799, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "操控是用手去管一个东西，让它照你想的动。", "primary_collocate": null, "pronunciation": "cāo kòng", "ipa": "tsʰau˥ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他用手柄操控游戏里的小人。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友正在操控着一辆玩具车。", "target_word": "操控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会操控这台机器，你来吧。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用手机操控家里的灯。", "target_word": "操控", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这架无人机很容易操控。", "target_word": "操控", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开车时，他双手操控方向盘。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷操控过很多种老机器。", "target_word": "操控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个遥控器可以操控远处的小车。", "target_word": "操控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子操控机器人走了过来。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他慢慢学会了操控这辆小船。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "操控了", "label": "体标"}, {"form": "操控着", "label": "体标"}, {"form": "操控过", "label": "体标"}, {"form": "操控杆", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手操作机器、玩具等，让它按自己的想法活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操控", "is_correct": true, "explanation": "操控：用手使游戏角色按自己的意思动，与“手柄”“游戏里的小人”相符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，与用手柄无关，游戏里的小人也不能被清洗。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象要吃东西，不能说喂游戏里的小人。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指用针线连接布料，与手柄和游戏无关。"}], "explanations": {"操控": "操控：用手使游戏角色按自己的意思动，与“手柄”“游戏里的小人”相符。", "洗": "语义：“洗”指清洗，与用手柄无关，游戏里的小人也不能被清洗。", "喂": "搭配：“喂”的对象要吃东西，不能说喂游戏里的小人。", "缝": "语义：“缝”指用针线连接布料，与手柄和游戏无关。"}, "sentence_index": 0, "correct_answer": "操控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他操控着一碗汤走过来。", "explanation": "这里应该用〈端〉。操控指用手使机器、玩具等按自己的意思活动，端汤不是操控。"}, {"text": "他操控着栏杆慢慢下楼。", "explanation": "这里应该用〈扶〉。操控的对象是能按意愿运转的机器或玩具，栏杆不能被操控。"}, {"text": "她操控着书读了一会儿。", "explanation": "这里应该用〈拿〉。操控针对能按意愿运转的机器或玩具，拿书读不属于操控。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操控", "is_correct": true, "explanation": "操控：指用手使机器按自己的意思运转，“操控过”表示曾经操作过老机器。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能与“老机器”搭配，句义不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与“老机器”无关，句子不通。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象多是食物，不能说烤老机器。"}], "explanations": {"操控": "操控：指用手使机器按自己的意思运转，“操控过”表示曾经操作过老机器。", "吃": "语义：“吃”指进食，不能与“老机器”搭配，句义不通。", "唱": "语义：“唱”指发声演唱，与“老机器”无关，句子不通。", "烤": "搭配：“烤”的对象多是食物，不能说烤老机器。"}, "sentence_index": 6, "correct_answer": "操控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子操控着那辆玩具车跑过来。", "explanation": "操控的施动者必须是人，椅子不能操控玩具车；应改用人作主语，如“他操控着那辆玩具车跑过来”。"}, {"text": "这块石头操控着小船向前漂。", "explanation": "操控的施动者必须是人，石头不能操控小船；应改用人作主语，如“他操控着小船向前开”。"}, {"text": "这只杯子操控着那辆遥控车。", "explanation": "操控的施动者必须是人，杯子不能操控遥控车；应改用人作主语，如“他操控着那辆遥控车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我操控了过这架无人机。", "corrected_sentence": "我操控过这架无人机。", "error_description": "错误在“过”前多加了“了”。表示曾经操控时用“操控过”，“了”和“过”不能同时用在动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他慢慢操控了很好。", "corrected_sentence": "他慢慢操控得很好。", "error_description": "“了”不能引出“很好”这类程度补语，应把“了”换成“得”，说“操控得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
