INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92800, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "操纵并控制，使其按意愿运转或行动。", "primary_collocate": null, "pronunciation": "cāo kòng", "ipa": "tsʰau˥ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "有人试图操控舆论。", "target_word": "操控", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "少数公司操控着这个市场。", "target_word": "操控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方怀疑有人暗中操控股价。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "幕后有人操控着整个计划。", "target_word": "操控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想操控原材料的价格。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不愿让别人操控自己的命运。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络谣言可能操控公众的情绪。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "操控比赛结果是违法的。", "target_word": "操控", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们长期操控着当地的媒体。", "target_word": "操控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人雇水军操控网上的热门话题。", "target_word": "操控", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "操控了", "label": "体标"}, {"form": "操控着", "label": "体标"}, {"form": "操控过", "label": "体标"}, {"form": "操控杆", "label": "复合"}], "register": "书面", "sense_fingerprint": "暗中或有意地操纵、控制舆论、市场等，使其按自己的意愿发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78c39e31-92d1-407d-a2da-901a9781bb50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操控", "is_correct": true, "explanation": "操控：暗中或有意地操纵舆论，与“试图”的意图相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用来表示影响舆论。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”多接道路、机器等，不能说修舆论。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指用针线连接布料，与舆论无关。"}], "explanations": {"操控": "操控：暗中或有意地操纵舆论，与“试图”的意图相符。", "吃": "语义：“吃”指进食，不能用来表示影响舆论。", "修": "搭配：“修”多接道路、机器等，不能说修舆论。", "缝": "语义：“缝”指用针线连接布料，与舆论无关。"}, "sentence_index": 0, "correct_answer": "操控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快操控了这道数学题。", "explanation": "这里应该用〈解〉。操控指有意操纵、控制使其按意愿运转，数学题只能被解答，不能被操控。"}, {"text": "这块石头操控了整个计划。", "explanation": "这里应该用〈影响〉。操控的主体应是有意图的人或组织，石头不能操控计划，这里只是客观作用，应说〈影响〉。"}, {"text": "他操控了一杯茶。", "explanation": "这里应该用〈端〉。操控指有意操纵或控制事物使其运转或行动，茶只能被端、拿，不能被操控。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操控", "is_correct": true, "explanation": "操控：暗中影响、支配公众的情绪，与句义相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，与情绪无关。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”多接植物、火等，不能说浇公众的情绪。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，不能用于表示影响情绪。"}], "explanations": {"操控": "操控：暗中影响、支配公众的情绪，与句义相符。", "煮": "语义：“煮”指用水加热食物，与情绪无关。", "浇": "搭配：“浇”多接植物、火等，不能说浇公众的情绪。", "唱": "语义：“唱”指发声演唱，不能用于表示影响情绪。"}, "sentence_index": 6, "correct_answer": "操控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我非常操控这位老师。", "explanation": "这里应该用〈尊敬〉。操控指有意操纵、控制，不表示对人的感情态度，表达敬意应说〈尊敬〉。"}, {"text": "他操控了整个夏天的阳光。", "explanation": "这里应该用〈享受〉。操控指操纵、控制使其运转或行动，阳光不能被操控，表示享受阳光应说〈享受〉。"}, {"text": "我操控他的勇气。", "explanation": "这里应该用〈敬佩〉。操控指有意操纵、控制，不能用于对他人品质的赞赏，表示佩服应说〈敬佩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他暗中操控得股价。", "corrected_sentence": "他暗中操控股价。", "error_description": "“操控”后直接接宾语“股价”，不能插入“得”。“得”引出补语，此处应去掉“得”，说“他暗中操控股价”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们长期操控了过当地的媒体。", "corrected_sentence": "他们长期操控过当地的媒体。", "error_description": "错误在“过”前多加了“了”。表示曾经操控时用“操控过”，“了”和“过”不能同时用在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f75b68db-b5d9-497b-a135-8666a53b5245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
