INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92801, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "干嘛是问你要做什么。", "primary_collocate": null, "pronunciation": "gàn má", "ipa": "kan˥˩ ma˧˥", "syllable_count": 2, "sentences": [{"text": "喂，你现在在干嘛呢？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末你打算干嘛？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么晚了，你还在外面干嘛？", "target_word": "干嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们三个人坐在这里，是要干嘛？", "target_word": "干嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放假了，你准备干嘛？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你拿着剪刀要干嘛？", "target_word": "干嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以后你们都去干嘛了？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天下班后一般干嘛？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你一个人在厨房干嘛？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天是星期天，你们想干嘛？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "幹嘛", "label": "繁体"}], "register": "口语", "sense_fingerprint": "干嘛：口语疑问代词，相当于“做什么”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a80d1613-ad74-4c77-841d-4a5ae0d1a4c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干嘛", "is_correct": true, "explanation": "“干嘛”问正在做什么，与“你现在在……呢”的句式和语境相符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问的是人，而句子问的是正在做的事。"}, {"text": "怎样", "is_correct": false, "explanation": "配价：“在”后要接地点或动作，“在怎样呢”不成句。"}, {"text": "什么", "is_correct": false, "explanation": "配价：“在什么呢”后缺少动词，不成立。"}], "explanations": {"干嘛": "“干嘛”问正在做什么，与“你现在在……呢”的句式和语境相符。", "谁": "语义：“谁”问的是人，而句子问的是正在做的事。", "怎样": "配价：“在”后要接地点或动作，“在怎样呢”不成句。", "什么": "配价：“在什么呢”后缺少动词，不成立。"}, "sentence_index": 0, "correct_answer": "干嘛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我干嘛了三个小时的作业。", "explanation": "这里应该用〈做〉。“干嘛”是疑问词，只用于询问要做什么，不能用来陈述已经做了什么，应说“做了三个小时的作业”。"}, {"text": "他干嘛了很多年的老师。", "explanation": "这里应该用〈当〉。“干嘛”不能表示担任某种职务，应说“当了很多年的老师”。"}, {"text": "他干嘛了一幅很好的画。", "explanation": "这里应该用〈创作〉。“干嘛”不能表示创作艺术作品，应说“创作了一幅很好的画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干嘛", "is_correct": true, "explanation": "“干嘛”问要去做什么，与“去……了”的句式相符。"}, {"text": "多少", "is_correct": false, "explanation": "配价：“多少”问数量，“去”后要接地点或事情，“去多少了”不成立。"}, {"text": "几", "is_correct": false, "explanation": "配价：“几”问数量，“去”后要接地点或事情，“去几了”不成立。"}, {"text": "为什么", "is_correct": false, "explanation": "语义：“为什么”问原因，不能用来表示去的地点或活动。"}], "explanations": {"干嘛": "“干嘛”问要去做什么，与“去……了”的句式相符。", "多少": "配价：“多少”问数量，“去”后要接地点或事情，“去多少了”不成立。", "几": "配价：“几”问数量，“去”后要接地点或事情，“去几了”不成立。", "为什么": "语义：“为什么”问原因，不能用来表示去的地点或活动。"}, "sentence_index": 6, "correct_answer": "干嘛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位老人干嘛了一辈子的农活。", "explanation": "这里应该用〈干〉。“干嘛”是疑问词，不能表示从事劳动，应说“干了一辈子的农活”。"}, {"text": "下午的报告他干嘛了三个小时。", "explanation": "这里应该用〈讲〉。“干嘛”不能表示讲报告，应说“讲了三个小时的报告”。"}, {"text": "他干嘛了这样的决定。", "explanation": "这里应该用〈作出〉。“干嘛”不能表示作出决定，应说“作出这样的决定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末你们在干嘛什么呢？", "corrected_sentence": "周末你们在干嘛呢？", "error_description": "疑问词重复：“干嘛”与“什么”都是疑问词，同一问句中只用一个，应说“在干嘛呢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们这会儿在干嘛吗？", "corrected_sentence": "你们这会儿在干嘛呢？", "error_description": "语气词错误：带疑问代词“干嘛”的问句不用“吗”，应说“在干嘛呢”，不能说“在干嘛吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
