INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92802, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "口语，询问原因，相当于“为什么”。", "primary_collocate": null, "pronunciation": "gàn má", "ipa": "kan˥˩ ma˧˥", "syllable_count": 2, "sentences": [{"text": "你干嘛哭？谁欺负你了？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他干嘛不来开会？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你干嘛这么生气？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干嘛要买这么贵的手机？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气这么好，咱们干嘛待在家里？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你干嘛一直看着我？", "target_word": "干嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他干嘛不告诉我实话？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这点小事，干嘛那么紧张？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你干嘛把灯关了？", "target_word": "干嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干嘛不早点说呢？", "target_word": "干嘛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "幹嘛", "label": "繁体"}], "register": "口语", "sense_fingerprint": "干嘛：口语疑问副词，放在动词前，相当于“为什么”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a80d1613-ad74-4c77-841d-4a5ae0d1a4c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干嘛", "is_correct": true, "explanation": "“干嘛”在这里表示“为什么”，放在动词“哭”前，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "搭配：副词“很”不修饰动作动词，“很哭”不说。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”不直接修饰动作动词，“太哭”不成立。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不修饰“哭”这类动作动词，“非常哭”不成立。"}], "explanations": {"干嘛": "“干嘛”在这里表示“为什么”，放在动词“哭”前，符合句意。", "很": "搭配：副词“很”不修饰动作动词，“很哭”不说。", "太": "搭配：“太”不直接修饰动作动词，“太哭”不成立。", "非常": "搭配：“非常”修饰形容词或心理动词，不修饰“哭”这类动作动词，“非常哭”不成立。"}, "sentence_index": 0, "correct_answer": "干嘛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一天干嘛了十个小时的活。", "explanation": "这里应该用〈工作〉。“干嘛”不能表示劳动，应说“工作了十个小时”。"}, {"text": "我昨天干嘛了一份很好的报告。", "explanation": "这里应该用〈写〉。“干嘛”不能表示完成具体的写作动作，应说“写了一份很好的报告”。"}, {"text": "这次比赛他干嘛了第一名。", "explanation": "这里应该用〈获得〉。“干嘛”不能表示取得名次，应说“获得了第一名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干嘛", "is_correct": true, "explanation": "“干嘛”表示“为什么”，放在“不告诉”前，询问对方不说实话的原因，符合句意。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”强调本人动手去做，与“不告诉我实话”的否定语境不合，句意说不通。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即刻发生，与“不告诉”所表达的持续态度不合。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙去做，与“不告诉我实话”的态度相悖，句意不通。"}], "explanations": {"干嘛": "“干嘛”表示“为什么”，放在“不告诉”前，询问对方不说实话的原因，符合句意。", "亲自": "语义：“亲自”强调本人动手去做，与“不告诉我实话”的否定语境不合，句意说不通。", "马上": "语义：“马上”表示即刻发生，与“不告诉”所表达的持续态度不合。", "赶紧": "语义：“赶紧”表示急忙去做，与“不告诉我实话”的态度相悖，句意不通。"}, "sentence_index": 6, "correct_answer": "干嘛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天干嘛了一下午的书。", "explanation": "这里应该用〈读〉。“干嘛”不能表示阅读，应说“读了一下午的书”。"}, {"text": "这台机器干嘛了三年。", "explanation": "这里应该用〈运行〉。“干嘛”不能表示机器运转，应说“运行了三年”。"}, {"text": "他干嘛了一个好的决定。", "explanation": "这里应该用〈作出〉。“干嘛”不能表示作出决定，应说“作出了一个好的决定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你干嘛不吃饭吗？", "corrected_sentence": "你干嘛不吃饭？", "error_description": "语气词多余：“干嘛”问句本身是疑问句，句末不能再加“吗”，应说“你干嘛不吃饭”，不能说“你干嘛不吃饭吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他干嘛为什么不回我的消息？", "corrected_sentence": "他干嘛不回我的消息？", "error_description": "疑问词重复：“干嘛”与“为什么”都表示原因，同一问句中只用一个，应说“他干嘛不回我的消息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba1235cd-9732-42dd-b546-8574580fca1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
