INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92803, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "支配是自己决定钱、时间等怎么用。", "primary_collocate": null, "pronunciation": "zhī pèi", "ipa": "ʈʂʅ˥ pʰei˥˩", "syllable_count": 2, "sentences": [{"text": "这笔钱你可以自己支配。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月的零花钱自己支配。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会支配自己的时间。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的时间由你自己支配。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我自己支配这五百块钱。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想怎么支配工资，是你的事。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要学会合理支配时间。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先支配一部分钱买书，再存起来。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一天的时间支配得很清楚。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期的生活费我已经支配好了。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支配着", "label": "体标（着）"}, {"form": "支配了", "label": "体标（了）"}, {"form": "支配过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "自己决定钱、时间等怎么使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支配", "is_correct": true, "explanation": "正确：「支配」指自己决定钱怎么用，与「自己」搭配，符合句意。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：「观看」的对象是画面、比赛等，不能带「这笔钱」作宾语。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：「呼吸」是不及物动词，不能带「这笔钱」作宾语。"}, {"text": "摇晃", "is_correct": false, "explanation": "语义：「摇晃」指晃动物体，与决定钱怎么用的意思不符。"}], "explanations": {"支配": "正确：「支配」指自己决定钱怎么用，与「自己」搭配，符合句意。", "观看": "搭配：「观看」的对象是画面、比赛等，不能带「这笔钱」作宾语。", "呼吸": "配价：「呼吸」是不及物动词，不能带「这笔钱」作宾语。", "摇晃": "语义：「摇晃」指晃动物体，与决定钱怎么用的意思不符。"}, "sentence_index": 0, "correct_answer": "支配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根柱子支配着整个屋顶。", "explanation": "这里应该用〈支撑〉。「支配」指自己决定钱或时间怎么用，不表示承受、撑住。"}, {"text": "我用手机支配了这个月的房租。", "explanation": "这里应该用〈支付〉。「支配」指决定钱怎么用，不表示付款这个动作。"}, {"text": "老师把座位支配给同学。", "explanation": "这里应该用〈分配〉。「支配」强调自己决定怎么用，不表示把东西分给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支配", "is_correct": true, "explanation": "正确：「支配」指决定时间怎么用，与「合理」搭配，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：「欣赏」的对象是风景、音乐等，不能用于时间。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」指修复器物，时间无法被修理。"}, {"text": "推开", "is_correct": false, "explanation": "语义：「推开」指用力使物体移开，与时间无关。"}], "explanations": {"支配": "正确：「支配」指决定时间怎么用，与「合理」搭配，符合句意。", "欣赏": "搭配：「欣赏」的对象是风景、音乐等，不能用于时间。", "修理": "语义：「修理」指修复器物，时间无法被修理。", "推开": "语义：「推开」指用力使物体移开，与时间无关。"}, "sentence_index": 6, "correct_answer": "支配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在餐厅支配了一份牛肉。", "explanation": "这里应该用〈点〉。「支配」指决定钱或时间怎么用，不表示在餐厅点菜。"}, {"text": "他在操场上支配了一会儿篮球。", "explanation": "这里应该用〈打〉。「支配」指决定钱或时间怎么用，不表示打球这种运动。"}, {"text": "我们在超市支配了账单。", "explanation": "这里应该用〈结算〉。「支配」指决定钱怎么用，不表示付清账款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔奖金我已经支配了好，准备买书。", "corrected_sentence": "这笔奖金我已经支配好了，准备买书。", "error_description": "错误：「支配了好」；正确：「支配好了」。结果补语「好」要紧跟动词，「了」放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把每个月的钱支配很合理。", "corrected_sentence": "她把每个月的钱支配得很合理。", "error_description": "错误：「支配很合理」；正确：「支配得很合理」。把字句中动词后带补语要用「得」，缺了「得」句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
