INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92804, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "安排、调度；对人或事物起主导控制作用。", "primary_collocate": null, "pronunciation": "zhī pèi", "ipa": "ʈʂʅ˥ pʰei˥˩", "syllable_count": 2, "sentences": [{"text": "经理支配着公司所有的人员。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长支配人手，大家都很听话。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想法支配着他的每一个行动。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板可以支配工人的工作时间。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感情常常支配人的行为。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司统一支配这些车辆。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的行为受思想支配。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货由仓库统一支配。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不应该支配你的生活。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的人手由王经理支配。", "target_word": "支配", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支配着", "label": "体标（着）"}, {"form": "支配了", "label": "体标（了）"}, {"form": "支配过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "安排调度人员，或控制、主导人的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '964c90de-6e63-4a08-9795-75c3d131a85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支配", "is_correct": true, "explanation": "正确：「支配」指主导、安排人员，与「公司所有的人员」搭配，符合句意。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：「歌唱」指唱歌，不能用来指主导或安排人员。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：「呼吸」是不及物动词，不能带「公司所有的人员」作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，不能带人作宾语。"}], "explanations": {"支配": "正确：「支配」指主导、安排人员，与「公司所有的人员」搭配，符合句意。", "歌唱": "语义：「歌唱」指唱歌，不能用来指主导或安排人员。", "呼吸": "配价：「呼吸」是不及物动词，不能带「公司所有的人员」作宾语。", "散步": "配价：「散步」是不及物动词，不能带人作宾语。"}, "sentence_index": 0, "correct_answer": "支配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姐姐支配难过的弟弟，轻轻拍着他的背。", "explanation": "这里应该用〈安慰〉。「支配」指安排或主导，不表示安抚别人的情绪。"}, {"text": "工人昨天支配了一整面墙。", "explanation": "这里应该用〈粉刷〉。「支配」指安排或主导，不表示涂刷墙面。"}, {"text": "老师支配了我的作文，很认真地写了评语。", "explanation": "这里应该用〈批改〉。「支配」指安排或主导，不表示看过作文后写评语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支配", "is_correct": true, "explanation": "正确：「支配」指主导、左右人的行为，「受……支配」是常用结构，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：「欣赏」的对象是艺术、风景，不能说「受思想欣赏」。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：「收藏」的对象是物品，不能说「受思想收藏」。"}, {"text": "修补", "is_correct": false, "explanation": "语义：「修补」指修理破损的东西，与行为受什么影响无关。"}], "explanations": {"支配": "正确：「支配」指主导、左右人的行为，「受……支配」是常用结构，符合句意。", "欣赏": "搭配：「欣赏」的对象是艺术、风景，不能说「受思想欣赏」。", "收藏": "搭配：「收藏」的对象是物品，不能说「受思想收藏」。", "修补": "语义：「修补」指修理破损的东西，与行为受什么影响无关。"}, "sentence_index": 6, "correct_answer": "支配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师支配了我，说我很棒。", "explanation": "这里应该用〈表扬〉。「支配」指安排或主导，不表示称赞别人。"}, {"text": "士兵支配命令。", "explanation": "这里应该用〈服从〉。「支配」表示主导、控制，不表示听从；士兵应当听从命令。"}, {"text": "他支配了老师的批评。", "explanation": "这里应该用〈接受〉。「支配」指主导或安排，不表示接受批评。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没有支配了过别人的时间。", "corrected_sentence": "他从来没有支配过别人的时间。", "error_description": "错误：「支配了过」；正确：「支配过」。「没有」否定经历时只用「过」，「了」和「过」不能同时用在「支配」后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂长支配了着全厂的生产。", "corrected_sentence": "厂长支配着全厂的生产。", "error_description": "错误：「支配了着」；正确：「支配着」。动态助词「了」和「着」不能同时用在一个动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f5f1d31-ca2a-49c7-8237-0c9588c31fa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
