INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "幻想是脑子里想一些不会真的发生的事。", "primary_collocate": null, "pronunciation": "huàn xiǎng", "ipa": "xwan˥˩ ɕjaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他总幻想自己一夜之间变成明星。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别再幻想了，天上不会掉馅饼。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我常幻想自己能在天上飞。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她幻想着有一天遇到白马王子。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟幻想过当超人去救全世界。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要整天幻想发大财，要努力工作。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他幻想自己是国王，住在很大的城堡里。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别幻想他会突然给你一大笔钱。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们幻想着坐火箭去月亮上玩。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了就幻想自己躺在海边，什么都不用做。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幻想着", "label": "体标"}, {"form": "幻想过", "label": "体标"}, {"form": "幻想了", "label": "体标"}], "register": "通用", "sense_fingerprint": "动词：在脑子里想不会真的发生的事，后面常接自己或想象的情景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37389423-afce-42fb-8c84-9ff544ce5cc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
